/* 平成28年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h28.committeeSessions.push(...[{"id":"h28-20160222-9","meetingId":"h28-cm02","date":"2016年2月22日","dateIso":"2016-02-22","committee":"文教委員会","time":"午前１０時００分～午後 ３時１９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を108件整理しています。","topics":[{"id":"topic-01","title":"第３８号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第３８号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"大もとがなぜ変わるのかというのと、あと、額というのはどこで誰がどう決めるのかなというのをちょっと。基準なんかがあって決められるのかというところをお伺いしたいと思います。","respondent":"野呂瀬学務課長","answer":"ですから、変わってくるということで、毎年毎年限度額が変わったらそれに準じて条例でやはり改正をしていくというものです。ちなみに、今までそういうのを受けたという実績はないのですけれども、毎年それに準じて変えているというものです。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、改正された新旧の対照表を見て、付則が多いというかわあーっと下についているのですけれども、これは改正されると必ずここも変わってくるという部分ということになるのか尋ねました。","respondent":"野呂瀬学務課長","answer":"全員上がっておりますので適用は平成２８年の４月１日ですので、例えば今年度あったとしても、それは従前の規定のとおりですよということです。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"どういう違いというか、その級で何がどう違うのかをちょっと伺いたいのと、分限のところ。降給のところで、これを要は実行というか施行されるとなると、どういうふうにして降給というふうに実施されていくのか、それをちょっと伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうですね。どういう事例が降給になるのか、伺いたいと思います。","respondent":"渋谷指導課長","answer":"１点目は、園長だったりというふうな業務執行の内容によって級が変わり、それに応じて給与の基準額が変わっているというふうなものです。今手元に資料がないのでわかりませんけれども、一つ一つの事例で判断して、その内容に応じて処分が決まってくるという内容のものです。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"降給させるには、誰が決めるのか。それで、これが濫用ではないけれども、濫用防止策、濫用される例があったりするのか、それを防止する策はあるのかをちょっと伺いたいなと思います。","respondent":"渋谷指導課長","answer":"任命権者が基本的にはその裁量を持っておりますけれども、基本的にどんな処分が出されたとしても異議申立て等をするような機会がきちんと設けられておりますので、いわゆる、今委員ご心配になるような濫用ということはないというふうに考えているところです。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"今の分限の処分のところなのですけれども、どういう経過があって。どういう経過でこういう項目が入るようになったのかということと、今までこれに値するような事例があったのかどうか、ちょっと説明を求めました。","respondent":"渋谷指導課長","answer":"これも、もともとこの人事委員会勧告に入ってきた経緯については私どももわからないのですけれども、分限処分そのものにつきましては、もとからあるものですので、特別改めてそのことによって新規にかかわるというようなことではないと考えています。","id":"exchange-006"}]},{"id":"topic-02","title":"第４１号議案、品川区いじめ防止対策推進条例","agenda":"第４１号議案、品川区いじめ防止対策推進条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして内容などもこういった内容にすべきだ、してほしいというような要望もさせていただいてきたのですけれども、ちょっと残念だなと感じています。ですので、このいじめの禁止で、いじめがなくなる、防止できるというふうに考えられているのか、改めて伺いたいと思うのですが。","respondent":"村尾教育総合支援センター長","answer":"１点目の条例の部分ですけれども、条文を受けた項目になることについてはご理解いただければと考えています。２つ目、第４条の「児童等は、改めて認識を高めるものであるというふうに私は考えているところです。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問","question":"だからこそ教訓を活かして、もっと広く区民に意見を聴取して、そして現場や団体からも声を聞いてつくるべき条例なのではないかなと思うのです。そういった部分で、今後さらに地域や団体の声を聞いていくという考えはあるのか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"ならびに教職員が、市民科だけでこのいじめの対策、いじめをなくしていくというだけの方法ではないと考えているところです。以前の答弁でもご案内したと思うのですけれども、議決事項ですので、この後それぞれ広くこの条例について意見を伺う等の計画はございません。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問","question":"お子さんからも伺いましたけれども、ではなぜ起きたのだと、こういったことが繰り返されて本当につらかったと私は聞きました。改めて、こういう状況がまだあるという中で、ちょっと見解を伺いたいなと思うのですが、いかがでしょう。","respondent":"村尾教育総合支援センター長","answer":"やはり今の現状から含めて、さまざまなそれぞれの今までのいただいた意見や考え方等を踏まえて、この条例をつくりあげてきたというような経緯です。いじめというものに対して、子どもたちへ防止、また根絶に向けて取り組んでいこうというような考えです。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これは子たちたちに対してどういう思いをさせるのかというのがちょっと足らない条例ではないかなとものすごく感じるのです。学校も地域も、そういった言葉は入っているのですけれども、守っていくという立場の条文にしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"今回、文科省のほうから平成２５年に出ている法、これに準拠するような形で品川ナイズされたと言えるのですけれども。どういう形で、どういう形で知っていただくというのでしょうか、説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"地域ということで、まず４月に新学年の保護者会がありますので、そこでやはりこの条例について説明をきちんとしていこうと。こういう条例ができましたということで説明をしたり、また青少年対策地区委員会等、また内容については説明を広げていこうと考えているところです。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"こういう、何というのでしょうか、個別の話の中でやっていただくというのが一番いいかなと思いますけれども。ただ、こういう条例があるということは多分お知らせすると思うのですけれども、どのような手段を講じられる予定なのか、説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"まさに今おっしゃったとおり、こういう条例ができましたということはより広く、学校関係だけではない保護者の方にも伝えていこうと考えています。","id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"その中に品川区としての平成２４年の出来事があったということで、品川区だからこそこういう文言を入れたというようなものがあれば教えてください。そういう時代になっているので、これはなかなか発見というのが非常に難しいと思うのですが、今後の取組みについて説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"先ほどご説明をさせていただきましたけれども、第９条、また関係機関等の役割ということを入れております。使う子どもたち自身の理解、認識というものを高めていくよう、今後も努めていこうと考えているところです。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"どういった検討を重ねてこの条文になったのか、まず１点お伺いしたいのと、あまりにも大きすぎる犠牲がこの中にどう活かされているのか。私はリアリティーがなくてはいけないなと思っているので、この教訓がどう活かされているのかという点、２点をお伺いいたします。","respondent":"村尾教育総合支援センター長","answer":"いわゆる教育委員会として設置する組織と、それから区長部局の第三者機関にどのような関係をしていくか等について検討を進めてまいりました。第１条からそれぞれ、文言の使い方や考え方等については、これまでもそれぞれ検討をお互いにしてきたということはあります。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"最初のほうなのですが、この作成にあたった方々の、参加をされた方の、特に職種というか、法律家とかそういった方がいらっしゃったのかどうか。この区長部局のところの関係を１点、あと、この２つの委員会の調査がどのように区議会のほうに報告されるのかをちょっとわかりやすく説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"もともと常設している委員会ではありますけれども、ここにこの調査実施を委任し、各学校におけるさまざまな調査を行ってまいります。設置してどのような対応をするかは、それから教育委員会のほうでそれぞれ調整をしながら進めていく、委員会のつながりになります。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"対策委員会の常設のところの調査の報告というのはどのようにされるのか１点と、弁護士とかがやはりきちんとこういうものには参加をしていただきたいなと思うので、その点がどうだったか説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"２点目につきましては、弁護士等の部分につきましては、特に弁護士の意見を求めたというものではございません。あくまでも、国のいじめ防止対策推進法に基づいて、どのような形で区としてこれをひもとくか、または位置づけるかという内容だけです。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"提案","question":"私たちとしては、やはり幾つか提案をして直していただきたいところがあるので、ぜひ改善をしてほしいなと思います。ちょっとその辺の手順が、区長部局の調査と教育委員会の調査の２つがどういうふうに関係をしていくのか、１点説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"現時点では、この結果については個人情報等さまざま複雑なものがあると思います。この文教委員会においてそれぞれの報告の経緯とか内容について、当所管についてはちょっとこちらのほうで検討させていただきたいと考えています。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そして、そのためにも、子どもの権利条約に基づく区の立場を明らかに書き込んでほしい、これが１点目です。これなしにはやはり子どもを救えないと思っているのですが、この点とても重たい問題なのですが、いかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"迅速・適切な対応、家庭また関係課との連携、区のほうでこの条例を定めたときに調査という部分があります。再発が起こらないようにどう取り組んでいくか、その内容について学校に周知、また徹底を図るというような考えです。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"要望ではないのですよ。この本体自体の問題点を指摘して、改善を求めているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"家庭を知るといった意味での、やはり大きな意味での原因究明、この視点を持っていただきたいなと思っているのが１点です。ぜひこれは書き込んでいくべきものであると思っていますが、どうしてこれが書かれていないのか、お伺いしたいと思います。","respondent":"村尾教育総合支援センター長","answer":"これはそもそもこの法ができたときに、各学校に校内委員会を設置するということで、法で言うと第２２条のほうに定められている部分があります。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"４定のときに中塚亮議員がいじめの問題、条例の問題で質問をしましたけれども、子どもたちに教えてわかる問題ではないと思っています。この点は、ちょっと再度ですけれども、いかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"これについては第１２条の学校いじめ防止基本方針、子ども、あえてこの条例にその細かいところまで載せていくという考えは今のところございません。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この条文には書かれていない大事なことをちょっと１つご意見を伺いたいなと思っているのですが、児童と教員、一緒に過ごす時間がほしいと。品川区とともに、ここの改善を何とかしていただきたいと思うのですが、これはいかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"ただ、これについてはここで詳しく説明はできないのですけれども、提供についてはきちんと明記をしているところであります。いずれにしても、また子どもたちの様子については十分見るように、これは中心に進めていこうと考えております。","id":"exchange-022"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ちょっと２点お伺いしたいのですが、それは感想と、どういう考えなのかなというのをお聞きしたい。結局何でもみんないじめになってしまうのではないかと思うのですが、その辺、教育委員会はどのようにお考えなのか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"まさにいじめ根絶宣言のところで区としての一つの考え方、または方針ということで載せているところであります。これは１対１のトラブルであるのか、または違う、このいじめの定義は各学校に基本的には共通して定義しているものです。","id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ところが、中にはまだ小さな、未熟な発展途上の子どもですから、いろいろとトラブルなんか当然あるわけですよ。具体的な分類とかというのは、補足なりいろいろ実際の実践の場では考えたほうがいいのではないかと思うのが１つなのですけれども、いかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"ここは大きいいじめ、小さいいじめ、なかなかちょっと難しいかなと考えています。今、ケース・バイ・ケースで担任や保護者のほうと連携を図りながら、各学校できちんと対応できるようにというふうにしていきたいと考えています。","id":"exchange-024"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"この辺は後でよく検討していただくことにして、答弁は求めません。区の責務、強制力は考えていませんということでしたが、強制力を考えたほうがいいのではないか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"第２５条には懲戒、また第２６条には出席停止等、条文の中にはあえて罰則がどうのこうのということを入れてないというふうにこちらのほうでは考えています。","id":"exchange-025"},{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただきたいのですが、学校いじめ防止基本方針。品川区では役割ということになっているところについて、もう少しどういう理由なのかというのをご説明ほしいと求めました。","respondent":"村尾教育総合支援センター長","answer":"今現在もう各学校ではこの基本方針はでき上がっておりますので、６月ぐらいにかかっていくのではないかなと考えているところです。ただ、現存の基本方針はそのまま残りますので、切り替えるという考え方で見ていただければと考えています。","id":"exchange-026"},{"speaker":"大倉委員","kind":"質問・要望","question":"第一義的責任が保護者にあることからというところでは、ここにもう責任が出てくるので役割でいいのかなと思ったのでちょっと伺いました。その辺はちょっと伺いたいのと、今後実効性がしっかりと担保されるというか、考えてほしいと求めましたが。","respondent":"村尾教育総合支援センター長","answer":"保護者の役割については、まさに委員おっしゃるとおり、学校だけではなかなか対応できない。特に第９条にあります見守りとか声かけですね、極端に言うと、具体的な方法とまた連絡先等を周知をしていこうと考えているところです。","id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"何かここはわざわざこういったちょっと強い言葉というのでしょうか、何かかたい言葉というのでしょうか、になったのはどうしてなのでしょうか。何といいましょうか、シンポジウムとか他自治体のようないじめに対する子ども教育委員会ではないのでしょうか、その点についてはいかがか尋ねました。","respondent":"村尾教育総合支援センター長、渋谷指導課長","answer":"やはり区としての考え方を一つ条文を踏まえて伝える方法として、まずは学校でそれぞれ基本方針を立てていきますので、伝えていこうと考えています。対応につきましては、先日も１月に行われましたけれども… ２点目の第２１条の調査委員会と前回立ち上げた調査委員会との違いについてですが、区の事務局の者は完全に事務局として引いた形で客観性を担保する組織でありましたので、そういう意味合いにおいては同等のものだと考えています。","id":"exchange-028"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"性格も同じということを伺ったので、オープンにというとあれですけれども、行われるということで認識してよろしいでしょうか。ですから、この総合教育会議で統合された議論になるようにされることを要望したいと思いますが、その点についていかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"区長の附属機関である第三者機関に対して、教育委員会の第三者ということで、やはり客観性を持たせた調査研究をしていくと考えているところです。","id":"exchange-029"},{"speaker":"伊藤副委員長","kind":"質問","question":"何点か質問させてください。その方向は理解出来たのですけれども、今回、条例として出てきた背景が何なのかなということを改めてお伺いしたいのですが、いかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"これにつきましては、先ほどご説明を少し申し上げていた部分ではありますけれども、それについて各学校を含めて一定の取組みは進めてきた。実は２年前ぐらいからもう既に少し作成の準備は進めてきたという中で、このタイミングで提案をさせていただいたというような考えです。","id":"exchange-030"},{"speaker":"伊藤副委員長","kind":"確認","question":"そんなことは思っていない。むしろ、改めてこのいじめ防止対策推進条例の位置づけというのも私が理解するのでいいのでしょうかという確認をお願いします。","respondent":"村尾教育総合支援センター長","answer":"協力をお願いしながら進めていかなければならない、この条例をこの場面で区のほうでお願いする、また制定するという流れです。","id":"exchange-031"},{"speaker":"伊藤副委員長","kind":"確認","question":"何点か文言の確認で、第１条の４行目の最後のところ、「いじめの防止等のための対策」という表現になっていますよね。答えというのはないのかもしれないけれども、条例だから、わかれば答弁をお願いいたします。","respondent":"村尾教育総合支援センター長","answer":"私の部分では、防止ができず、または発生してしまった場合の早期対応というものを含めて「等」という考え方で使っていると考えております。〔「ためは何なのですか」「防止等のためのため」と呼ぶ者あり〕 すみません、「ための」がなぜここにどうして入ったのかと、今私もわかっていないところです。","id":"exchange-032"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"区立学校の責務とは何ですか、単純に。すみません、こんなこと言ってはいけないかもしれないけれども、条例なので、それは何かあるのか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"区立学校の責務という部分につきましては、学校としての考え方、責務、または学校としての組織体制を含めて、区立学校というような取組みでここに書いていると思います。","id":"exchange-033"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"一番確認したかったことが、第２１条の第５項の一番最後のところ、「必要な措置を講ずるものとする」という表現になっていますよね。それに対して具体的にこういうふうな、メニューと言ったらおかしいな、こういうことを考えていますみたいなことが何かあるのか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"ときに出席停止という方法も、やはり子どもの教育の権利をきちんと保証するというようなことを踏まえて、必要に応じて進めていこうと考えているところです。","id":"exchange-034"},{"speaker":"伊藤副委員長","kind":"質問","question":"Ｃ君、Ｄ君がいて、どうしてもそうせざるを得ない状況が当然出てくるわけではないですか。今あるのですよね、そのことも含めて、お考えを説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"具体的に必要な措置ということで名目がだあっと書かれているようなものを現在はつくってはおりません。今後、どのような形で学校または教育委員会としてそういうものに対応していくかについては、こちらのほうで検討させていただければと考えています。","id":"exchange-035"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"考えはわかるのですけれども、この条例だけで解決するとは当然思っていないのです、私たちとしては。それをある意味大きく担保する形で条例があると思っていますので、そういう意味で根絶に向けて努力していっていただきたいと思ってます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問","question":"この条例を作成するにあたって、教育委員会で今日いらっしゃっている理事者の中で、かかわった方ってどの方ですか。説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"基本的には教育委員会の指導課、教育長、次長も当然です。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３点目、いじめの禁止を教えるのではなく、子どもたちの自主性を育て、いじめをとめる人間関係をつくっていくこと。４点目、以上をぜひ改善を求めたのですが、受けとめられないということで反対をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]},{"id":"topic-03","title":"平成２８年請願第２号、大崎図書館の移転の見直しと現地での存続を求める請願","agenda":"平成２８年請願第２号、大崎図書館の移転の見直しと現地での存続を求める請願","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"今の説明では、１５０平米の取次窓口を大崎駅西口再開発事業の中に、そして５００平米の図書機能を持った施設を芳水小学校内にということでしたけれども、今の大崎図書館の利用できる平米数と座席数、それとどんな機能を有しているのかをお伺いいたします。","respondent":"木村品川図書館長","answer":"これは１階フロア、２階フロア、地下書庫合わせた面積です。座席数に関しましては、７８席あります。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問","question":"機能のほうもお聞きしたのですけれども、どういった機能を持っているのかというのと、あと芳水小学校内の、要は図書機能を持っている５００平米のところは座席数は幾つになるのか伺いたいと思います。","respondent":"木村品川図書館長","answer":"それから、２階に関しましては、今まではビジネス支援機能ということで図書を整備しておったところです。それから、芳水小学校のほうに関しましては、現在検討中でございまして、まだ座席数その他中身については現在検討中です。","id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問","question":"この請願を見てみても、本当に多くの地域の皆さんから愛されている図書館なのだなというのはわかると思います。議会でも何でも老朽化がなぜ移転の原因になるのかというのはずっと問わせていただいているのですけれども、改めてその理由を伺いたいと思います。","respondent":"木村品川図書館長","answer":"先ほどご案内いたしました北品川５丁目の施設に関しましてのお話がありましたので、また実際に休館をしてご迷惑をおかけするということもあります。北品川５丁目そのもののそういう文教機能、あるいはビジネス支援の機能、総合的に勘案いたしまして結論づけたところです。","id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、図書機能のアップということも言われたのですけれども、今の大崎図書館では本の一般的な貸出、そしてお話し会などもされているということで、移転したとすればこの機能はどのようになっていくのか、伺いたいと思います。","respondent":"木村品川図書館長","answer":"移転先の北品川５丁目の施設に関しましては、同様のお話し会のスペースを設けて行おうと計画しておるところです。やはり小学校の中の施設ですので、お話のコーナーといいますか、それをできるようなことも今は踏まえて考えておるところです。","id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして、先ほどは事業説明会と学校改築説明会の説明をしてきたということですけれども、利用者への説明会はされていないということなのでしょうか。そして、やはりこの方たち皆さんの一番求めているのは、その辺は区はどのように考えているのか尋ねました。","respondent":"木村品川図書館長","answer":"その都度、今の考えを説明をしてきているです。踏まえて考えていくつもりですので、新しい施設、培っていただいたものを引き継いでいけるような形で計画をしてまいりたいと考えています。","id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"質問","question":"利用者に説明がないというのは、私はそもそもおかしな話だなと思うのです。こちらからは何も説明はしないというのは、態度としては誠実ではないなと思いますし、なぜ利用者に施設からの説明をしないのかを伺いたいと思います。","respondent":"木村品川図書館長","answer":"実際に情報提供に努めていきたいと考えておりますが、今具体的にいつどのようにという形ではちょっとお答えはできませんけれども、ご理解いただきたいと思います。","id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"他のところでもよく品川区は誇りと愛着という言葉を使っていろいろと伝統を活かそうとか残そうとか言っているわけですから、残して。私も納得いかないですし、地域の皆さんも納得いっていないと思うのですけれども、なぜ現地で存続ができないのかをちょっと伺いたいと思います。","respondent":"木村品川図書館長","answer":"そういう意味ではそちらに、その部分は私が実際に着任をしてからこの請願をいただいた方とも直接お話をさせていただいたこともあります。","id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問","question":"こういった声もあるのですけれども、これはそのとおりなのでしょうか。そこをちょっとお伺いしたい。","respondent":"木村品川図書館長","answer":"今後の説明会の実施につきましては、引き続き情報提供に努めていきたいというように考えておりますし、大きく変更する考えはございません。","id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問","question":"図書館の移転の話が先にあったということなのかもしれないのですけれども、でも代替地になるというのはそのとおりなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問","question":"連携してお話がされているのであれば、その辺をちょっと伺いたいと思います。２９号線の代替地になるのは本当なのかということ、あと区が勝手に決めたのですかというような、そこもちょっと具体的にお聞きしたいのですが。","respondent":"木村品川図書館長","answer":"代替地に関しましては、先ほどのご答弁どおりで、今この場で代替地です、ございませんというような形ではお答えができないで申しわけございません。","id":"exchange-048"},{"speaker":"石田（ち）委員","kind":"意見","question":"ぜひすぐに臨機応変に説明会を開催して、そして住民の声をしっかりと受け止めて、この場での存続をすべきだなと思います。それを主張したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"浅野委員","kind":"質問・要望","question":"その地域におられた方々については、それはちょっと私も計り知れないところがありますけれども、それは大事にしていっていただきたいなと思うのです。何というのでしょうか、多分決まっているのだと思うのですけれども、そこら辺の考えをちょっと教えてほしいと求めました。","respondent":"木村品川図書館長","answer":"改修・改築に関しましてのお尋ねですけれども、基本的には現在その考えはございません。それから、代替としてお話がありました芳水小学校、大崎駅の再開発の地域という形で運営をしていくというような考えです。","id":"exchange-050"},{"speaker":"浅野委員","kind":"質問","question":"は住民の皆様に地元の環境というものをしっかりと斟酌していただければなと思います。例えば芳水小学校の新しいところで使い続けることがすぐできるのかどうかということについて、目途があれば説明を求めました。","respondent":"木村品川図書館長","answer":"実際に芳水小学校のところは５００平米ですので、ほぼざっくりで１フロア、１階フロアがそのまま同等の機能を持っていけるというような認識です。","id":"exchange-051"},{"speaker":"浅野委員","kind":"質問","question":"そうすると、大体七、八カ月ぐらい空白があるという、そういうイメージですかね。８カ月ぐらいですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問","question":"経過も伺っていたら、図書館をほしいといった思いで、子ども文庫ですか。まず最初にこの図書館の移転という問題がいつどこで議論をされて、どういう経過でこういうふうになってきたのかというのをお伺いします。","respondent":"木村品川図書館長","answer":"発端は、企画部門、区のほうで北品川５丁目の老健施設に関するところの部分で、複合施設の活用というところでの検討がまずございました。区の内部検討の中で方針が決まって、それに関しましてご案内、ご報告をしてきたです。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問","question":"向こうは必要だからって、こっちが必要だと言っているのを無理やり移すことはないではないですか。私は両方大事にすべきであるなと思うのですが、この点いかがか尋ねました。","respondent":"木村品川図書館長","answer":"それから北品川近隣かなり住民の増の例が多いところですけれども、そういう意味では、運営をしてまいりたいと。地区の、大崎地域の思いみたいなものは、今後の計画の中でそういう思いみたいなものを反映させていくような形で計画を進めていきたいと考えています。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問","question":"受けとめて、どういうふうにあらわしていったら住民の方に受けとめていただけると思っているのでしょうか。同じにしますからというのもきちんと説明をしていないということでは、私、本当に進め方が乱暴だし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問","question":"まとめますよ、一生懸命、怒っているのでね、ちょっとね。その前にはやはりここは凍結してほしいと書いてあるので、住民の方に本当に失礼なことになると思うのですけれども、いかがか尋ねました。","respondent":"木村品川図書館長","answer":"もう既に生活の一部、地域の歴史の一部というところもありますので、そういう思いについては受けとめているというふうに判断しておるところです。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問","question":"ぜひ使える状態で、いい状態で残してほしいと思うのですが、こっちの芳水小学校にあるほうはどういう位置づけになるのですか。何になるのか尋ねました。","respondent":"木村品川図書館長","answer":"位置づけの仕組みについての質問です。現在検討を進めているところで、細かくちょっとご説明して、位置づけに関しましても今後検討という形で考えております。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問","question":"向こうにたまたまスペースができたから図書館をとられてしまって、後の機能がどうなるかわかりませんよなんていう話を誰が納得できるでしょうか。だから１つは、私はだから２つの図書館がきちんとあって、これはちょっとひどいことではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問","question":"この移転の問題が出てきた途端に改修はできません、補修もできません、建替えは無理ですと言ったら、もう移るしかないではないですか。この辺ってどこでどう議論をされて、いつ判断されたのか尋ねました。","respondent":"木村品川図書館長","answer":"建物で押しなべて１０年、１１年、建物の構造的なもの。実際にこういう話がありますというところでありましたので、総合的に判断をいたしまして、そのような考えとさせていただいたところです。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問","question":"お願いしたいと思いますが、改修に幾らぐらいかかるかとか建替えに幾らかかるかとか実際に計算がされているのかどうか、それを一つお伺いします。もちろんそういう話にも参加していらっしゃると思うので、この点を、答えるよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"道路の代替地の問題は、ぜひ都のほうにお断りをしていただきたいなと、これは要望しておきます。長くなりましたが、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"伊藤副委員長","kind":"確認","question":"おそらくこの大崎図書館というのは、そういう基準に当てはめて改修・改築の方法はとらなくなったと推測するのだけれども、わからないですかね。その点、伺います。","respondent":"木村品川図書館長","answer":"申しわけございません。存じ上げておりません。","id":"exchange-062"},{"speaker":"伊藤副委員長","kind":"確認","question":"次に、平成２６年の請願のことについていろいろ確認したいのですけれども、このことに関してこの中に書かれていたような請願が出されました。確認したいのが、平成２６年のこの請願、具体的にどういうふうなことを品川区は考えたのですかということを確認をお願いします。","respondent":"木村品川図書館長","answer":"実際に周辺でそういうような確保、急遽その部分でそういう部分を入れられないかということで検討いたしまして、その部分を入れ込んでやったです。","id":"exchange-063"},{"speaker":"伊藤副委員長","kind":"確認","question":"確認したいのが、芳水小学校ＰＴＡ会長が出された請願に基づいて、つまり芳水小学校の中にそういう施設を確保したという確認でいいのですよね。こういう請願について真摯に応えて、実際にそういう施設なりを対処したと思うのですが、それでよろしいのか尋ねました。","respondent":"本城教育次長","answer":"その意味では、本委員会での請願の趣旨をしっかりと受けとめて、請願に代表されます住民の方もしっかり受けとめた形で対処をしたところです。それと、もちろん大崎図書館を含めて全般についての位置づけの中でいろいろ検討されたプランになっているものと理解しております。","id":"exchange-064"},{"speaker":"伊藤副委員長","kind":"質問","question":"つい先日品川区からこういう計画が報告されたわけですから、この請願にあるように、現地で存続はしないか。それがずっとバランスを考えていくと、大崎図書館代替機能は十分果たせると思うのですが、いかがか尋ねました。","respondent":"木村品川図書館長","answer":"それから芳水小学校のスペース、それからプラスいたしまして大崎駅前の再開発の施設の中に予定しております取次の施設。こういう形で実際にその３つを組み合わせた形でといいますか、副委員長のおっしゃるとおりです。","id":"exchange-065"},{"speaker":"伊藤副委員長","kind":"質問","question":"十分さまざまな説明なり、将来できるリハビリテーションパーク内の図書館とあわせて有効活用していっていただきますことをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"大倉委員","kind":"確認","question":"確認なのですけれども、今、副委員長がおっしゃっていた請願については、平成２６年の品川区立大崎図書館移転に関する請願の話でいいですか。６月２０日と書いてありますが。","respondent":"木村品川図書館長","answer":"品川区立大崎図書館移転に関する請願。そちらです。","id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問・要望","question":"このまま放置して、いや、これから先にもっときちんと決まってから説明しますよという話では、やはり地域をまとめていけないのではないですかね。２階のスペース、ちょっと平米は別々に聞かせていただきたいのと、芳水小学校の地下にできるところの平米数をもう一回聞かせてください。","respondent":"木村品川図書館長","answer":"大崎図書館の１階・２階の平米数につきましては、ちょっと今調べますのでお待ちください。それから、芳水小学校に関しましては５００平米を想定しております。","id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問・要望","question":"障害者に使ってほしいと書いてあるので、あくまでも芳水小学校の地下が同等の機能ですというところで、地域の方は違うといつも言っています。ここは明確にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これに関してはこのような意見もあるので、その辺の説明はしっかりとしていただくということを案分して、不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"浅野委員","kind":"質問","question":"質問させていただきましたけれども、やはり利便性も含めてスペースも含めて、住民の皆さんのメリットは大きいと考えます。不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして、賛成の方も反対の方も意見をしっかりと言う場をつくっていただきたい、そして説明会をすぐにでも開いてほしいと求めました。ですので、この請願に賛成をしてこの場での存続を私たちも訴えたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"大倉委員","kind":"質問・要望","question":"しっかりと利用者とかに説明をこれからしていくということでしっかり対応していっていただきたいというところで、今さまざまお話があった中でされていくのだというところでありますので、この請願に対しては不採択ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"利用されている方々の思いや利便性に応えるべく今後の芳水小学校や取次コーナーなどの充実を図ってほしいと求めました。ということで、この請願に関しては不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"}]},{"id":"topic-04","title":"平成２８年請願第４号、品川区の保育水準を維持し拡充を求める請願","agenda":"平成２８年請願第４号、品川区の保育水準を維持し拡充を求める請願","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"民営化、当面５園、１年当たり１園ということで計画が発表されているわけですが、民営化することでどれくらいの費用が浮いていくのか。それは保育園運営のどの部分で一番コスト削減ができるのか伺いたいと思います。","respondent":"竹田保育課長","answer":"民設民営にすれば約１億５,０００万円と試算しておりますので、約５,０００万円程度の軽減になるのかと考えています。そもそも保育園の運営費は６０％近くが人件費ですので、その部分を含めて削減されると考えております。","id":"exchange-075"},{"speaker":"石田（ち）委員","kind":"意見","question":"これで１園２億円かかっていたものが１億５,０００万円でいくということですけれども、そこまで頑張って運営してきたということだと思うのですけれども、その理由を聞かせてくださいとの意見を述べました。","respondent":"竹田保育課長","answer":"例えば、遡りますと、昭和の時代は品川区内に私立保育園は非常に限られた数しかございませんでした。２３区も含めてですが、今後、民営化に取り組んでいくと計画を立てているところです。","id":"exchange-076"},{"speaker":"石田（ち）委員","kind":"質問","question":"この民間活力を活用すると人件費が下げられると、要は今の説明を聞いているとそういうことだと思うのですけれども、何で民間の活力を活用すると人件費が下げられるのか、そこを伺いたいと思います。","respondent":"竹田保育課長","answer":"公立の保育園については、国や都からの補助金等が入らないのが現状です。しかし、民設民営の運営形態ですと、国や都から補助金等の歳入が期待できますので、その分削減できると考えております。","id":"exchange-077"},{"speaker":"石田（ち）委員","kind":"質問","question":"人件費なわけですから、そこを削減すれば保育士の給料が安くなっていくのは当然ですので、そこを区としてはどう考えているのか。前回の補正予算でついた……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"石田（ち）委員","kind":"質問","question":"５,０００万円の部分が、でも先ほど５,０００万円の部分で６０％が人件費になりますので、そこがやはり大きくというふうな説明でしたよね。ですから、私は５,０００万円の多くが人件費で浮いていくのだなと理解をしたわけですけれども、そういうことでよろしいか尋ねました。","respondent":"金子子ども未来部長","answer":"昨年の委員会でも今回の方針をご説明したとおり、今日も課長からご説明しましたけれども、国や都からの運営費というものが入らない。これはやはり今後の不透明な財政運営から考えますと、品川区としての民設民営化を実施し、当面の民営化ということを計画したわけです。","id":"exchange-079"},{"speaker":"石田（ち）委員","kind":"質問","question":"区も圧迫していくというような状況になるのではないか、圧迫しているとは私は思いませんけれども、そういう状況になるのではないでしょうか。低賃金になれば質の確保は下がっていくのではないかなと普通に考えて思うのですけれども、そういったところはどのようにお考えか尋ねました。","respondent":"竹田保育課長","answer":"財政につきましては、例えば公立保育園が何園あるとか民間の保育園が何園あるとかということまでを加味したものではございません。東京都や国から今いろいろさまざまな形で賃金改善の施策が出されているところですので、昨年よりも今年という形で賃金は改善されているところです。","id":"exchange-080"},{"speaker":"石田（ち）委員","kind":"質問","question":"そして、公設の方も２００万円をやっと超えるかなというぐらいなのですけれども、やはり保育士の働く現状というのは、どちらにしても大変だなと。そこをもう一度ちょっとご答弁お願いします。","respondent":"竹田保育課長","answer":"その後、数々の賃金改善の施策がなされておりますので、状況は一定程度改善されたと考えております。それから、公立と私立の賃金の比較ですが、こちらは年齢構成等も違いますので一概に比較はできないものだと考えております。","id":"exchange-081"},{"speaker":"飯沼委員","kind":"質問・要望","question":"何かなですが、６０％が人件費というと、４０％はあと何なのですか。これは求めていると思いますけれども、これをこれからも引き続き頑張って求めていって、そこは投げ捨ててしまったのか尋ねました。","respondent":"竹田保育課長","answer":"人件費のご質問ですが、こちらの６０％については正規の職員を計算したものです。それは入れないで」と呼ぶ者あり〕 それから、人口推計を見ますと、平成３３年をピークに今後、経費がどんどん膨らんでいくということが予想されております。","id":"exchange-082"},{"speaker":"飯沼委員","kind":"質問","question":"いいのでしょうか、今ので、部長。〔「課長のとおりです」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ということは、人件費６０％ですよと言っていることは世間的にいうと正確ではないと受けとめていいのでしょうか。４０％が非正規とかに入っているということは、ここに抱えているという捉え方でいいのかどうか、ちょっとお聞かせいただきたい。","respondent":"竹田保育課長","answer":"こちら、先ほど申し上げたのは、６０％というのは職員人件費です。〔「よくわからない」と呼ぶ者あり〕 今働いていらっしゃる方々には非常勤等も含めまして、適正な賃金をお支払いしていると考えております。","id":"exchange-084"},{"speaker":"飯沼委員","kind":"質問","question":"４０％の中に非正規、今の職員の正規職員の比率ってどのくらいなんですか、保育士は。正規比率を説明を求めました。","respondent":"竹田保育課長","answer":"先ほどの６０％は正規の職員ですので、それ以外の部分に非常勤等が入っているものです。今、正規の数字はすぐ出ませんので、後ほど答えします。","id":"exchange-085"},{"speaker":"飯沼委員","kind":"質問・要望","question":"お金の面はわかったのですけれども、このことによって失うものはないのでしょうか。今のこの時期、中身は何ですか、民間活力の活用というのは。","respondent":"竹田保育課長","answer":"今後、限られた財源の中で子育て支援の一層の拡充を図っていくためには、官民が一体となってサービスを提供していくことが必要だと考えております。多様な運営主体が連携して保育サービスを提供していくというのが民間活力の活用というようなことだと考えております。","id":"exchange-086"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それで、保育士がやめる、最近の離職率がわかったら教えていただきたいのですが、区立の保育園の離職率はどんなものなのですか。品川区内の企業立の認可保育園の離職率をつかんでいたら説明を求めました。","respondent":"竹田保育課長","answer":"公立の保育士が約７００名程度おりますが、年によっても違いますし、理由もさまざまですが、おおむね２％から３％ぐらいと考えております。私立の保育園につきましては、園によってさまざまですので正確な数字というのはつかんでございません。","id":"exchange-087"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、平均並みなのですか、そういうところなのですかね。いるのだったら教えてほしいと求めましたが、３万２,０００人がやめてしまうのです、新人。","respondent":"竹田保育課長","answer":"特に、労働市場が非常に流動的になっているところがありますので、より人の異動というのが多いかと思います。人間関係も一つの要素と言われておりますので、そういった面を改善するような研修なり支援をしていきたいと考えております。","id":"exchange-088"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味で、この子育て支援センター的役割はますます求められていると思うのですが、この点に関してはいかがでしょうか。代表質問の中で不承諾通知、入れなかった１次のところが１,１８５人お子さんがいらっしゃったということで、聞かせてください。","respondent":"竹田保育課長、今井待機児童対策担当課長","answer":"今回の民営化は、当面運営のみを民間事業者に委託するいわゆる公設民営を予定しております。地域子育て支援センター的な役割ということに関しましても、業務委託の範囲内で可能な限り果たしていきたいと考えています。 今年は認可保育園７園でございましたけれども、平成２９、３０年と６園ずつ認可保育園を含めて開設をしてまいります。平成３０年度の末に待機児童の解消を予定しておりますけれども、その中で対応してまいります。","id":"exchange-089"},{"speaker":"飯沼委員","kind":"質問","question":"私は受け皿的に何園必要と思って幾らぐらい計算しているのかなとお伺いしたのですけれども、それ以外は考えていない、そういうことなのでしょうか。何が違うのですか、違わないのか尋ねました。","respondent":"竹田保育課長","answer":"先ほど申し上げたのは、設置主体として区の責任は変わることはございませんと申し上げましたので、その部分、設置主体の責任という点では変わらないと考えております。","id":"exchange-090"},{"speaker":"飯沼委員","kind":"質問","question":"設置主体であることは変わらないけれども、内容は変わるけれども、今日は言えないと、そういうことでよろしいでしょうか。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"浅野委員","kind":"質問","question":"前回もちょっと伺ったのですけれども、品川区がこのような形で計画を立てて進めていくということで、あと前にほかの区はどんな動きをしているのかということを聞いたことがあると思うのですけれども、最近また変わったところですとか、ほかの区、周りの区で変化があれば教えてほしいと求めました。","respondent":"竹田保育課長","answer":"前回お示しした内容で、そのあと周辺区で大きく変わったというところは聞いてございません。","id":"exchange-092"},{"speaker":"浅野委員","kind":"質問","question":"大田区でも動きがあるとか、世田谷区、目黒区に少しずつあると伺っております。状況をどう把握するのかということについて説明を求めました。","respondent":"竹田保育課長","answer":"保育の質については、各園でさまざまな取組みを行っているところですので、今後もさまざまな取組みを支援していきたいと考えております。","id":"exchange-093"},{"speaker":"浅野委員","kind":"確認","question":"そういうような動きが必要なのか、それともそれは区の及ばないところなのかということについて、確認をさせてください。","respondent":"竹田保育課長","answer":"保育内容が低下することのないようにしたいと考えております。それから、運営主体関係なく、指導監督する責任が区にはありますので、運営の管理監督をしっかりしていきたいと考えております。","id":"exchange-094"},{"speaker":"浅野委員","kind":"質問","question":"管理監督するためには、やはりさまざまな指標というのでしょうか、そういうものが必要かなと思いますね。そういうふうな形を私は取るべきだと思うのですけれども、具体的な指標で評価をするという考え方は今あるのかどうか、説明を求めました。","respondent":"竹田保育課長","answer":"具体的な方法等につきましては、今後検討していきたいと考えております。","id":"exchange-095"},{"speaker":"高橋（し）委員","kind":"質問","question":"民営化として業務委託、指定管理とあると思うのですけれども、その辺はどのようにお考えなのか尋ねました。","respondent":"竹田保育課長","answer":"当面は、運営業務委託、いわゆる公設民営の形をとってまいりまして、十分内容を検証しつつ民設民営化を検討していきたいと考えております。","id":"exchange-096"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、現行、公設民営化していて運営されている保育園はあるのか尋ねました。","respondent":"竹田保育課長","answer":"指定管理の形でやっているところはありますが、公設民営という形でやっている保育園は現在は、業務委託をやってはございません。","id":"exchange-097"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、そこでさまざまな問題が起きているとすると、今後民営化するのには課題が出てくると。そうでない、あるいはそういったチェックする機能がきちんと働いているのであったら進めていけるのではないでしょうかということをお尋ねしたのです。","respondent":"金子子ども未来部長","answer":"お尋ねの園は公設民営、また私どもが掌握している内容としては、保育の内容としては非常に先進的な取組みをしてすばらしいものがあると考えています。","id":"exchange-098"},{"speaker":"高橋（し）委員","kind":"質問","question":"わかりました。指導をしていくということですから、その中で進めていくという今のお話があったので、ありがとうあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"伊藤副委員長","kind":"確認","question":"何点か確認させてください。初めに、私の記憶ではされていないという記憶があるのですけれども、その確認だけまずお願い。","respondent":"金子子ども未来部長","answer":"財調の方には算定されています。財調は一般財源ですので、しかもそれはいわゆる特定財源という分類にするわけではありませんので、そのようにご理解いただきたいと思います。","id":"exchange-100"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"待機児童が増加するたびに１０事業ですか、１０事業の事業で展開をしてきて、この保育水準を維持してきたと私は思うのですよ。民営化云々というより手前にこの保育水準を維持し拡充を求めるために品川区は税を投入して、費用対効果も十分勘案しながら、いかがか尋ねました。","respondent":"竹田保育課長","answer":"品川区は、ご指摘のとおり、乳幼児教育の充実に力を注いできたところです。そういった考え方については、保育の質を維持しながら、保育の維持・充実・向上に十分努めてまいりたいと考えております。","id":"exchange-101"},{"speaker":"伊藤副委員長","kind":"質問","question":"ですから、さまざまな選択肢の１つに、ここに書かれてあるような民営化というのがあると判断するわけですよ。お話しいただいた中で有効に活用していただいたほうが、私は３８万区民のためになると思っておるのですが、お考えはいかがか尋ねました。","respondent":"金子子ども未来部長","answer":"区立区営が先頭を切って運営をしてまいりましたけれども、区立区営をこのまま４３園維持するというのは非常に厳しいものがあると考えています。","id":"exchange-102"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"品川区の保育水準を維持し拡充を求める、これは非常にもっともな願いというか希望でありまして、これは何人も反対する人はいないです。ということで、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"浅野委員","kind":"質問・要望","question":"質問しましたけれども、１園ずつ当面５園の委託をしていくということであります。次にどうするかというのはまた別の話になるかと思いますけれども、また次なる新たな一歩、新たな手段というものも出てくるのかなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"飯沼委員","kind":"意見","question":"これも社会的に明らかになっているということで取り上げているので、誤解をしないで受けとめてほしいなというのをまず最初に一言。この願いは当然と思いますので、賛成をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-105"},{"speaker":"大倉委員","kind":"質問・要望","question":"品川区の保育水準を維持し拡充を求める請願については、研修も促していく中で向上も目指していくというお話もありました。この請願に関しては、そういったところから願意に沿いがたいというところで、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"高橋（し）委員","kind":"意見","question":"そして、認証も含め、保育の保護者の方々のニーズに対応してさまざまな形で保育の需要に応える形で供給していく必要があると思います。そのために、そういったことでこの請願書については願意に沿いがたいということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-107"}]},{"id":"topic-05","title":"本定例会の代表・一般質問にかかわる所管質問ですが、本定例会の代表・一般質問中文教委員会にかかわる項目","agenda":"本定例会の代表・一般質問にかかわる所管質問ですが、本定例会の代表・一般質問中文教委員会にかかわる項目","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"ゼロ歳から２歳が何人だったのか、３歳以上が何人かという、そこを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/462438?Template=document&Id=4876#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":76194,"voices":290}},{"id":"h28-20160222-5","meetingId":"h28-cm02","date":"2016年2月22日","dateIso":"2016-02-22","committee":"総務委員会","time":"午前１０時００分～午後 ４時４０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を100件整理しています。","topics":[{"id":"topic-01","title":"第９号議案、品川区文化スポーツ振興基金条例","agenda":"第９号議案、品川区文化スポーツ振興基金条例","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今回の５億円の中では、この補助金の活用というのがどういう関係になってくるのか、そこを伺いたいと思います。３点目は、必要な事業に充てていくという説明もありましたけれども、あえて基金をつくって行っていく理由を改めて伺いたいと思います。","respondent":"秋山財政課長","answer":"大体５億円を、平成３２年度のオリンピック・パラリンピックまであと５年ありますので、その程度を使っていきたいというふうに考えてあります。３番目の質問にも重なるのですけれども、また事業として継続性を持って使っていけるということで、基金を積んだです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"全部通しても３０億円だというお話がありましたけれども、どういう見通しの規模を持っているのか、現時点での考えを伺いたいと思います。混ざってしまうことと絡むのですけれども、直接の競技場にこの基金を充てるということが可能なのか、幅があるので、そこを伺います。","respondent":"秋山財政課長","answer":"３０億円で、来年度は５億円の取崩しを予定しておりますけれども、取り崩したものは積み増していきたいというようなことを考えてあります。","id":"exchange-002"},{"speaker":"中塚委員","kind":"確認","question":"ここで３０億円というたがをはめてしまって、毎年大体５億円というたがをはめてしまって、そこも１点確認したいと思います。幅広く活用するというだけに、区の設置に当たっての考えというのがとても大事だと思うので、ここも最後に伺いたいと思います。","respondent":"秋山財政課長","answer":"再開発につきましては、平成２８年度当初予算では、そこに投入するようなことは考えてございません。そういうソフト事業も含めて、地域のにぎわいに資するものということで使っていきたいというふうに考えて、今回基金を設置する、そういうことです。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問・要望","question":"積立額なのですけれども、予算で定める額とそれから寄附金の額の合計額とあるのですが、この基金の全体の額となるという理解でよろしいのでしょうか。ご説明では、３０億円を５年間で使い切っていくようなイメージだと理解して、これはそういう理解でいいのか尋ねました。","respondent":"秋山財政課長","answer":"寄附金につきましては、３０億円に積み立てるものの一つとして寄附金を充てるですので、寄附金が幾らということでは特には考えてございません。オリンピック以後もそうやってその後の基金については、使っては積み立てるという形で運用していくように考えております。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問","question":"とすると、３０億円規模を今後もずっとキープするようなイメージでよろしいのでしょうか。それが非常にそれぞれの年度に恣意的に選択されるとなると、この事業の範囲の捉え方はどのように線引きされているのか尋ねました。","respondent":"秋山財政課長","answer":"オリンピック・パラリンピックに向けて、この基金を充当しなければ、文化スポーツの対応をしないとかということではないというふうには考えています。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"３０億円程度を維持するということですから、そうすると、また同じ基金名であれば随分違った使われた方になるのではないか。その辺、どうなのか尋ねました。","respondent":"中山企画部長","answer":"そういう中での財源充当を考えていく。こういう考え方です。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"先に３０億円使っていいですよ、内容はお好きにしてくださいというような形では、チェック機能というのが使えなくなってしまうわけです。その辺はどのように区はお考えか尋ねました。","respondent":"中山企画部長","answer":"そういう点での例示の中でご説明したのですが、スポーツをしっかり支援していくための姿勢を示す、ただ単純にソフトだけに充当しない。財源についてはその時々の中でしっかりと見極めて、この条例の趣旨に合うものを充当していく、そういう意味でご説明したものです。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"ちょっとまだ疑問は残るのですが、ほかにもご質問される方がいるので、一旦ここでやめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"その辺、一貫性がないのですが、あれだけ基金の創設を毛嫌いしていたのが、ポンといきなり出てきたというのはどういうことなのですか。その辺の考え方を聞かせてください。","respondent":"秋山財政課長","answer":"あくまで財源の固定化ということではありませんというか、ある意味、使い方が固定化されるとかということではないというふうには考えています。ある資金として考えたときには固定化はされるわけですけれども、今回は２０２０年のオリンピックで、今回ご提案させていただいたです。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"その辺についてどうなのですか。このときにわざわざ収支から、黒字の部分から３０億円移動してしまうというのは不思議な感じがするのですが、その辺もう一度だけ説明を求めました。","respondent":"秋山財政課長","answer":"目的を持って使っていくというのが一応基金の性格ですので、一般財源でやればよいのではないかということは、確かにそのとおりです。基金から使うのと一般財源から使うのでは変わってくるというふうに考えて、そういうことで今回条例の提案をさせていただいたということです。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"私もこの基金をなぜこういう形でつくるのかということを伺いたいと思いましたので、今、皆さんのご議論の中で聞かせていただくことができました。第３条の「基金に属する現金は、これは「必要に応じ」というのが、例えばどういう必要が想定されているということを教えていただきたい。","respondent":"秋山財政課長","answer":"それから第５条の繰替運用ですけれども、そちらのほうに議決をいただいて、基金からお金を一時支払う現金のために使って戻すと。そういうことができるということで、第３条以降では、通常、取崩し型の基金の条例を使うときは、同じような方法でそういう手続きを踏むものです。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"別の質問になるのですが、すみません、基本的なことで、今、審議しているのは、この条例を通して基金を創設するというところまでですよね。つまり、何が聞きたいかと言えば、基金の積立額とか、そういうのはまた別の審議になるということでよろしいですね。","respondent":"秋山財政課長","answer":"今回は基金の設置条例についてのご審議で、３０億円については補正予算の中での金額になりますので、おっしゃることになろうかと思いますけれども。","id":"exchange-012"},{"speaker":"本多委員","kind":"質問・要望","question":"うちの会派が言っていましたのは、２０２０年東京オリンピック・パラリンピック開催に向けて基金を創設してはという要望を出しておりました。その辺の展望についてお聞かせほしいと求めました。","respondent":"秋山財政課長","answer":"２０２０年に向けて、これからどんどん需要が増えていくのではないかですけれども、確かにそのようなことも考えられるとは思います。それはそのときで考えなければいけないと思うのですけれども、３０億円について足りなかったというときに、今考えているわけではないです。","id":"exchange-013"},{"speaker":"本多委員","kind":"意見","question":"左にしか行けないのを右に行けるようにしたほうが、必ずそうなると思うので、そういうのを早急にやったほうがいいかと思います。絡みでいろいろと細かいことを言うと切りがないのですが、いろいろ出てくると思いますので、ぜひ基金の活用をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"大沢委員","kind":"質問","question":"姿勢を見ると、議会の議決よりももう我々はこういうふうにするのだ、だからどうだというような姿勢に感じざるを得ない部分もあります。そこのところをご意見、伺いたいと思います。","respondent":"桑村副区長","answer":"計上してあります、補正予算に出してありますという意味ですので、それはぜひご理解をいただきたいと思います。今後の様々な予定のことがありましたが、これは今の予定でこの条例の動かし方というのをやっておりますので、ご理解をお願い申し上げたいと思います。","id":"exchange-015"},{"speaker":"大沢委員","kind":"確認","question":"決して言葉尻云々ということではなくて、進め方で私のほうで質問とか考えがあったので、そこの部分の確認というか、自分の考えをぶつけさせていただきましたので、区の姿勢はよくわかっている上での質問をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"あくつ副委員長","kind":"提案","question":"議員提案でやろうか、創設を提案しようかという話もありましたけれども、そういうイメージがあったものですから。ですから、使い方については予算特別委員会等でまたご提案をするということにして、いかがか尋ねました。","respondent":"桑村副区長","answer":"区長の施政方針でありますように、新しく何か取り組む事業になるべく充てていきたいというのが、気持ちとしてはあります。もちろん区民芸術祭等を充実させていくというのは継続的にはあるわけですけれども、何かやることは可能ですけれども、その方向にやると。","id":"exchange-017"},{"speaker":"あくつ副委員長","kind":"意見","question":"この３月で文化プログラムができるということで、文化芸術に対しては若干薄い印象をどうしても受けてしまう、オリパラに関しても。そこのところをぜひもうちょっと強調していただけたらなというふうに思います、意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"あべ委員","kind":"質問","question":"別に来年度どうしても５億円使わなくてはいけないということもないわけですし、支出する項目も金額もどんどん増えていったりもするでしょうから。","respondent":"秋山財政課長","answer":"今回の予定としてこれを選んだ結果として５億円という形でありますので、中身も変わっていくというものだと思っています。ただ、今回ご提案する当初の予算の中では、こういう形で入れさせていただいたという考え方です。","id":"exchange-019"},{"speaker":"中塚委員","kind":"意見","question":"幅が広く、具体的な事業にどう充てていくのかというのは、十分注意が必要だということは指摘をしたいと思います。使い方については、しっかりした精査が今後も必要だということは指摘をして、賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"あべ委員","kind":"意見","question":"３０億円程度ということがずっとオリパラ前後と同じ規模必要なのかどうか、それを区民にどうわかりやすく説明していくのか。わかりやすく、基金という形のものが便利な財布になってしまわないように使い方をするということをぜひ強調して、この基金条例には賛成しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"まだまだ足りない分野にも、福祉の分野にも事業費、予算はつぎ込んでほしいと求めました。今回の条例案に対しては賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"吉田委員","kind":"確認","question":"区民から見えにくいものになりがちなところがあるというのは、どの区でも、どの自治体でもあり得ることだと思います。それぞれ別の場でちゃんと審議されるということを確認できましたので、目的に鑑みて必要と考えますので、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回の変更は、資料でいうと、第１４号議案の説明の２ページ目と３ページ目のこの関係をもう少しご説明いただきたいというふうに思います。役職なのでしょうか、教えていただきたいのと、どういう位置づけなのかも伺いたいと思います。","respondent":"江部総務課長","answer":"なかなかわかりにくいということで、もう一度説明します。３人大体想定はしておりますけれども、保護はより厚くなっているというのが国の考え方でございまして、それに沿った制度構成にしたところです。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的にどういうやりとりが追加されるというか、充実されるのか、そこを改めてご説明いただきたいというのが１点です。そこの姿勢としか聞けないのでしょうけれども、伺いたいと思います。","respondent":"江部総務課長","answer":"それを、先ほど申しました第三者機関の３人の専門の方にお渡しして、それで書類上審査していただく形になります。基本的には、行政不服審査会のほうは企画部門のほうで持っていただいて、そこは線引きをするということでやる予定にしております。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまり、仕組みで担保をつくっていくということが重要なポイントになってくると思いますので、そこは改めて１点伺いたいと思います。こういう審理にかかわって自分の情報の開示を求めるときは、無料であるべきではないかという意見についてのお考えを、そこも１点伺いたいと思います。","respondent":"江部総務課長、中元広報広聴課長","answer":"１点は、まず審理を、原処分に関わっていない所管が行う。これまでというわけではありませんけれども、より請求人の方の権利といいますか、救済がされていくだろうと思われます。 自己情報開示の有料のところです。この辺のところの手数料につきましては、今後も、こちらの個人情報保護条例のほうでは変わるところはございません。","id":"exchange-026"},{"speaker":"あべ委員","kind":"質問","question":"３月いっぱいのうちに手続きを行うと、４月を超えると、改正後の審査請求という手続きになるのであろうかと思います。もし３月中に異議申立てをして、改めて４月にこの４月の仕組みに則って、審査請求をするということはあるのではないか尋ねました。","respondent":"江部総務課長","answer":"平成２８年４月１日施行ということで、今年度、平成２７年度に行いました行政処分は対象ではありません。ですから、平成２８年の入園の件が平成２９年の２月とかであれば、そこから対象になってくるというものです。","id":"exchange-027"},{"speaker":"あべ委員","kind":"質問","question":"現行と改正後で、申立人といいますか、請求人の方が最初に用意する書類等々というのは変わってくるのでしょうか。よりよい、しやすいものになるとか、最初からすごく大変なものであるとか、そういう変化というのはあるのか尋ねました。","respondent":"江部総務課長","answer":"異議申立書というのは、そこで原処分、何月何日に行われたこれについて異議があるということを出していただくようになると思います。それらは所管課からとかご本人からとかとのやりとりの中でいただいてまとめていくということで、後で出てくるだろうと認識しております。","id":"exchange-028"},{"speaker":"あべ委員","kind":"確認","question":"最初のアクションを起こすときに、ハードルの高さがもし変わってくるのであれば、ちょっと注意したいなと。ちょっと注意を要するなと思ったものですから、確認したいということですが、いかがか尋ねました。","respondent":"江部総務課長","answer":"それが事後の審理の場というので何月何日どこでという日付を設けていきますので、そこで実際はされていくと思いますので、特にハードルが上がるということではないと思います。","id":"exchange-029"},{"speaker":"あべ委員","kind":"質問・要望","question":"どんな仕組みでも大変なものだと思いますので、審理までにできるだけ相談に乗ったりというようなことはしていただきたいなと。一般論ですけれども、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"どういう人が審理員になるかというところで、そういうのはさっき伺ったのですが、何か想定されるようなことがあるのか尋ねました。","respondent":"江部総務課長、田村総務部長","answer":"各区でも、外部の弁護士を非常勤で委託するかというのもいろいろやっておりますが、区の職員である必要があるという条件の中で選んでいきます。中立的立場とか、「など」というところですと… 大きく言えば、１つは原処分、例えば保育課の業務に携わっていた人ではないところ、例えば総務課ですね。","id":"exchange-031"},{"speaker":"吉田委員","kind":"確認","question":"やはり、でもこういうふうに審理員をそうするということは、中立性というのを重んじるというふうに理解してよろしいのでしょうか。その辺は確認したいと思いますが、いかがか尋ねました。","respondent":"江部総務課長","answer":"まさに委員おっしゃる中立性というところが、ほかに法の中でもあります。品川区でも、今後どういう流れにするかということを検討してきてやってきているものですので、委員おっしゃるとおりです。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"くれぐれも中立性というのは、改正の意義の大きなところかなというふうに思いますので、その中立性という点は強く持ち続けていただきたいということを意見として申し述べたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"あくつ副委員長","kind":"質問","question":"３ページに載っている参加人、言葉のことを伺いたいのですけれども、これはどういう場合を想定しているのか。それは言葉の説明だけお願いします。","respondent":"江部総務課長","answer":"具体的には、その整理に沿って絞り込み、誰でもが入れるということではないと思います。ここで家族ならいいのかとか、第何親等までとか、正確には申し上げられませんが、そういう方針だということで聞いてあります。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"それとも、第１０号のみですか。いずれも行政不服審査法に関わる改正でありますので、公平性、また中立性の担保を強く求めたいという点は指摘をしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]},{"id":"topic-02","title":"第１１号議案、品川区附属機関の構成員の報酬および費用弁償に関する条例の一部を改正する条例","agenda":"第１１号議案、品川区附属機関の構成員の報酬および費用弁償に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"１点だけなのですけれども、会長や委員や、また委員長や委員や、いろいろ報酬に差があるのは、その考え方は職責なのか、実際の拘束時間なのか。一定の物差しを持って、ただその物差しは何なのかという、そこだけご説明くださいとの意見を述べました。","respondent":"江部総務課長","answer":"やはり会長や委員長はそれぞれ少しずつ金額が上ですけれども、それらの負っている職責という面と、それから事前の打ち合わせ、その他ありますので、時間的な部分も含めてです。","id":"exchange-036"},{"speaker":"あべ委員","kind":"質問・要望","question":"これはどういう基準でこういう報酬差が出ているのかという、その理屈の部分を教えてほしいと求めました。どうだろう、いろいろあるので、どういう全体の枠組みの中でそれぞれの報酬額が決まっているかということを説明を求めました。","respondent":"江部総務課長","answer":"必ずしも全て横並びで決めているということではなくて、やはり会議の時間、拘束時間だったり、議論している内容、様々なところで他区の状況などを見ながら、それぞれの所管で決めているのではないかと思います。","id":"exchange-037"},{"speaker":"あべ委員","kind":"質問・要望","question":"お考えをお伺いしたいと思うのが１点と、議員が委員の場合にあってはという、若干ほかの委員も報酬額が安いと。何か背景がわかるようなというところで、金額の多寡は構わないのですけれども、それだけ教えてほしいと求めました。","respondent":"江部総務課長","answer":"詳細につきまして申し上げるのは、根拠も持っておりませんので、申し上げられません。正確なところが把握できておりませんので、これはちょっとお時間をいただいて、確認をしてみたいと思います。","id":"exchange-038"},{"speaker":"中塚委員","kind":"提案","question":"教育的な対応こそと提案したのですが、そうした視点が足りず進めるべきではないと考えていますので、ここの規定は反対です。よって、３つの附属機関の改正ですけれども、いじめ条例は大きな問題があるので、全体として反対ということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"須貝委員","kind":"質問","question":"先ほど、費用弁償の金額差について質疑がありましたが、それはやはり一律に下げる方向でもいいのでしょうから、すべきだと思います。今回の議案に関しては、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"吉田委員","kind":"確認","question":"確認なのですが、条例とかが最終本会議も経て、全部決まったらこの制度も設置されるということで理解してよろしいのですよね。これは必要な措置だと思いますので、そういうことを前提として、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"おおよその総額で結構ですので、この条例改正に伴って去年と今年と、総額でどれぐらい変動、要するに増えるのか、そこを伺いたいと思います。一致ではなかっただけに、そういうタイミングや考え方は、一般職と特別職の違いにも関わってご説明をほしいと求めました。","respondent":"江部総務課長","answer":"区長ですと、５０万円ちょっとということですので、それぞれ人数を掛けていただいた総額が影響額です。２３区の中での報酬、特別職の方は選挙で選ばれる方ということが趣旨ですので、一定の違いはあるかというふうに認識しております。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問","question":"つまり、議員も区長も選挙で選ばれる性格から独自に見ていくという視点が必要だと思うのです。検討経過を伺いたいということが１つと、特別職の引き上げというのは問題があると思いますけれども、それについてのご意見も伺いたいと思います。","respondent":"江部総務課長","answer":"そちらに対する施策というのは、それぞれの消費を喚起するであるとか、そういった政策の中で展開されるべきものであります。議員等特別職の報酬につきましては、これまで答弁しておりますけれども、別の次元で考えていっていいのではないかという立場です。","id":"exchange-043"},{"speaker":"あべ委員","kind":"質問・要望","question":"参考までに、これまで過去５年、１０年ぐらいはどのような推移であったかということを確認させてほしいと求めました。私の記憶では、随分と下がる一方だったような気がするのですけれども、今、過去と比べてどうか尋ねました。","respondent":"江部総務課長","answer":"３.６０月からの下落分の戻りが６５％程度、３分の２は戻ったというようなことが、この１０年の期末手当では言えるものです。ただ、報酬全体を見ますと、バブルの崩壊以降、平成９年がトップなのですけれども、そこから下がり傾向にあるというのがあります。","id":"exchange-044"},{"speaker":"須貝委員","kind":"提案","question":"特別区人事委員会勧告というのがありますが、どうもこういう勧告を出すのはちょっとおかしいのではないかというふうに私は思います。今回のこの提案に関しては、大半の区民のことを思うと、やはり引き上げに関しては、今は私はやめるべきだと思いますので、反対をしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"吉田委員","kind":"質問","question":"品川区の条例によれば、議員のこういう期末報酬も区長、副区長に連動する形になっているのですけれども、その考え方を教えていただけますか。どうして、だから別に決めるということではなくという点。","respondent":"江部総務課長","answer":"考え方ではなく、費用弁償及び期末手当に関する条例」が昭和２７年に制定でございまして、そこでは期末手当についても金額が決まっています。第６条の第２項、「期末手当の額は」というところで、区長と同じになるというような、そういうつくりをしているです。","id":"exchange-046"},{"speaker":"吉田委員","kind":"質問","question":"その条例の背景というところまでいくと、お答えいただくのは無理なのでしょうか。別の決め方をするというふうになっていないということについて教えていただけるといいと思うのですが、いかがか尋ねました。","respondent":"原区議会事務局長","answer":"条例のつくり方について、考え方といったところですけれども、この間、いろいろ経過を調べてみますと、歴史的な経過があります。担っている重責に対しての考え方をどこかに持つという中で、一つは、区長のところと合わせていくというのがこの間の経過等々です。","id":"exchange-047"},{"speaker":"吉田委員","kind":"意見","question":"議員の期末報酬に関連してしまうということで、やはり議員というのは、感覚的により区民の一般的な感覚に近くあるべきかなと思います。反対というか、賛成しかねるという感じで、反対をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"}]},{"id":"topic-03","title":"会議の運営上、審査の順番を入れ替え、先に契約議案を審査してまいります。 これより(14)第４２号議案、しながわ区民公園水泳場改築工事請負契約の変更","agenda":"会議の運営上、審査の順番を入れ替え、先に契約議案を審査してまいります。 これより(14)第４２号議案、しながわ区民公園水泳場改築工事請負契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"工事内容の変更なので、ここをちょっと伺いたいということだけで、基礎調査を一部見直すどういう事情が起きたのか。どういう、利便性の向上ということなのですけれども、変更の中身をもう少しご説明ほしいと求めました。","respondent":"小林施設整備課長","answer":"既存のプール等の解体後、現地にて地盤調査を実施いたしました。１５個を増設したです。","id":"exchange-049"},{"speaker":"本多委員","kind":"質問","question":"工期の延長なのですけれども、６１日の延長というのは、作業する日数が６１日間ということでしょうか。その辺をもう少し説明を求めました。","respondent":"小林施設整備課長","answer":"その地質調査と同時に、地盤調査、地質調査をもとに基礎の再検討をしたのが約２ヶ月ぐらいかかりました。そういう障害物があったために、それを取り除いたのでかかったところで、６月３０日までの６１日間延長が必要になったです。","id":"exchange-050"},{"speaker":"本多委員","kind":"質問","question":"期間的に３ヶ月なのですが、６１日というカウントの仕方が、作業する日なのかなと。基本的な、簡単なことを素朴に思ったので、質問しました。","respondent":"小林施設整備課長","answer":"そのとおりです。作業をする日数です。","id":"exchange-051"},{"speaker":"あべ委員","kind":"質問","question":"すみません、私がわかっていないということなのですけれども、契約金額の変更が、要はこれ、増と書いてある額が数字を足し算するとこうならないというのは、何がどういう関係なのか尋ねました。","respondent":"立川経理課長","answer":"検算いたしまして、差し引き３,１３０万９,２００円増です。今日机上で差し替えさせていただきました。","id":"exchange-052"},{"speaker":"吉田委員","kind":"意見","question":"さっきの利便性の向上のところのご説明で、ろ過器がプールのほうに寄ったのでと、どう利便性が向上するのかちょっと理解できなかったので、もう一回ご説明いただけますかとの意見を述べました。","respondent":"小林施設整備課長","answer":"プールサイドにろ過器が寄ったために、動くときにポンプの音だとかがしますので、そのためにコンクリート壁をつくって防音壁ということで、設計を変更させていただきました。","id":"exchange-053"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"これ自体は否定するものではないですし、内容をしっかり説明していただければ、それは議会としても応じるべきだというふうに考えております。先ほど、基礎構造の一部見直しの必要があるというところで、これは事業者のほうから協議を求めてきたのか尋ねました。","respondent":"小林施設整備課長","answer":"向こうから上がってきたわけではなくて、我々の立ち会いのもとに現地で確認をいたしました。そこで変更が生じたので、今後の工事に支障が出るということで、変更の協議をお互いにやりました。","id":"exchange-054"}]},{"id":"topic-04","title":"第４３号議案、大森駅水神口自転車等駐車場整備工事請負契約","agenda":"第４３号議案、大森駅水神口自転車等駐車場整備工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"１点だけ。それはどういう関係にあるのかというのを伺いたいのと、こういう地下のものは大体２つぐらいの種類で、そこの関係を伺いたいと思います。","respondent":"多並公園課長","answer":"今回の工事をする事業者については、今のご説明のように、ゼネコン等、工事会社が構築してまいります。そういう流れになっていくことになります。","id":"exchange-055"},{"speaker":"大沢委員","kind":"質問","question":"全体が進むには非常に検討が必要だということを伺いまして、土地柄を考えて経費がかかる駐輪場をつくったという、方針の変更をされたというところのご意見を伺いたい。","respondent":"田口交通安全担当課長","answer":"どうしても工事が難しいという状況がございましたが、今そういった技術も発達しておりまして、そういった問題もクリアができたと。方針転換があったというのが、歩行者のそういった空間創出ということも謳われておりましたので、そういったことを加味して計画変更をしたものです。","id":"exchange-056"},{"speaker":"あべ委員","kind":"質問","question":"やはりそれぞれあると思うので、初期投資が小さくてもメンテナンスがかかったり、当初の工事金額だけで選んでしまうとどうなのだろうと。だから、どういう順番でどういう契約にされているかというところを説明を求めました。","respondent":"多並公園課長","answer":"１つ目の考え方は、最後、周りを埋め戻す形でやるのが１つ目です。２つ目のやり方のほうがより安全性が高いだろうということで、今回それを選定して、実際にはその仕様で縛った形で工事を発注しているものです。","id":"exchange-057"}]},{"id":"topic-05","title":"第４４号議案、浜川雨水排水管建設工事その２請負契約の変更","agenda":"第４４号議案、浜川雨水排水管建設工事その２請負契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"契約金額、総額としては減なのですけれども、今のお話だと、工事の中身によっては増えたり、また減ったり、その結果減るということですけれども、変更の内容をもう少しご説明ほしいと求めました。","respondent":"和田河川下水道課長","answer":"その縦穴に到達させる予定だったのですけれども、この区道は狭いものですから、そこに大きな深い穴を掘ることができなくなりました。","id":"exchange-058"},{"speaker":"あべ委員","kind":"質問","question":"そこで高くなったというのならわかるのですけれども、安くなったという理屈が逆に今わからなかったものですから、もう少し説明してください。最初からそれをやったら最初から安かったのではないか尋ねました。","respondent":"和田河川下水道課長","answer":"非常に簡単に考えていたものが、今回のこの変更によって、狭い中で分水をやらなければいけないという非常に高度な技術的な検討が必要になりました。","id":"exchange-059"},{"speaker":"あべ委員","kind":"質問","question":"とすると、その設計の変更によって少し安くなったけれども、逆に、今、当初予定されていた形でこの工事を終えることができず、今度、次のステップの工事では、またそれがリスクになったり、予算増の要因になったりする可能性があるという理解でいいか尋ねました。","respondent":"和田河川下水道課長","answer":"検討に要する費用、水理実験では模型が必要になったりとかして、検討が普通の委託の設計よりも莫大に大きくなるというリスクがあるです。","id":"exchange-060"}]},{"id":"topic-06","title":"第４５号議案、浜川雨水排水管建設工事その２（浜川公園人孔等整備）請負契約","agenda":"第４５号議案、浜川雨水排水管建設工事その２（浜川公園人孔等整備）請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"ある程度どういうふうにあらかじめ調査をして進めるというか、その辺をどの程度までまずこの中に見込んでいるのか、そこだけ説明を求めました。","respondent":"和田河川下水道課長","answer":"実施設計と申しまして、実施設計の中では、そうはならないように実施設計の中で台帳等でやっているのですけれども。","id":"exchange-061"}]},{"id":"topic-07","title":"第４６号議案、勝島運河雨水貯留施設建設工事その２請負契約の変更","agenda":"第４６号議案、勝島運河雨水貯留施設建設工事その２請負契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今の説明だけだと、設計変更の理由とかがわからないです。なので、今回、変更という議案なので、どういう事情があって変更するのですというのをもう少しご説明ほしいと求めました。","respondent":"和田河川下水道課長","answer":"主なものを２点取り上げて説明をします。これは下水道局と品川区との協議の中で、それからその検討結果に伴う鉄筋の増、この辺の変更によって９００万円余の増ということになったものです。","id":"exchange-062"},{"speaker":"吉田委員","kind":"質問","question":"すみません、今のご説明の一番最初のところ、十分に記憶できていないのですが、防水のコンクリートを取っ払ってからのつもりが、それをやると水が入ってきてしまう関係で、そのことについての検討は、工事を始めてみてそういう危険性があるということがわかったという理解でよろしいのか尋ねました。","respondent":"和田河川下水道課長","answer":"設計には、そういう事実がわからないときから防水コンクリートというのはありまして、そうなるとシールドを発進できません。これは残したほうがいいということで、今回、変更で残させていただいたものです。","id":"exchange-063"},{"speaker":"あくつ副委員長","kind":"質問","question":"ちょうど１年経ちましたけれども、すべき事項というところに、あと工期の変更というところが入っています。我々はチェック機関ですから、そこについてどのように区はお考えになっているのか、お聞かせほしいと求めました。","respondent":"立川経理課長","answer":"やはりそれまでちょっとした変更とかがあったとしても、そういった話がやはり全国的にはあったのかなというふうに認識しています。区といたしましては、品確法の運用指針に則りまして、今後とも、契約変更等につきましては柔軟に対応していきたいというふうに考えてあります。","id":"exchange-064"}]},{"id":"topic-08","title":"第４７号議案、勝島運河雨水貯留施設建設工事その２（池上通り取水管等整備）請負契約","agenda":"第４７号議案、勝島運河雨水貯留施設建設工事その２（池上通り取水管等整備）請負契約","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"それで改めて確認なのですけれども、全体の計画は今どのくらいまで行っているものなのか。例えば今回の工事でこのくらいまで行って、そういう全体像の中での位置づけというのが表現できるのであれば教えていただきたいというのが１点。","respondent":"和田河川下水道課長","answer":"予定ですけれども、今のところ平成２９年度中に完成の見込みがついてございまして、７割方来ているのかなというような状況です。今回の池上通りの取水管等整備の工事でこの工事も完了する予定ですので、これも平成２８年度中に終わる予定ですので。","id":"exchange-065"},{"speaker":"あべ委員","kind":"質問・要望","question":"品川区としての大切な要望を１００％実施されているということで、改めて感謝したいと思います。もちろんいろいろな事態があって少し延びることはあっても、基本的に、これで全て項目としては終了するというふうに理解してよろしいのか尋ねました。","respondent":"和田河川下水道課長","answer":"計画では、平成２８年度中に勝島は全てが終わるです。","id":"exchange-066"},{"speaker":"中塚委員","kind":"質問・要望","question":"何とかしてほしいという要望がすごく高かった地域で、そのためか１点確認と、ちょうど特殊マンホール改造工あたりからでしょうか。そういう意味では、この先どういう感じなるのか、何かあれば教えていただけますか。","respondent":"和田河川下水道課長","answer":"２つ目の質問ですけれども、この工事が大田区側へどんどん進んでいくということはございません。特殊マンホールのＳＮｏ６人孔で止まって終わりというようなものです。","id":"exchange-067"},{"speaker":"須貝委員","kind":"質問","question":"昨年ですか、７０ミリとか１００ミリとか、そういうときには一体どうなるのですか。わかる範囲でいいのですけれども、品川区のこの下流域もそうですが、ちょっと説明を求めました。","respondent":"和田河川下水道課長","answer":"理論上は５０ミリの雨しか受け入れられませんので、瞬間的に８０ミリとか１００ミリ降っても、もっと安心になるのかなというふうに考えております。","id":"exchange-068"},{"speaker":"あべ委員","kind":"質問","question":"ほぼ勝島の工事も終わりというふうに伺ったのですけれども、この工事が終わると、今よりもかなり向上するということを期待してよろしいのでしょうか。かつ、これが、逆に言えば、水質改善の決定打であって、それをもって対策というのは終結になるのか尋ねました。","respondent":"和田河川下水道課長","answer":"下水道局の工事が終わって立会川に水が流れなくなって、ようやく勝島運河の水質改善が完了するということですので、まだ道半ばな状況ということになるかと思います。","id":"exchange-069"}]},{"id":"topic-09","title":"戻りまして、次に(8)第１６号議案、品川区職員定数条例の一部を改正する条例","agenda":"戻りまして、次に(8)第１６号議案、品川区職員定数条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"特に荏原文化センターと国保の執行体制の見直しに伴う減ですけれども、具体的にどういう見直しで１減にそれぞれなるのか、そこを伺いたいと思います。逆に、４減でいくらぐらい減るというつかみの金額みたいなのがあるのかどうか、そこはよくわからないのでお伺いしたい。","respondent":"米田人事課長","answer":"その権限に対する対応をきちんと行う、それから私立の開設に関する支援だったり、今回２つの増をしているものです。簡単に考えれば、４つ増えて４つ減るので、私どものほうとしては理解しています。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"もうちょっと教えていただきたいのだけれども、あっちを減らしてこっちを増やすという、何かそういう見直しなのでしょうか。そこを伺いたいと思います。","respondent":"米田人事課長","answer":"係が９係ありますが、多少事務の効率化が見込めるということで、所属のほうから提案があったものです。こちらについては、所属の提案を受け入れたです。","id":"exchange-071"},{"speaker":"あべ委員","kind":"質問","question":"経理課のほうで、電話交換の方が２人退職不補充ということなのですけれども、これは業務そのものがもうなくなるということなのか、それとも、その職業を充てるのではなくて別の形で人を確保して業務を充てるということなのか、まずそこを説明を求めました。","respondent":"米田人事課長","answer":"電話交換の職員におきましては、旧来は直営でやっておりましたけれども、電話交換業務につきましては委託化を順次進めておるところです。職員の退職の都度に定数を見直してということで、今回、２名の退職がありましたものですから、その分、２名減らしているものです。","id":"exchange-072"},{"speaker":"あべ委員","kind":"質問","question":"平成１２年には都のほうの受け入れもしていますから、実質的には１,５００人以上、定数を減らしているような感じかなと思って見ております。あるいは働く人のコストと、それからクオリティのコントロールというのをどういう形でやってきているのか、その辺は区はどのようにお考えか尋ねました。","respondent":"米田人事課長","answer":"お尋ねの可視化の部分についてですけれども、区を取り巻く事務量というのは、単純に経年で追ってみれば増大の一途だと思います。その増大の一途の中でいかに人件費を抑えていくか、人員の数を抑えていくかというのも一つの指標にはなるのではないかと思っているところです。","id":"exchange-073"},{"speaker":"あべ委員","kind":"質問","question":"差し引きプラスには絶対にしてはいけないという何か区としての内規ではないのですけれども、そういうものはあるのでしょうか。増やすべきところは躊躇なく増やすべきだと思っているのですが、そこら辺の区の全体の考え方というのは、どのようなものなのか尋ねました。","respondent":"米田人事課長","answer":"プラスがあり得ないということではありませんけれども、他区の状況を見ておっても、職員の人員についても抑えていくというような方向で頑張っていく。様々なものを見て、人数の変更がありましたら、この条例での提案ということでのご説明をするものというふうに考えてあります。","id":"exchange-074"},{"speaker":"あべ委員","kind":"質問・要望","question":"日本は公務員の数が先進諸国の中でも人口比では極めて少ない国であって、それは自治体でも例外ではないかなと考えています。サービスの評価をして、それから実質的にどれだけ人件費がかかっているということも勘案しながら、人員削減の計画を立ててほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"須貝委員","kind":"質問","question":"どこかでしわ寄せが来ると僕は思うのです。それはどうなのですか、課長、説明を求めました。","respondent":"米田人事課長","answer":"私の認識といたしましてはほぼ横ばいということで、現在横ばいですが、縮減に努めてまいりたいと考えております。","id":"exchange-076"},{"speaker":"須貝委員","kind":"質問・要望","question":"ここに職員増員してくれないかという要望というのは、相当出ているように感じるのですが、それもないのですか。それとも、ここは増やしてほしいという要望というのはたくさん来ていないのか尋ねました。","respondent":"米田人事課長","answer":"所属の増減の要望を集計いたしますと、当然あまり減らしてくれというような話は来ないので、増やしてくれというような話は来ます。所管とのヒアリング、こちらのほうも査定を行いまして、つけるところにはつけるという姿勢で臨んでいるところです。","id":"exchange-077"},{"speaker":"中塚委員","kind":"意見","question":"必要な体制は当然とるべきだと思いますし、定数を減らすことで、委託など不安定な雇用に置き換えていくという方向も見直しは必要だと私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"吉田委員","kind":"提案","question":"今審議しているのは、今ここでも議論がありましたように、やはり必要な人員というのはきちんと説明して提案するということも必要だと思います。義務教育学校というのは文言の整理の範囲かなというふうに感じまして、定数ということを見て、この条例案には賛成をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-079"}]},{"id":"topic-10","title":"第１８号議案、職員の分限に関する条例の一部を改正する条例","agenda":"第１８号議案、職員の分限に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"その上で、資料に３(2)基準ならびに手続とありますけれども、この中身を少し具体的に伺いたいと思います。区長会と特区連の間でいろいろ協議がされた話は伺っておりますけれども、そこの中身をご説明ほしいと求めました。","respondent":"米田人事課長","answer":"職員の矯正を目的とした研修の受講を命じたりというようなことでの然るべき措置を行った上でもさらに改善が見込まれないというような場合においては。","id":"exchange-080"},{"speaker":"中塚委員","kind":"確認","question":"やはり基準ならびに手続とここに書かれている中身が具体的にどういう労使の合意がされ、ここが大事になってくるのだと思うのです。労使で話し合って合意された中身がどういうものなのか、改めてそこの中身をもう少し詳しく、確認された中身を伺いたいと思います。","respondent":"米田人事課長","answer":"こちらについては、国のほうでもきちんと手順を示して、東京都のほうも同じような形でやっております。条例がこういう形で定められましたら、その指針に則ってきちんと処分を行っていく必要があるであろうというふうに考えているものです。","id":"exchange-081"},{"speaker":"あべ委員","kind":"質問","question":"分限に関する条例そのものはこれまでもあったわけで、分限処分というのも多くはないけれども、やはり行われていたという。このことによって分限処分の対象が事実上広がることになるのか、１つ種類が増えるというふうに考えたほうがいいのか、どういう意味か尋ねました。","respondent":"米田人事課長","answer":"もともと４つあったわけですけれども、条例に定めることがなければそれを行うことはできないというのが、地方公務員法の第２７条に記されております。こちらとしては考えているところですが、制度としては導入をさせていただきたいということで、ご提案差し上げているものです。","id":"exchange-082"},{"speaker":"あべ委員","kind":"質問","question":"お伺いしたかったことは少し違くて、数は多くないですけれども、要は降給以外のものというのは行っていたわけですよね。それとも降給という選択肢が加わったことによって、分限処分の対象となる事象そのものが増えていくのかという、そこをお伺いしたいです。","respondent":"米田人事課長","answer":"所定の病気休業期間を経て、そういったものはこれまでどおり行っていきますが、それと降給が絡むということではありません。しばらくの間は、いきなり適用できるものではありませんが、然るべき処分を行うこともやぶさかではないというふうに考えているものです。","id":"exchange-083"},{"speaker":"あべ委員","kind":"質問","question":"勤務実績をベースにした分限処分というのは、これまでは全く行ってこなかったということなのですか、それが１つ。いわゆる評定、仕事のクオリティとしての評定が非常に悪い状態が続いたらその部分でも降給というのはあり得るのか、その辺はどうなのか尋ねました。","respondent":"米田人事課長","answer":"現在、もともと降給がありませんから、そのほとんどが心身の故障による休職処分であるということでご理解いただければと思います。その中で、実績だったり、こういうものが明らかに不良である場合についての措置を設けさせていただいたというものでご理解いただければと思います。","id":"exchange-084"},{"speaker":"あべ委員","kind":"質問","question":"ＤのＤ評価が３回続いたら基本的にダウンとかというような話は聞きますけれども、分限処分ですから、またちょっと違うのかなとも思います。どういうふうなものなのか尋ねました。","respondent":"米田人事課長","answer":"例えば国の公表されているもので、降給を平成２１年度から何件行われているかというと、実質的には１件というふうに聞いてあります。実績というものはないということですので、これはよほどのことがない限りは適用されるものではないだろうというふうに考えてあります。","id":"exchange-085"},{"speaker":"吉田委員","kind":"質問","question":"それとは別に、降任はせずに降給だけするというふうな、別の分限処分ができたというふうに考えていいのでしょうか。それがさっきのあべ委員のご質問と重なるかなと思いますが、降任させるか免職しかなかったのが、その辺のことを説明を求めました。","respondent":"米田人事課長","answer":"第２７条において条例できちんと降給について定めなさいという形になっていますので、今まで「降給」の文字がなかったものについて入れた。こちらについては、職員の勤務実績ということでもともと、同じような内容でということの担保はできるだろうと考えているところです。","id":"exchange-086"},{"speaker":"須貝委員","kind":"質問","question":"１つだけ質問なのですが、品川区の職員、区の教員はこれに当てはまるのですか。そしてまた、一般の教員、東京都の教員ということになりますが、それも同じような今回のこういう条例に関わってくるのか尋ねました。","respondent":"米田人事課長","answer":"ここでいう「職員の」ということについては、学校の県費負担の教職員については含まれておりません。","id":"exchange-087"},{"speaker":"中塚委員","kind":"質問・要望","question":"恣意的な運用や処分の内容が起きない担保について、基準ならびに手続の説明がありました。労使の合意を尊重する立場から、労使で確認されたこうしたルールをしっかり守ることを強く求めて、賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"あべ委員","kind":"質問","question":"やはりこういう事態になるまでにきちんと指導その他を行っていく、これは当然のことだと思いますけれども、そういったことを全て踏まえた上で、基本としてはこのような処分に至らない職場づくりというのが基本でしょうから、そのことを踏まえた上で、賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"吉田委員","kind":"確認","question":"客観的に見れば、もう少し客観的な指導が入るのかなというふうに理解できますので、そちらの方向がいいと思います。降給をするか否かの評価についても、やはり客観的な指標に照らし合わせるということを確認させていただいた上で、賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"}]},{"id":"topic-11","title":"第１９号議案、職員の給与に関する条例の一部を改正する条例","agenda":"第１９号議案、職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"簡潔に１個だけ。解説をしていただきたいのと、あと(2)、これも解説をしてほしいと求めました。","respondent":"米田人事課長","answer":"０.１月増えた分をそれぞれ６月と１２月に０.０５月ずつ割り振って、６月期と１２月期を揃えようということで提案させていただいているものです。こちらについても労使合意のもと、施行していくというような内容になってあります。","id":"exchange-091"},{"speaker":"須貝委員","kind":"意見","question":"一応、意見だけ言わせていただきます。やはり国民の実質所得は２年連続下がっているということと、我が会派としては賛成できませんので、一応申し上げておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-092"},{"speaker":"あべ委員","kind":"意見","question":"それぞれ内容に合ったもので、先ほどちょっと話がありましたような、職員のアップは伴わずに支給の割合のバランスをとったということで、トータルでは変わっていないという意味では、それはアップというわけでもありませんので、賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-093"},{"speaker":"吉田委員","kind":"意見","question":"生活者ネットワークは、(4)の、やはり義務教育学校に反対しておりますが、この条例に関しましては、私たちが義務教育学校に反対している理由の本質に関わるところではなく、規定の整備の範囲と認めますので、これには賛成をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-094"}]},{"id":"topic-12","title":"第２１号議案、品川区特別区税条例の一部を改正する条例","agenda":"第２１号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"大きく２つですけれども、具体的にどういう事態でどういうことになって、こういうのは例示というのは出しにくいのでしょうか。もう一点、マイナンバーにかかわって、軽自動車等の記載事項の変更ですけれども、記載しないと申請者に不利益はあるのか、ここを伺いたいと思います。","respondent":"黒田税務課長","answer":"現在の資力とか今後の納付見込みを伺いながら滞納を解消していくというのが、基本的な流れになろうかなというふうに考えております。２点目のマイナンバーにかかわる、書類には書く欄があるというふうにご説明申し上げますが、そういった意味から不利益はございません。","id":"exchange-095"},{"speaker":"あべ委員","kind":"質問・要望","question":"その３つの条文、３つの手続だけで、ほかには今後も該当してまた改正になることというのはないのかということが確認です。それから３つ目も同様のことで、必要な条文というのはこの部分だけなのかという確認をさせていただきたい。","respondent":"黒田税務課長","answer":"１点目の猶予制度に関して、大きく変更になるものはございませんで、要件が変わるというようなものではございません。こちらも昨年の１２月に政府が新年度の税制を検討する中で、これ以外に区条例を変更するものはないというふうに考えております。","id":"exchange-096"},{"speaker":"あくつ副委員長","kind":"質問","question":"今までも地方税法上は、換価の猶予制度であるとか、徴収の猶予制度というものは定められていたと。事実上の猶予ということで処理をしている自治体もあるというふうに聞いていますけれども、品川区はその点はいかがなのか尋ねました。","respondent":"黒田税務課長","answer":"今ちょっと払えないから１回のところを４回で払えないかということで、平成２６年度実績で２１件、徴収猶予をしております。災害・盗難・病気等、これに該当するのかというところを納税相談の中で伺いながら、制度について適用してまいりたいというふうに考えております。","id":"exchange-097"},{"speaker":"あくつ副委員長","kind":"質問","question":"相談の中でということだと思うのですけれども、これは救済制度ということでつくられたはずなので、これは自治体が周知する必要があると。今までと変わらないということではなくて、周知していく必要があると私は思うのですが、その点はいかがか尋ねました。","respondent":"黒田税務課長","answer":"周知の点ですが、条例が改正されて制度が新たに新設されたということにつきましては、広報紙などで周知してまいります。ただ、今後の納付計画を早く立てていただくということが非常に重要ですので、税の啓発とあわせて広く周知してまいりたいというふうに考えております。","id":"exchange-098"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"法制度が変わって条例も変わるということで、内容が変わらないということではないと思いますので、もちろんこれは公平、公正な立場に立って税を徴収していただかなければいけないのですけれども、これはそういう意味では周知をしっかり、先ほどありましたけれども、やってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"吉田委員","kind":"確認","question":"大変マイナンバーに関してはこれは大きなところだと考えておりますが、この条例自体は法に伴って変えていくということで、それは必要だと思います。ご説明の中でマイナンバーを記載しなくても不利益はないということを確認いたしましたので、その点引っかかりますが、全体としては賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701406?Template=document&Id=2038#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":86112,"voices":360}},{"id":"h28-20160223-6","meetingId":"h28-cm02","date":"2016年2月23日","dateIso":"2016-02-23","committee":"区民委員会","time":"午前１０時００分～午前１０時５１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)、平成２７年国勢調査","agenda":"はじめに、(1)、平成２７年国勢調査","exchanges":[{"speaker":"田中委員","kind":"質問","question":"この調査員事務説明会の内容が、わかりにくい人のほうが多いのですけれども、それについてどう考えられていますか。改善点などありますか尋ねました。","respondent":"久保田地域活動課長","answer":"説明会に来られる調査員の方は、その辺は次回以降、また工夫をしなければいけないかと考えています。いずれにしましても、正確な調査を実施するためには、きちんとした説明が必要だと思いますので、こういった意見を踏まえて改善に努めてまいります。","id":"exchange-001"},{"speaker":"たけうち委員","kind":"質問","question":"設問４の6)のご意見ですけれども、最初に行ったときに、インターネットでやりますという方は１回で済むのでしょうか。こちらをどうぞということは、総務省とかいろいろな関係でできなかったということで、こういう意見が出ているという理解でいいのか尋ねました。","respondent":"久保田地域活動課長","answer":"２３区の中では、インターネット回答と同時配布は困るということで、注意がきたところではあります。ですから、こういった点も総務省のほうにも伝えて、次回以降の改善に努めていきたいと考えています。","id":"exchange-002"},{"speaker":"たけうち委員","kind":"質問","question":"どうしても１回会わないことにはどうしようもないわけですから、調査員の訪問回数とか負担はかえって増えてしまっているのかという印象もあります。一方で、総務省としては、なぜ同時配布がだめなのかというのが、もしわかれば。","respondent":"久保田地域活動課長","answer":"インターネット回答についても、回答がなくて、訪問回数としては１回増えてしまうのかと思います。インターネットの回答率を高めるといいますか、まずインターネット回答からやってほしいという指示がありましたので、そういうことで。","id":"exchange-003"},{"speaker":"たけうち委員","kind":"意見","question":"負担の低減ということで、その場でインターネットはできないという方については、できるような形にしてほしいということを言ってほしいと求めました。","respondent":"久保田地域活動課長","answer":"私どもも問題意識を持っておりますので、事務の改善につながることについては、今後、積極的に申し入れていきたいと思います。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"なぜインターネット回答を定着させたいのかわかりますか、わかったら説明を求めました。","respondent":"久保田地域活動課長","answer":"やはりインターネット回答ということであれば、回答する側も非常に容易に回答ができるということです。インターネット回答は、スマートフォンでもできますので、どこにいても回答ができるという利便性がありまして、それを普及させていきたいです。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問","question":"私個人的には、インターネットが回答するのは怖いと思うところですけれども、人によるのでしょうか、回答する側の利便性を考えてのインターネット回答の普及ということか尋ねました。","respondent":"久保田地域活動課長","answer":"回答する側のほうのことを考えて、インターネット回答を普及させていこうというものです。","id":"exchange-006"}]},{"id":"topic-02","title":"永年継続事業所顕彰","agenda":"永年継続事業所顕彰","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"創業年数１００年以上で、７０年以上継続しておられる事業所ということなので、上から順にってそんな感じなのですか。表彰する対象として選ぶ基準というのは、そういうことなのか、そのあたりを確認したいと思います。","respondent":"山崎商業・ものづくり課長","answer":"それから、一つ特徴としましては、１００年以上の創業年数を持っているのですが、品川区での年数が例えば１桁の企業も１０社ほどあります。そうしたこともございまして、地域に対しての貢献という意味で、品川区内年数を、今回は重視して選定させていただいた経過です。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"整理していっていただきたいと思うし、品川区がそういう事業所を別の角度、視点で見直せるという感じがして非常に嬉しい報告だったと思っています。改めてわかった時点で報告なり、パンフレットなりにしていただけるといいかと、そう思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"それから、何年くらいたったら、この事業を確かめるのかという、計画について教えていただきたい。それから、事業費は大体幾らくらいを見込んでいるかということを説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"こうしたことを勘案して、創業年数は１００年以上ということをキーにしたいとは、今は考えております。来年、再来年、３カ年で事業をひとまとめにしようかと、現時点では考えさせていただいているところです。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"では、事業の見直しも３年でやるということでよろしいか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"２２事業所を顕彰させていただいて、来年、再来年と同様のことをする予定です。そういったことについて、今後しっかり検討して、対応してまいりたいと考えています。","id":"exchange-010"}]},{"id":"topic-03","title":"ウーマンズビジネスグランプリ２０１６ｉｎ品川","agenda":"ウーマンズビジネスグランプリ２０１６ｉｎ品川","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"１回目、あるいは２回目の初期の段階では、はじめから全国を意識してこられたのか。この５年の間に実際に創業されて、そのあたりがもしわかれば、教えてほしいと求めました。","respondent":"立木産業活性化担当課長","answer":"こちらのウーマンズビジネスグランプリに関しましては、第１回の開催のときから、全国から募集するということで開始しております。そういったような形で、非常に地域との融和性といいますか、そういったものが取れているコンテストだと考えています。","id":"exchange-011"},{"speaker":"南委員","kind":"意見","question":"先ほど、区民の方が３人いらっしゃるということでしたけれども、(5)は教育関係のテーマの事業なのかと思ったりするのです。この８件でいいのですけれども、どんな傾向の事業内容なのか知りたいと思いますとの意見を述べました。","respondent":"立木産業活性化担当課長","answer":"武蔵小山創業支援センターがもともと、プラン提出前からいろいろなセミナーや講座で支援している方が６名いるということで。やはり身近なもので、そういった部分でも、今回のプランもそのようなものになっています。","id":"exchange-012"},{"speaker":"松永委員","kind":"質問・要望","question":"先ほど、大会に参加された方が品川区で起業されるときに、紹介のお話がありましたけれども、誰が紹介されたのかということ。女性が決められているのか、何名なのか、誰が審査するのか教えてほしいと求めました。","respondent":"山崎商業・ものづくり課長、立木産業活性化担当課長","answer":"私も２年担当しておりましたので、例えば、高齢者向けの食材を活用したお弁当を製造するという方がいらっしゃいました。それから、もう一方ありましたけれども、参考にそういうようなことがありました。 武蔵小山創業支援センターのセンター長や、男性目線、女性目線で審査員として加わっております。予定しております審査員は５名、そのうち１名が男性の起業家ということで、４名が女性という構成の予定です。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/294647?Template=document&Id=2746#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":15304,"voices":54}},{"id":"h28-20160223-7","meetingId":"h28-cm02","date":"2016年2月23日","dateIso":"2016-02-23","committee":"厚生委員会","time":"午前１０時００分～午前１１時３７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)、大崎高齢者多世代交流支援施設の運営事業者の選定","agenda":"はじめに、(1)、大崎高齢者多世代交流支援施設の運営事業者の選定","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"そのうちの一つが品川区社会福祉協議会だと思うのですけれども、残りの４事業者がどこか。それから、１回目の選定で落とされた１事業者がどこか、それをお伺いします。","respondent":"松山高齢者地域支援課長","answer":"５事業者の名称ですけれども、ＮＰＯ法人のワーカーズコープ、そして社会福祉法人の品川区社会福祉協議会の５事業者です。そのうち、１社不選定だったところは株式会社サンワックス新宿支店です。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問","question":"それから、このプロポーザルの公募についてですけれども、私も勉強不足ですけれども、公募というのは、実際にどういうところにかけるのですか。いろいろ考えてしまうのですけれども、その辺、詳しく説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"そのほかに、問い合わせがありましたところに詳しく説明申し上げました。社会福祉法人につきましては、品川区社会福祉協議会一つです。","id":"exchange-002"},{"speaker":"いながわ委員","kind":"質問","question":"やはり株式会社は法人で、皆法人格は法人格なのですけれども、やはりそういう部分も選定理由になっているのでしょうか。少し信頼性がどうとか、持続可能かどうかとか、やはりそういうことも多少なりとも加味されている選定結果ということなのか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"例えば基本方針、区との連携が取れるか、事業提案。ただ、総合的に見て審査をしたものです。","id":"exchange-003"},{"speaker":"横山委員","kind":"提案","question":"提案内容について、詳しく教えてほしいと求めました。地域とのつながりを活かした提案というのは、具体的にどのような提案か尋ねました。","respondent":"松山高齢者地域支援課長","answer":"１点目が、専門職で運動指導師を常勤職員として雇用する予定ということで、そちらの方による介護予防プログラムの実施の提案がございました。それによりまして、高齢者のやりがいも生れてくるといったような企画内容です。","id":"exchange-004"},{"speaker":"横山委員","kind":"提案","question":"ほかの４事業者で、提案内容として、どうか。もしすばらしい提案があったのであれば、連携したり、それを区として取り入れていけるような可能性や道筋みたいなものはあるのか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"一緒に区民の方と地域の防災について考えるというようなワークショップ形式の提案もあったのですが、実行性とか、難しいところもあります。ゆうゆうプラザも地域の一員として一緒に考えていくという方向性は、将来的には今後、可能性としてはあるかと思います。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"地域との交流が必要だということで、今回、品川区社会福祉協議会は区内にあると思うのですけれども、ほかの４事業者で区内にあった事業所はあるのか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"本社としましては、ほかにはないのですが、一つの株式会社が区内で活動をしているところがあります。","id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"向こうの提案を、その提案内容から、これからの協議になるのか。そこの提案、またそれがどういう形で実施されていくのかという体制について、お聞かせほしいと求めました。","respondent":"松山高齢者地域支援課長","answer":"２点目の人員配置ですけれども、公募をした際に、常勤職員を３名以上配置してほしいということ、その他非常勤の人数は特に示しておりません。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"新しい形の施設ということで、期待されるところだと思いますけれども、委託料は幾らくらいになるのかわかったら、最後に教えてほしいと求めました。","respondent":"松山高齢者地域支援課長","answer":"ホームページの公募要綱のほうにも出させていただきましたけれども、２,０００万円です。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"意見","question":"これは本当に期待している多世代交流支援施設なので、今回の公募要綱、例えば常勤３名以上、できるだけ品川区民ということもあるのかもしれないのですが、ポイントとなる点を幾つかご紹介していただければありがたいとの意見を述べました。","respondent":"松山高齢者地域支援課長","answer":"高齢者を含む多世代交流事業というところで、高齢者と子育て世代の間に交流が生れるような提案、地域との連携ということを非常に多く挙げました。それから、高齢者を対象とした個人の利用の促進ということと、地域との連携、交流事業というのが今回のポイントとなっております。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"提案","question":"ほかのところがまた違う提案をして、それぞれ特徴はあっていいのだけれども、ばらばらという見方も見てくる。今後どういう視点で選定していくか、もちろんお考えがあると思うので、あれば教えていただきたいとの意見を述べました。","respondent":"松山高齢者地域支援課長","answer":"交流事業を実際に実施する回数につきましては、年間４回程度ということで、まずは定めさせていただいています。ただ、企画内容とかは、まだかなり自由度が増しておりますので、そういったことで、どういうふうに標準化していくかという課題はあると考えています。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"意見","question":"選定されるところが決まってきてしまうけれども、私は、それでもしようがないと思うのです。多分、区もそういうふうにお考えなのだろうと思うのですけれども、そこら辺のところもお考えいただいて選定していってほしいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"新妻委員","kind":"提案","question":"一つ確認ですが、私も少し高齢者のこういう場に携わらせていただいた経験がある中で、女性は比較的にこういうところに足を運びやすいのです。男性向けというところでの何かプログラムとか、そういうものが提案された経緯がありましたら、教えてほしいと求めました。","respondent":"松山高齢者地域支援課長","answer":"委員おっしゃられるとおり、確かに男性の方が地域に参加するというのが一般的なというか、全体的な課題になっていると思います。お互いに教えられるような講座ということで、ＤＩＹや男性向けの囲碁、将棋教室といったような提案はございました。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"確かに、男性は何かやるということがないと、なかなか来づらいのかもしれないということもありますので、そこのところで力を貸していただき、またその人脈の中から引っ張っていただいて、多くの男性が参加できるようなプログラムも、ぜひまたさらにご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"そこら辺が大丈夫なのかということが一つ現実的にはあるので、そこの心配を払拭するような内容であれば、教えていただきたいのが一つ。一緒に聞きますけれども、朝と夜といわゆる開設時間、どういう想定をされているのか、お聞きしたいと思います。","respondent":"松山高齢者地域支援課長","answer":"ボランティアセンターの中には、かなり豊富な人材がおりまして、団体や企業と協力して、さまざまなニーズに対応できること。朝９時から９時半ということで、複数で対応するということで、きちんとこちらのほうである程度例をお示ししています。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"大分不安はこれで解消されるのかというお話でした。１００団体くらい登録しているのですかね、そういう方向のご答弁だったと思いますので、ぜひその方向で頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-02","title":"障害者差別解消法施行に向けた区の体制","agenda":"障害者差別解消法施行に向けた区の体制","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"４月から全面施行ということで、今、準備を進めていただいていることと思います。全職員というのは区の施設全てということで捉えていいのか、そこの確認をさせてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"全施設の職員が対象になるかですが、現在のところ、職員対応要領の中に規定するのは、正規職員、臨時職員、教職員を含む形で考えております。","id":"exchange-016"},{"speaker":"新妻委員","kind":"質問・要望","question":"なかなか人数も多いですので、また、それぞれの意識の違いもあろうかと思いますが、着実に進めてほしいと求めました。具体的な応対の仕方、窓口になる方への研修、それはどのようになっていますか。","respondent":"中山障害者福祉課長","answer":"今までも、全てのカウンターの向こう側にいらっしゃる利用者に向けての対応というところで、それぞれの窓口に合わせた対応の勉強をしています。","id":"exchange-017"},{"speaker":"いながわ委員","kind":"質問","question":"「啓発パンフレット・ポスターの配付および掲示」と２点書かれているのですけれども、これはこれだけということですか、「等」とも入っていないので。その辺は特にお考えではなくて、この周知、啓発の方法でいくということでよろしいのか尋ねました。","respondent":"中山障害者福祉課長","answer":"ここに書かせていただいたのは、あくまで啓発をメインとした取り組みということで書かせていただいております。区のさまざまな部署で、それぞれの所管で幅広く、障害のある方が参加できる事業に取り組んでいければと考えているところです。","id":"exchange-018"},{"speaker":"横山委員","kind":"質問","question":"障害者差別解消支援地域協議会は、品川区としては組織していくということなのでしょうか。施設の構造の改善および設備の整備というのは、現在、どのように把握していらっしゃいますか尋ねました。","respondent":"中山障害者福祉課長","answer":"１点目の差別解消に向けた協議会の設置についてですが、現在のところ、これを設置する予定はないです。窓口での対応や、場合によってはメモを書きながらとか、理解の部分でもう少し注意をしてほしいというようなお声はいただいているところです。","id":"exchange-019"},{"speaker":"横山委員","kind":"質問","question":"２点目のご答弁の中ですけれども、どのように整備していくかというところは、計画の中にもう既に入っているということなのでしょうか。先ほどの自立支援協議会のほうからも声を出していただきながら、状況把握の部分から、これから進めていくという計画なのか尋ねました。","respondent":"中山障害者福祉課長","answer":"どういう対応をするか、そこの心がけを、この合理的配慮の中でやっていければよいと思っています。授業を上のほうばかりでやるのではなくて、下におりてきてみんなで授業をやるといった考え方が、この合理的配慮の中には含まれているものです。","id":"exchange-020"},{"speaker":"横山委員","kind":"意見","question":"２点目に意思疎通の配慮、３点目にルール・慣行の柔軟な変更という点において、どういったものを想定していらっしゃるのか。どういうふうに感じて生活していらっしゃるか、その辺について、ご説明をお願いいたしますとの意見を述べました。","respondent":"中山障害者福祉課長","answer":"これから作成する対応要領のほうに載せて、まずは、そこは最低ラインになってくるかと考えております。当事者のお話を伺うとか、さまざまな手法を取り入れながら、できるだけ障害のある方への理解を進めていければよいと考えております。","id":"exchange-021"},{"speaker":"横山委員","kind":"質問","question":"そのような形で、当事者のお話をお聞きしたり、実際にそういった体験をするというような研修内容にしていただけたらよろしいかと考えています。理想値とか、どのくらいの効果を目指してこれから啓発活動を行っていくのか、最後にお願いいたします。","respondent":"中山障害者福祉課長","answer":"啓発の効果を数値ではかるというのは、すごく難しいことかと考えています。まずは、実施計画上の事業としても載せさせていただいておりまして、そこの参加者数のようなものは一つの指標にはなろうかと考えています。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"今も、合理的配慮は何かというところもありましたけれども、合理的配慮の提供の中で、社会的障壁の除去の必要性ということも、理解を深めていくとありますけれども、社会的障壁とかは何か、どう考えているのかということを説明を求めました。","respondent":"中山障害者福祉課長","answer":"何が社会的障壁かというのはちょっと難しいのですが、個々によってそこは違うというのが、この法律の中でもうたわれております。その方に合った対応、理解や生活の不便につながっているのかというところを、個別の場面で考えていかなければいけないと考えております。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、差別解消推進本部を発足されるということですけれども、この構成メンバーが全部長級ということでいいか、その確認。それから、年にどの程度の頻度で行っていくのか、お聞かせほしいと求めました。","respondent":"中山障害者福祉課長","answer":"それから、次年度に向けての運動の確認ということで、今年度内は１回を予定しております。次年度以降につきましては、よほど何かがない限りは、おおむね年２回くらいの開催ではないかと考えているところです。","id":"exchange-024"},{"speaker":"のだて委員","kind":"確認","question":"自分たち抜きに考えないでほしいということが言われておりますけれども、この協議会の中に障害者の当事者がメンバーに入っているのか、確認です。","respondent":"中山障害者福祉課長","answer":"自立支援協議会のメンバーの中には、当事者の方、そして当事者の親の会の方も入っております。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"新しくできるほうでも、やはり当事者の声を聞いていくことが大切だと思いますので、メンバーの中に入れていってほしいと求めました。合理的配慮とか、社会的障壁の除去が実現していけるということでよいのか、確認です。","respondent":"中山障害者福祉課長","answer":"障害者計画のほうは、区の障害者の施策を全体的に網羅したものになります。計画を進めながら、区の障害者施策を進めつつも、合理的配慮の提供をしっかりと伝えていきたいと考えています。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"障害者が障害を感じずに、障壁を感じずに、社会の中で生活できるようにやっていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"簡単に教えていただきたいのは、副区長が本部長のときもあって、これって何か行政の決まり事があるのですか。もしあれば、教えてほしい。","respondent":"中山障害者福祉課長","answer":"ただ、我々行政事業もきちんとした理念を持ちながら個々の場面で説明責任を果たしていく必要があるかと思っています。相談はすごく難しいと思っていまので、今の３点は、私のほうも肝に銘じたいと思います。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"どんな施策がどういうふうに進んで、それをどう進めていくかと、そこがどういう形でされていくのかということが一つ。そしてまた、公開がされているのかも含めて、まずその点について教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"次年度に向けては、年３回開催する予定です。あるいは相談支援部会、それからもう一つ日常生活用具検討の部会、就労支援の部会があるので五つあります。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"一足飛びに、これで障壁がなくなるということは、なかなかならないと思うのです。さらに進めていくためには何が必要なのかと協議しながら、政策も出していくという形での協議会の位置づけということでよろしいのか尋ねました。","respondent":"中山障害者福祉課長","answer":"今年度の自立支援協議会からは、学識経験者の方に委員長になっていただいておりますので、やはりそういう視点は大事かと考えています。それから現場からの声、そうしたものをこの協議会に諮りながら、課題の整理や次に向けての政策提案などができればよいと考えております。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それぞれ要望を、そういうものが反映されるような仕組みに、この自立支援協議会がなっているのかお聞きしたい。２５人という人数は教えていただいたのですが、今、それ以外にどんな方がメンバーに含まれるのかということについても教えていただきたい。","respondent":"中山障害者福祉課長","answer":"そうした声も、自立支援協議会の中にも上げながら、政策は考えているところです。自立支援協議会のメンバーの構成になりますが、相談事業の代表者、そうしたメンバーで構成されているところです。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"かなり具体的な要望がされていて、そういう声が反映されるような協議会に、ぜひしてほしいと求めました。職員対応の要領についても、当事者の意見を聞いてつくってほしいということも、障害者団体の要望書の中にも書かれていたのです。","respondent":"中山障害者福祉課長","answer":"それから、職員対応要領のことですが、今、人事課のほうで素案づくりを進めております。あるいは各省庁で、もう既に対応要領をつくって、パブリックコメントが終わっているところです。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"障害者が自分たちを抜きに決めないでほしいという、素案の段階で、そういう場面をつくっていただきたいと要望をさせてほしいと求めました。区の職員ではなくて、そういうところに対しての働きかけはどういうふうにしていくのかについても、教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"例えば区内の社会福祉法人の職員一人ひとりが、この法施行を受けて、どういうふうに対応するかというご質問かと思います。それから保育園なども入ってきますので、それは各省庁の指針に基づいて、それぞれの事業所が対応していくことになります。","id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"２、実施事項の(2)、どう考えられているのか。この啓発パンフレットの活用は、どういうふうに普及・啓発されていくのかについても説明を求めました。","respondent":"中山障害者福祉課長","answer":"１点目の職員対応要領をいつまでに作成する予定かですが、３月中につくりたいということで、準備を進めているところです。啓発パンフレットのほうは、例えば「こころつながる映画祭」のときに配布したり、そういった関連事業のときにお配りさせていただいているものです。","id":"exchange-034"},{"speaker":"若林委員","kind":"質問","question":"職員対応要領の作成に関してですが、これは３月いっぱいにできるということで、最終的なのか、事前になのかですけれども、いわゆる当事者の方、特に団体の方への説明はされるのか尋ねました。","respondent":"中山障害者福祉課長","answer":"今のところ、対応要領について、団体の方に説明をする予定はございません。服務規定の一環のような形で作成するので、障害者団体の方への説明は予定していないところではありますが、３月に行う自立支援協議会がありますので。","id":"exchange-035"},{"speaker":"若林委員","kind":"質問","question":"では、いわゆる自立支援協議会の中で提示がされて、お話も伺う機会はしっかりと確保、担保してあるという理解でいいのですね。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-03","title":"平成２８年度品川児童学園の運営","agenda":"平成２８年度品川児童学園の運営","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"以前の説明で、障害児者総合支援施設の委託業者が、はじめからこちらもやっていくという理解だったのですけれども、そこの確認をさせてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"現在の福栄会の指定管理期間が平成２８年度末ということになっておりますので、平成２９年度から新しい事業者に運営を委託する予定です。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"それから、児童発達支援センター（本部）のほうが指定管理になっていて、分室のほうは業務委託というのは、何か決まりがあるのか尋ねました。","respondent":"中山障害者福祉課長","answer":"指定期間が１年間残っていての仮移転ということになりました。平成２８年度については、平成２９年度からは、合わせて指定管理という運営にしていきたいと考えております。","id":"exchange-038"},{"speaker":"新妻委員","kind":"確認","question":"準備を進めていただいていると思います。「こみゅにてぃぷらざ八潮」のご利用者へは、この配置図の説明はされているのか、まず、それを確認させてください。","respondent":"中山障害者福祉課長","answer":"文化観光課のほうと相談しながら、どういう形で周知するか考えていきます。ただ、もう既に工事は始まっているので、あそこが変わるということは、ご利用者の方々は皆さんご存知のところかと思います。","id":"exchange-039"},{"speaker":"新妻委員","kind":"意見","question":"移動にあたりまして、「こみゅにてぃぷらざ八潮」のほうには園庭がないという課題が一つあったかと思います。既にもう引っ越しが始まりますので、そこの辺、どのようにお考えいただいているのか、お願いいたしますとの意見を述べました。","respondent":"中山障害者福祉課長","answer":"児童学園にはゆっくり安心して遊べる園庭があるのですけれども、「こみゅにてぃぷらざ八潮」に移転しますのと、専有の園庭の確保が難しい状況です。","id":"exchange-040"},{"speaker":"石田（秀）委員","kind":"質問","question":"いろいろ理事者からもお話を伺って、すごく感動して帰ってきました。本当に世界に発信できるくらいの施設ができるということを改めて感じさせていただいたので、ぜひ前に進めていただければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/540863?Template=document&Id=3440#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":27806,"voices":103}},{"id":"h28-20160223-8","meetingId":"h28-cm02","date":"2016年2月23日","dateIso":"2016-02-23","committee":"建設委員会","time":"午前１０時００分～午後 ２時４９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件整理しています。","topics":[{"id":"topic-01","title":"の順番では、(1)の空き家対策の周知についてでありますけれども、順番を変更いたしまして、先に(3)の今視察をしてまいりましたが…","agenda":"の順番では、(1)の空き家対策の周知についてでありますけれども、順番を変更いたしまして、先に(3)の今視察をしてまいりましたが…","exchanges":[{"speaker":"筒井委員","kind":"確認","question":"確認ですけれども、これ工事費用はお幾らなのでしょう。","respondent":"多並公園課長","answer":"金額といたしましては、７億３,８９５万円余の契約金額ということで、今契約の条件を定めてあります。","id":"exchange-001"},{"speaker":"筒井委員","kind":"質問","question":"当然受益者負担の意味も込めて、利用料とかを徴収すると思われるのですけれども、ちなみにその利用料はお幾らなのかということと、これは品川区民以外にも使えるのかということをちょっとあわせてお聞きします。","respondent":"田口交通安全担当課長","answer":"利用料金につきましては、現在検討しています。区民以外の利用ということにつきましても、現在検討しています。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"向こうが通る場所になるのでしょうかということと、公園の中にあるので、何かそういう工夫はできないものかと。思いではなくて、何か公園の中に馴染むような形になったらいいのにというふうに思ったのですが、いかがか尋ねました。","respondent":"多並公園課長","answer":"３メートルの必ず通行帯を確保しながら、工事の段階で最低でも３メートルあけながら、工事の段階でより広げながら段階的に進めていくとなるようです。その中でも、あまりに奇抜ではなくて、落ち着いた形でデザインを出すつもりではあります。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"何でしょうか、せっかく公園の中につくるものですから、そういうのがあってもいいのではないかと考えています。どういう説明をされていくのか、あと皆さまのご意見がある程度聞こえるところがあれば、どういう反応があるのかをお聞きしたいと思います。","respondent":"田口交通安全担当課長","answer":"それと、あと住民説明会についてですが、一応今月の中旬ということで予定しております。整備後の状況を見ながら、その推移を見ながら、今後どうしていくかというのは検討していかなければいけないのかというふうに考えてあります。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問","question":"機械化ということで、すごくこれがきれいになっていると思うのですが、現況でこの大森地区の放置自転車はどのぐらいあるのかというのを説明を求めました。","respondent":"田口交通安全担当課長","answer":"１月末日現在で８１２台ということで、月平均８１台、前年と比べて放置状況はほぼ同数ですが、撤去台数につきましては、前年比で月平均マイナス１０台です。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"確認","question":"大体これでクリアできれば一番いいと思ったので、そこの確認だけです。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"そういう不安が出されているわけですけれども、この今回設置する機械式駐輪場に関してはそこら辺のところはどうなのかということをお伺いします。済みません、ちょっと１５層のうちの２層分がそうしたものに対応しているというような話も聞いたのですけれども、そこに関してもお伺いします。","respondent":"田口交通安全担当課長","answer":"済みません、１点目の質問は他区の駐輪場の状況。","id":"exchange-007"},{"speaker":"安藤委員","kind":"確認","question":"数字で言うと２８秒とか、２０秒になると思うのですけれども、問題ないという認識なのかどうかというのをちょっとお伺いしたいと思います。現在品川区は１５０円、１日という利用形態ですが、それ以上に高い設定なども可能性として考えているのかどうかお伺いします。","respondent":"田口交通安全担当課長","answer":"ただ、機器のメンテナンス、また定期点検等は施工業者のほうにやってもらうという予定です。料金設定ですが、今検討中ということで、どのぐらいの範囲にするかというのはちょっとまだここでは申し上げられないのですが、今検討しています。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"自転車利用促進の立場から、ぜひ利用しやすい料金設定にしていただきたいという思いがありますので、こちらは要望します。ちょっとやってみないとわからないということなのでしょうか、需要見込みというのですか、考えているのかお伺いします。","respondent":"田口交通安全担当課長","answer":"需要見込みにつきましては、大体１,１００台というふうに考えてあります。そのような予定なので、要は不確定要素が多々ありますので、やはり整備後の状況を見ていく必要があるのかというふうに考えてあります。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。もう少し出た声というのですか、そういった方々からの意見というのはどういったものがあったのか、ご紹介いただけないか尋ねました。","respondent":"田口交通安全担当課長","answer":"２月の説明会ですが、抜本的な見直しということで、２月の説明会では当初の予定を変更いたしますという形で説明をしています。既存の駐輪場は撤去しないのかとか、料金の見直しは行わないのかと、こういった話が主でございました。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"こういった新たな駐輪場ができるということで、私も段階的にでも撤去していくべきだと思うのですけれどもいかがでしょうか。４月中旬の説明会ということですけれども、周辺を含めた自転車対策、そうした内容にしていく必要があると思うのですけれどもいかがか尋ねました。","respondent":"田口交通安全担当課長","answer":"それと住民説明会ですが、一応範囲は大森住宅も含めまして大井水神町会、また大井坂下町会ですとか、こういった方たちを対象に説明会を行う予定です。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういったことも含めて広く説明し、質疑できるような形にしてほしいと求めましたが、もう一度お願いしたいというのが一つです。大森駅前住宅の駐輪場の今後に関しては、ぜひ決めていただきたいというふうに思っておりますが、いかがか尋ねました。","respondent":"松代防災まちづくり部長","answer":"対応をということで話があり、早期の対応をということで対応を検討し、進めてきたところです。台数等の今後の見込み、工法等いろいろ検討した中で、今回１基２５５台というのが可能ということになりました。","id":"exchange-012"},{"speaker":"つる委員","kind":"提案","question":"私もこれ４年前ぐらいには港区で、品川駅前ですか、区内で一時利用というところで機械式駐輪場にできないかというのを提案していたものですから。この１基当たりの２５５台とかいうのは、これ一つ会社とかの規格なのですか、そのあたりまず説明を求めました。","respondent":"田口交通安全担当課長","answer":"今回の施工業者の規格です。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問","question":"これは土地のここの部分からすると、例えば４基、５基とかというスペースとしてはいけるスペースなのですか。今これ３基ですが、３基ということなのですが、例えば４基、５基というと、どのぐらいまでやろうと思えばこのスペースでいけるのか尋ねました。","respondent":"松代防災まちづくり部長","answer":"できることであれば、公園につくるのが当たり前という考えではなく、取り組みができればというふうに思っているところです。この３台、また今ある既存の平置きを少し解消しまして、利用過程等も見ながら進められたらと、このように思っております。","id":"exchange-014"},{"speaker":"つる委員","kind":"質問","question":"増やせという方向性の話ではなくて、公園の中で何％とか、たしかそういうのあったと思うのです。そういう議論はどうなっているかと思ったので、これ今回全体で７億３,０００万円ぐらいで、この辺をわかれば説明を求めました。","respondent":"田口交通安全担当課長","answer":"メンテナンスにつきましては年に３回というふうに聞いてあります。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問","question":"当然民間ですから利益が上がってこないと下に請け負うということはないわけですけれども、わかれば、言えるのであればというところです。","respondent":"田口交通安全担当課長","answer":"ちょっとどのぐらいというのは、ちょっとまだ、申しわけございません。","id":"exchange-016"},{"speaker":"つる委員","kind":"質問","question":"少しでも長く使っていただいて、当然課題解決という部分も含めてやっていただけると、あと安全な運営管理というのがすごく必要とされるかと思います。管理人というのでしょうか、ちょっと上のほうなのですけれども、そのあたりでもし予定とかがわかっていれば説明を求めました。","respondent":"松代防災まちづくり部長","answer":"ですから、当然ながら本体自体のコンクリートの構造物は、通常の普通耐用年数５０年とかそういった形で持つものとまず考えます。そういった形ですので、その１基を集中的にやっているときには空いたところで使うと、こういった形で対応していければというように思っています。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"意見","question":"品川のほうに来ている人、また品川から大田に行っている人という差はあるのか、現在。今後その辺を踏襲していく中でどう考えていくのかという考え方でいいです、金額とかというのはまたとの意見を述べました。","respondent":"田口交通安全担当課長","answer":"済みません、ちょっと大田区の当日利用は１００円と聞いているのですが、ちょっと済みません、定期のほうは今資料がございません。済みません。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"意見","question":"同じなのかどうかということ、品川区の人も大田区の人も同じ料金かということの意見を述べました。","respondent":"田口交通安全担当課長、松代防災まちづくり部長","answer":"区内区外は今一緒です。それと、やはり検討しなくてはいけないと思うのは、区内区外というところの一つの考え方を少し整理しなければと思っています。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですから、ここに差が出てきても止むを得ないかというのは自分の考えだと思いますけれども、その辺はご検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"今の料金の考え方を伺ったのですけれども、その考えの中にあるのかどうか、そういうのはちょっとどうなのか尋ねました。","respondent":"松代防災まちづくり部長","answer":"いわゆる慣例として３割程度というような数字が出たのですが、それが本当に妥当かどうかというのもいろいろと議論があるところだと考えています。","id":"exchange-021"},{"speaker":"高橋（伸）委員","kind":"確認","question":"これ整備工事が２８年５月上旬から２９年３月下旬、地下３１メートルということは事前にこれボーリング工事をしたのか、そのことを確認させてください。","respondent":"多並公園課長","answer":"委員の今のお話のとおり地中に非常に深くつくる工事ですので、事前に設計のときにボーリング調査をもちろんやってございまして、それに沿った形で今回の設計をしているものです。","id":"exchange-022"}]},{"id":"topic-02","title":"の空き家対策の周知","agenda":"の空き家対策の周知","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"済みません、まず、区が確認している区内の空き家数とその確認の方法はどのような方法でやっているのかというのが１点です。それと空き家の中で管理不全状態の数とその確認する方法をお伺いしたいと思います。","respondent":"矢木住宅担当課長","answer":"区内空き家の件数ですが、昨年度実態調査を実施いたしまして外観調査から１,６７４件を確認しております。右側のいわゆるごみ屋敷、廃棄物に起因する管理不全状態にある空き地ですが、こちらのほうは現在１件を認定し、こちらも命令まで行っている状態です。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"このパンフレットのことなのですけれども、表紙が「空き家等の管理は、所有者の責任です。びっくりして終わるのではないかというか、そういう気もするのですけれども、そのタイトルについて区の考え方をお伺いします。","respondent":"矢木住宅担当課長","answer":"ただし、またこれは適宜、今度は有効活用をぜひ前面に打ち出したパンフレットを作成したいというふうに考えてあります。ですので、これでおしまいということではございません。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"これ「ねずみ・害虫等」に重なると思うのですけれども、ちょっとイラスト図と何か「ねずみ・害虫等」というのがリンクしていない。済みません、ちょっと細かい点で、その点いかがか尋ねました。","respondent":"矢木住宅担当課長","answer":"ちょっとこちらを改定する機会には、委員ご指摘のとおり、カラスも何となく入るような形でさせていただければと思います。ありがとうございました。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"その実態はどういうものなのでしょうか。どういうことで代執行まで行く、どうなのかと思っているのですが、その現状をわかったら説明を求めました。","respondent":"矢木住宅担当課長","answer":"そういう崩れているような物件については別対応というふうに考えてありますので、ちょっと具体的な案件については確認させていただければと思います。","id":"exchange-026"},{"speaker":"西本委員","kind":"提案","question":"何でしょうか、そういうのを提案して、ちょっとお聞きしたいと思います。そういう場合には、その廃棄物、ごみ屋敷の分類に入ってくるのでしょうか、それをお願いしますとの意見を述べました。","respondent":"矢木住宅担当課長","answer":"それから、猫にえさをやっているのがごみ屋敷、こちらは建物と敷地というところに関連するところに限定されているというふうに考えてあります。ただし、そういう情報があった場合には、関係所管のほうにご案内というか、情報提供はさせていただいているところです。","id":"exchange-027"}]},{"id":"topic-03","title":"の西五反田二丁目地区のまちづくり","agenda":"の西五反田二丁目地区のまちづくり","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"西五反田二丁目の２１番地が対象地区ですけれども、ビジネスビルのまちというイメージがあるのですけれども、大街区化の住民要望というのはどういうところから出てきているのかという認識をお伺いしたいと思います。","respondent":"溝口都市開発課長","answer":"平成２６年７月に公表させていただきました大街区化に向けてのプランにつきまして、もともと五反田地区、地域の方から意見をいただいたところです。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"どういった方を、もう少しイメージしているのかをお伺いしたいと思っているのですが、それはちょっと後でお伺いさせてください。その辺をお伺いしたいと思いますし、この計画策定の計画というのですか、そこら辺もお伺いします。","respondent":"溝口都市開発課長","answer":"ご回答、区分所有者も含め、全権利者を対象にアンケート調査を実施して公表してきたというのが現状です。ですから、今回の事業につきましても、事業主体としては基本的には新日鉄興亜が行う事業というふうに聞いているものです。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"策定経過をお伺いしたいのと、それと、区のほうからの発案ということでの認識で間違いないのかということはちょっとお伺いしたいと思います。実際何階から何階になるのかというのをちょっとお伺い、今の予定では１３階で、そこら辺はどうなのか尋ねました。","respondent":"溝口都市開発課長","answer":"目黒川沿い、これでいきますと、ちょっと見づらくて申しわけありませんが、２号線、目黒線という高速道路の区間があると思います。私どものほうで駐車場の台数の確保はお願いしていますが、運営については民間の実績に任せていきたいというふうに考えているものです。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"先ほどの目黒川沿いにあった時間制限の駐車区間の施設というのは、そもそもどこがつくっていた施設で、今までの、これから撤去して代替施設になりますが、これまでの時間制限駐車区間施設というのはどこが設置していて、どういった性質の施設だったのかというのをちょっと改めて説明を求めました。","respondent":"溝口都市開発課長","answer":"今現在道路上に設置しております時間制限の駐車区間、実際の設置は公安委員会等、そういったところが設置しながら進めてきている。駐車対策も配慮し、かつ目黒川沿いの回遊、そういったものも含めて今回の計画の中で整備していくというふうに考えているものです。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"そうしたことに対する利用者の、地域の方々の不満みたいなものが来るということは、区としてはどのように考えているのか尋ねました。","respondent":"溝口都市開発課長","answer":"さらに皆さまに桜の時季に楽しんで、散策を楽しんでいただけると、そういったものができる。そういったところのほうのメリットのほうが行政としては、効果としては十分大きいというふうに判断して、今回の計画を進めているものです。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"五反田がまた一つ明るくなると思って、非常にいいことだと考えておるのですけれども、これまだ西五反田二丁目地区のまちづくりの一部です。今後将来どんどんほかの番地のほうもやっていくという理解でよろしいのか尋ねました。","respondent":"溝口都市開発課長","answer":"その地区内であれば進めていきたいと考えていますし、または、このプランのＰＲをさせていただいているところです。同じようなことが起こってくればというふうに考えておりますので、これにつきましては引き続き進めていきたいというふうに考えているものです。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"ある部分をやるとしても、やはりトータル的な動きになっていかないと思うので、その動きというのは何かあるのですか。例えば、いいきっかけにはなると思うのですが、全体的にきれいにしていかなければいけないと思うのですけれどもいかがか尋ねました。","respondent":"溝口都市開発課長","answer":"済みません、添付しました資料の３枚目、参考資料をご覧いただきたいと思います。この緑に囲われたエリア約３０ヘクタールになりますが、また、いろいろご理解いただきながら進めていきたいというふうに考えているものです。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"全体的にまちが新しくなっていくという意味では、かなりこの地域がきれいになっていきますので、特に地権者の方々もうれしいことかと思うのです。なので、進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"つる委員","kind":"確認","question":"ちょっと確認で、８時から２０時、それを超えた駐車となると日曜日というのは無料で停められるのでしたか。日曜日は無料で停められるようになっているとあったから、そこはあれどうだったかという、ちょっと確認なのです。","respondent":"溝口都市開発課長","answer":"その料金を取る取らないとか、制限時間が何時から何時までいいとかというのがあると思いますが、それはたしか駐車できるというふうに理解しています。休みの日停まっているというのは、そのまま停まっているという形で理解をして、今までそれで来ているものです。","id":"exchange-036"}]},{"id":"topic-04","title":"参ります。(4)の品川区要配慮者支援全体計画の策定","agenda":"参ります。(4)の品川区要配慮者支援全体計画の策定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"具体的な中身ですけれども、資料１の第５章というところで、例えば視覚障害の方ですとか、聴覚障害の方に対しての情報提供というのは具体的にどうなっているのか、そうした人たちの情報提供についての記載なども必要なのではないかと思うのですけれども、いかがか尋ねました。","respondent":"鈴木（誠）防災課長","answer":"障害のある方等への情報提供ですが、ご用意しました本冊計画の１４ページをご覧ください。これは聴覚障害の方への対応というようなことで、一般の方も含めて情報発信をしっかりとしていくという規定は記載をしております。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"これは大事なところだと思いますので、引き続き研究、そして必要な改善をお願いしたいと思います。運営する主体になっているというところでは、ちょっと負担が重過ぎると思うのですけれども、いかがか尋ねました。","respondent":"鈴木（誠）防災課長","answer":"確かに地域の防災区民組織は災害時さまざまなことを担っていただくことになっております。ただ、もちろん、それから避難してきた方も対応可能な方も含めて全体で地域の共助でこれに当たるというのが考え方です。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"もう少しそういったところをこのモデル図なり、計画なりに書き込んだほうがいいのではないかという意見なのですが、いかがでしょうか。そうした方々も含め、ちょっとそうした地域センター職員の動きというのを組み込むように改善したらいかがかと思うのですけれども、いかがか尋ねました。","respondent":"鈴木（誠）防災課長","answer":"避難所の対応につきましては、それから学校施設の構造や状況、一律このようにというような形で規定はできないというふうに考えております。２点目のセンター職員ですが、１３カ所にある地域センターにつきましては、区の災害対応時の地域の拠点という位置づけになっております。","id":"exchange-039"},{"speaker":"安藤委員","kind":"確認","question":"ちょっとこの中身でもう少し伺いたいのが、とりわけ発災時ですが、品川区の役割がちょっと弱いように見えてしまうのです。例えば避難行動要支援者の安否確認というところに、防災区民組織の上にあるように、加えるべきなのではないかと思うのですけれどもいかがか尋ねました。","respondent":"鈴木（誠）防災課長","answer":"地域の現場で対応し切れない場合には区から支援を行うというのは除外するものではございませんが、主なものをわかりやすく表示したものですので。区が対応すべきものはこの避難誘導だけではなく、多岐にわたって、区がここの安否確認だけしかやらないということではございません。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問","question":"ちょっとお考えをお伺いしたいのですが、マンパワーの限界という、そういったところもかなり大きいということなのでしょうか。そこら辺の考え方を説明を求めました。","respondent":"鈴木（誠）防災課長","answer":"区が多岐にわたる対応をしなければならない中で、平常時から災害時の必要な業務量に対応する職員を雇用するわけにはいきません。平常時から区がしっかりと対応できるような体制づくり、もちろん区が一番責務を負って対応はしますが、今回の計画も策定したものです。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"ちょっと7)から12)番というのはどういう扱いになるのかというのがよくわからないのですけれども、それでは、そこはもう高齢者です。7)番になるのかと、実際今までの活動、それはどうなのか尋ねました。","respondent":"鈴木（誠）防災課長","answer":"これはあくまで今回の法改正の趣旨が、避難行動の支援が必要な方の対応ということでございまして、一切支援をしないということではございません。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"高齢者はたくさんいて、高齢者をやはり把握しておくべきだろうと。そういうところがあるものですから、もう少し広く、助け合えるようなそういう形に表現してもらえたらうれしいと思うのです。","respondent":"鈴木（誠）防災課長","answer":"ちょっと先ほど説明で漏れてしまったのですが、実はこの全体計画を検討するときに、今ご指摘のあったような情報についても共有をしております。支援について検討する場合には、今後地域での説明と、その辺についても協力いただけるようにご説明させていただいています。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"お宅を訪問して、「元気ですか」みたいなこともやる。そういうところも含めて、ちょっと支援を、町会・自治会への支援というのは何か考えてられるのか。","respondent":"鈴木（誠）防災課長","answer":"ご指摘の区の取り組みは、詳細はお答えできないのですが、その辺の連携なり協力についてはお話をさせていただいているところです。","id":"exchange-044"}]},{"id":"topic-05","title":"の平成２７年度地域防災計画の修正","agenda":"の平成２７年度地域防災計画の修正","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"基本的なことで、区災害対策本部の役割についてちょっと改めてお伺いしたいのですけれども、発災災害時の対応に特化したものなのか、日ごろ災害の程度を低くするために、日ごろからの態勢強化を含めてのものなのか、そこをまずお伺いします。","respondent":"鈴木（誠）防災課長","answer":"災害対応、区の体制についてですが、これについては全て区の地域防災計画に規定をされております。それから実際の発災後の応急対応の時期、大きくこの三つに分けまして、それぞれ区や関係機関等の役割や対応について規定をしているものです。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"済みません、その中で区災害対策本部の役割についてはいかがでしょうか。主に災害発生後の対応に特化したものなのかどうか、それとも、日ごろの態勢構築も含めての役割を果たしていくのか、そこら辺はいかがか尋ねました。","respondent":"鈴木（誠）防災課長","answer":"災害対策本部という本部体制ですが、これは発災した後に設置されるものですので、平常時はございません。ただし、効果的な活動やその態勢づくりについてはさまざまな検討を行い、各毎年度の地域防災計画への修正に反映をさせているところです。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"それとも、品川区としての考え方で修正するということになるのでしょうか、そこをお伺いします。部長級採用というのは昨年４月だったのですけれども、別にこのタイミングという問題だけなのでしょうか、そこら辺はどうなのか尋ねました。","respondent":"鈴木（誠）防災課長","answer":"先ほど要配慮者支援全体計画でも説明しましたように、災害対策基本法が改正されたことで記載が盛り込まれた要配慮者支援についてのみです。それから、この災害対応の強化のための自衛隊元幹部の方の任用につきましては、大体２年ぐらいの期間でじっくりと検討して。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"４月冒頭でそういうふうな考え方があったのではないかと思うのですけれども、それは修正のタイミングということなのかということでお伺いしました。今回全体統括ということで、これまでは本部長が全体統括ということをやっていたということでよろしいのか尋ねました。","respondent":"鈴木（誠）防災課長","answer":"本部長と危機管理官の役割ですが、危機管理監を設置するしないにかかわらず、災害対策本部の全ての判断権限は基本的には本部長の権限です。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひどういった災害対応の経験を積んでこられたのか、改めて聞かせていただきたいのですが、いかがか尋ねました。","respondent":"鈴木（誠）防災課長","answer":"本日ご説明、自衛隊としては具体的な災害対応を、皆さまもご存じのように何度もされております。その部隊の指揮なり対応なりというのを経験されたというところは防災課としても認識をしています。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"実際に部長としてどういった経験を積んでこられたのかというような、どんな災害対応の経験を積んでこられたのかぜひお伺いしたいということなのです。変わらなければ全く新設する意味がないわけですから、ぜひ考えをお伺いしたいのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"こんの委員長","kind":"質問・要望","question":"少し質問の整理をさせていただきたいのですけれども、先ほどのご答弁で委員長としてはご答弁されていると判断をさせてほしいと求めました。防災計画の中の今回はこの三つの点をされておりますので、ちょっとそこは整理させていただきたいというふうに思いますので、質問を変えて下さい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問","question":"区としては今回の部長の採用と新たなポストを新設して、防災力を上げるというふうなことを自らが書いているわけではないですか。どう、それは本人ないということでよろしいのですか、それは意気込みがないということでよろしいか尋ねました。","respondent":"松代防災まちづくり部長","answer":"その中の一つとして、体制強化というところでご説明をしております。深みを持って災害に対応する、このようなことですので、どうぞご理解をよろしくお願い申し上げます。","id":"exchange-052"},{"speaker":"こんの委員長","kind":"質問・要望","question":"今の部長のご答弁でお答えになっていると、委員長としては判断させていただきたいと考えていますので、質問の趣旨を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"それはわかります。経験ある方を区の考えとして採用したわけですから、それを災害対策の強化のために採用されたということなのですから、私は納得いきませんし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"西本委員","kind":"質問","question":"そこがちょっといろいろな名前があるものですからリンクしているのかと、２部とか、どのようにされるのでしょうかということと。そこら辺の整理というのはどういう形にしていくのかということで、説明を求めました。","respondent":"鈴木（誠）防災課長","answer":"２点目の訓練ですが、それから実際の対応の習熟を兼ねて、少し部隊ごとの訓練ができればということで今考えているところです。それから連携につきましては、迅速な対応ができるようにと調整する部分ですので、そこも今回の見直しでより強化されたというふうに認識しております。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、訓練については、すぐにというのは難しいでしょうけれども、計画的にお願いしたいと思います。いろいろなことが起きると、なので、効率的にしていくにも十分に対処してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"}]},{"id":"topic-06","title":"のしながわ防災体験館・しながわ防災学校","agenda":"のしながわ防災体験館・しながわ防災学校","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"幾つかお伺いしますが、この防災ということでいいのかと思うのですけれども、そこら辺はどうなのかというのをちょっとお伺いをします。しながわ防災学校のところの全５コースということなのですけれども、最後にという構成なのかどうか、そこら辺ちょっとお伺いしたいです。","respondent":"鈴木（誠）防災課長","answer":"は基本知識の２０分程度の映像、その対応についての紹介ビデオというようなもので、複数のものをご用意しています。２番目のテーマ研修につきましては、その都度開催をするという対応をしているものですので、順番の前後というのは特に定めておりません。","id":"exchange-057"},{"speaker":"安藤委員","kind":"質問・要望","question":"「やりたいわ、そういった気軽に受けられるほうがいいと思いますけれども、そこら辺はちょっとどうなっているのかというのをお伺いします。予防対策ということの大事さというのも要素としては入れていっていただきたいのですけれども、お願いしたいのですけれども、いかがか尋ねました。","respondent":"鈴木（誠）防災課長","answer":"主に研修に当たる部分が中心ですので、今でも実施していただいている地域の訓練はまた訓練として別の支援の中で行っていただくように考えております。","id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"運用しながら改善できるところは改善、さらに充実できるところは、そういった展示の程度などでも充実していってほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"つる委員","kind":"確認","question":"災害から生き延びることというのが目的とされているわけですから、それが実際どういうふうに動くのかという、そのあたりの確認だけ。","respondent":"鈴木（誠）防災課長","answer":"そこに機械的に組み込まれるものですので、見た目は、カバーを開けて何か機械が見えるぐらいなのです。その辺は現物の展示は予定をしておりますが、実際に動かして落ちる状況を見ていただくかどうかは、今業者と詰めているところです。","id":"exchange-060"},{"speaker":"つる委員","kind":"意見","question":"どうこうというのは想定でしかないのだけれども、そういったことをぜひ今後また詰めの中で少しでも実際に体験していただける、そんなことをお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"},{"speaker":"筒井委員","kind":"確認","question":"ちょっと確認の質問になってしまうかもしれないのですけれども、そのマンション管理組合単位で防災学校を受けられるのかということ。この以上４点伺いたいと思います。","respondent":"鈴木（誠）防災課長","answer":"対応する運営の事業者がありますので、個別対応しますので、個人でも可能です。ただし、コースをこの日に開催というようなところは、施設の利用状況等踏まえて可能な限り対応したいというふうに考えております。","id":"exchange-062"},{"speaker":"西本委員","kind":"質問・要望","question":"この防災体験館の場合は、どういうふうにＰＲをされていくのかと思うのですが、皆さま来てほしいと求めましたし、ただ、あれ２階です。２階に行きづらいのですから、表からあまり見えないのです。","respondent":"鈴木（誠）防災課長","answer":"今回の改修に連動しまして、その辺のサインも検討しております。第２庁舎のほうの３階のロビー入っていただくと、２階にシアター、誘導のサインも設置する予定でおります。","id":"exchange-063"},{"speaker":"西本委員","kind":"意見","question":"例えば防災学校にしても、防災体験館でも、申し込みの必要なものについてはインターネットで申し込みできるといいかと。そういうもので、何かリンクできるようにすると少しいいのかと思うのですけれども、ぜひ今後検討との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"}]},{"id":"topic-07","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"３点お伺いしたいのですが、現在の高さ制限がある地域をもう少し詳しく教えていただけないでしょうか。３点目が、導入の検討を開始すべきだと思いますけれども、お考えをお伺いします。","respondent":"中村都市計画課長","answer":"今大田区では検討中ということで、都市計画審議会は一度行われたということですが、まだ継続というところだです。その絶対高さを設定するための目的、これを明確に、そして慎重に決定しなければいけないということがあると思います。","id":"exchange-065"},{"speaker":"安藤委員","kind":"質問","question":"２点お伺いしたいのですが、やはりそういった声というのは、率直に開発が進んでいる地域であれば出てきているのです。３分の１から２分の１ぐらいの面積がそうした地区になっているわけですが、品川区としては絶対高さ制限をどのように評価しておられるのか尋ねました。","respondent":"中村都市計画課長","answer":"６０メートルという条件ですが、そういった影響というよりも、もう少し大きなまちづくりの観点というところから来るというふうに感じております。高さに応じて、それぞれ目的が皆さまのほうは変えているのかというふうに感じております。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問","question":"ですから、最後に１点なのですが、少ないというふうに思うのです。そういった意味で、私は品川区にこういった導入というのが必要になってくるのではないかと思うのですけれども、それに関してはいかがか尋ねました。","respondent":"中村都市計画課長","answer":"そういった意味からしますと、地域のまちづくり、ご自身のまちづくりに関して認識をうまくお話し合いをしていただくというのも一つ大事だと思います。","id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/862367?Template=document&Id=4164#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":61345,"voices":173}},{"id":"h28-20160223-9","meetingId":"h28-cm02","date":"2016年2月23日","dateIso":"2016-02-23","committee":"文教委員会","time":"午前１０時００分～午後 ２時３９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を76件整理しています。","topics":[{"id":"topic-01","title":"平成２７年度品川区教育委員会の事務事業の点検および評価報告書","agenda":"平成２７年度品川区教育委員会の事務事業の点検および評価報告書","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"この点検・評価報告書をつくる手順というか、ちょっと教えていただきたいです。どこまでの意見が吸い上げられてここに加わっていっているのかというのを知りたいので、その点を説明を求めました。","respondent":"品川庶務課長","answer":"この評価に至るまでですが、教育委員会のほうで大体年間３回から４回にわたって、この教育委員会の事務事業評価についてご意見をいただいています。そういう中で修正等も繰り返しながら、最後にこういう点検・評価表というものをつくっているという流れになってあります。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"どういう機会にどのような、どのようなというか、どういった方たちの意見を吸い上げているのか説明を求めました。","respondent":"品川庶務課長","answer":"年間を通じてご意見を伺っている状況を踏まえまして、このような４ページから５ページの状況でまとめをさせていただいているというような状況です。これは当然教育委員会でやっておりますので、教育委員のほうからご意見を伺って、このようにまとめているというような状況です。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"その中の具体的なところもお伺いをしたいと思いますけれども、４ページと５ページのところで、率直な疑問で質問をします。マイスクール八潮１カ所で対応しているところが、品川区はその辺の対応が緩やかにされているのかどうか、その点も説明を求めました。","respondent":"渋谷指導課長、村尾教育総合支援センター長","answer":"私からは１点目と２点目のご質問にお答えしたいと思います。委員が変わらないで、やはり毎回毎回、実際の改善になかなか活かされるような形につながりにくいというような課題があるです。４番目、マイスクール八潮、不登校の対応につきましては、現在、民間との具体的な連携ということは図っておりません。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"みんなやっているから支援をしていくという意味なのかどうか、ちょっとそこと、ちょっと具体的に教えてほしいのが１点です。全体像をわかりやすく教えてくださったら、その校区外部評価委員と専門外部評価委員のところも含めて教えていただけたらと思います。","respondent":"渋谷指導課長","answer":"指導方法の工夫、改善にも活かせて、何らかの形で見直しをしていきたいと考えているところです。校務関係、これも年に３回ぐらい教育委員会に場所を設定して、さらに客観的に評価を受けていただくというのが専門外部評価というふうなところです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"タブレットとかいろいろ必要な部分が配備されるかどうかというのも大きいところだと思うのですけれども、その辺の方向性をお伺いしたいのが１点です。人員的な問題がちょっと書かれているのですけれども、増員の方向でぜひお願いしたいのですが、そういう方向なのかどうかをお伺いいたします。","respondent":"村尾教育総合支援センター長","answer":"来年度４月から本区のほうで導入する特別支援教室、今、通級指導学級で現在使っているタブレットはそのまま公的に特別支援学級に持ち込んで。保護者との対応であったり、また都費のスクールカウンセラーとの対応であったり、今考えているところではございません。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"６６番のスクールプロモーションが、そうするとフォーラムに向けてプレゼンテーションとかＩＣＴの活用を広げたということなのでしょうか。６９番の勉強合宿のところですけれども、これというのは参加するにあたっては費用がかかったかどうか、別途かかるのだったかどうかを伺いたい。","respondent":"渋谷指導課長、村尾教育総合支援センター長","answer":"ただ、ふだんの授業の中で、または教育活動の中で取り組むことがよいだろうというふうなことで見直しというような形になっているものです。それから食事代、交通費、保険等々で… 私からはオリンピック・パラリンピック教育の中のスポーツトライアルのご質問にお答えします。ただこれは毎回数えてくれという話ではなくて、あまり学校、教員の負担にならないようにというふうには考えているところです。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"私も随分前に委員会で質問したことがあると思うのですけれども、何というのでしょうか、新しいシステムですね。この中で６１名の申込みがあったというようなことなのですけれども、ちょっとここら辺について内容を説明してほしいと求めました。","respondent":"品川庶務課長、野呂瀬学務課長、渋谷指導課長","answer":"大体１００％の方が、おおむね回答をいただいていまして、評価をしています。教育委員会のほうと、あと校長先生のほうとでカウンセリング等で対応をするよ… 私からは３４番の学校事務のＩＴ化についてご説明いたしますけれども、こちらになりますと、システムはもう既に構築されております。… 私から５５番の固有教員に関するご質問にお答えしたいと思います。","id":"exchange-007"},{"speaker":"浅野委員","kind":"質問・要望","question":"何というのでしょうか、もしも本当に重いということであれば、少しいい意味で休んでもらうみたいなところも出てくるかと思うのです。それを継続して使っているということで、あとは習熟ですか、そちらのほう進めていくということだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鈴木（博）委員","kind":"意見","question":"時間がないので、１点だけ絞ってやらせていただきます。１５ページの４８番の給食運営なのですけれども、これは意味がよくわからないので、ご説明お願いしたいのですけれどもとの意見を述べました。","respondent":"野呂瀬学務課長","answer":"これ継続なので、栄養士につきましては、栄養士が今基準では２校に１校の基準で栄養士というのはついております。その体制を今後も継続して、全校食物アレルギー対応というのが重視しているところなのですけれども、この方法については今後も継続してやっていくと。","id":"exchange-009"},{"speaker":"鈴木（博）委員","kind":"質問","question":"この間一般質問とか、特別委員会で何回もその質問をさせていただいているのですけれども、それが配属されていないところがあるということか尋ねました。","respondent":"野呂瀬学務課長","answer":"同じようにアレルギー対応委員会には出席するのですが、配置されている身分が委託で、都の栄養士ではない方もいらっしゃるということです。そのやり方によってアレルギー対応は各校によって、質が落ちるだとか、そういうことはないと考えているところです。","id":"exchange-010"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今年もなかったですけれども。この５０番を見ても一言も書いていないのですが、これは食物アレルギー対応の食器とかを全く買っていないということか尋ねました。","respondent":"野呂瀬学務課長","answer":"給食アレルギー対応という限定した、給食調理機器の整備の中には食物アレルギー対応のもの、そのほかの給食の消耗品も含まれているです。","id":"exchange-011"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これは予算書ではないわけですから、容器をカラーにしたり、いろいろ手が必要だと思うのです。そうすると、この評価に一言も書いていないということは、それに関してはあまり重視がされていないのかなと思うのですが。","respondent":"野呂瀬学務課長","answer":"重視はしております。今現在、給食アレルギーも含めて、その中に含まれているからアレルギーを重要視していないということではございません。","id":"exchange-012"},{"speaker":"大倉委員","kind":"質問・要望","question":"これをつくったこと自体が説明責任を果たしたということになるのかどうかというのを教えていただきたいのと、どういうふうにしていくのか。どういうふうにこの事業を対象としたのかという理由を教えていただきたいのと、意見をいただいている、どういうふうになっていくのか説明を求めました。","respondent":"品川庶務課長","answer":"１点目、区民への説明責任ですけれども、区民の皆様への説明ということでやっているような状況です。こういった意見をもとにしまして、次年度以降の教育委員会の事業について改善等をしているようなところです。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"どこまで出すかというところも考えなければいけないと思いますが、もう少ししっかり果たしましたと言えるような検討をしてほしいと求めました。その後、どういうふうに改善していきましたというような、これに対してはどういった形で出るのかなというのを教えてほしいと求めました。","respondent":"品川庶務課長","answer":"学識経験者の意見をもらうとなっているのですが、これは義務的なところではなくて、任意というような形でもらっている状況です。学識経験者からの意見としてこういうふうに対応したというところは特に項目は設けていなくて、一番最後のほうのページにあります総合評価。","id":"exchange-014"},{"speaker":"大倉委員","kind":"意見","question":"今回の事務事業評価については、前回の意見は反映されて、また来年度については今回のこの意見が事務事業に反映されるということでわかりました。説明責任は、今後どういうふうに検討していくのかというのはとの意見を述べました。","respondent":"品川庶務課長","answer":"は説明の方法についてはやはり他区も当然同じことをやっていますし、ほかの自治体等も同じことをやっています。そういった自治体の動きなども見て、公表の方法については少し研究をしていきたいと思います。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"これがどういうふうに、どういうふうになっていくのかというのがわかれば教えていただきたいのと、少し詳しく教えてほしいと求めました。廃止をどのぐらいされて、どのくらい残していくというような検討があるのか、ちょっと教えてほしいと求めました。","respondent":"品川庶務課長、渋谷指導課長","answer":"要するに４年生から６年生でスタンプカードがほしいという方がいれば、その方については渡していこうというような対応をとろうかと考えております。これはちょっと対応策というのがまだなかなか練れていないところもあるのですが… 私からは互助会の見直しの部分、５７番についてご説明を申し上げます。これは平成２５年当時に検討したときの細かいデータは持っていないのですけれども、これを実際やっているところがないと。","id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問","question":"９２番と１０５番なのですけれども、その辺どううまく連携してといいますか、どうやっていくのかということをお尋ねしたいと思います。かなり相談されている方が多くなったとお聞きしているのですけれども、その辺の数字がわかれば教えてほしいと求めました。","respondent":"品川庶務課長、渋谷指導課長、村尾教育総合支援センター長","answer":"こういった動きを見ながら、必要に応じて何か対応する状況があれば考えていきたいと、このように思っております。このランニングコスト… 私からは９２番のまちの人々に学ぶ授業、それから１０５番の学習支援ボランティアに関してです。今後展開する学校支援本部事業におきまして、効率的… 平成２８年度以降につきましては、平成２８年度においてはこの研究の成果を活かして、この教育については継続していこうという考え方です。","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"就学相談については、先ほどお話ありましたけれども、年度内にできる限りやって、指導して適切に対応してほしいと求めました。区の職員となれば、さらにそれが進むのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"伊藤副委員長","kind":"確認","question":"ここが同じスケールといったらいいのですか、１つのこういう基準で学校を見ていくというものがないと、評価がバラバラになる可能性があるわけです。だから確認したいのは、そういうチェックシートの項目は同じなのでしょうかということを、まずお伺いしたいのですが、お答えをお願いできますか。","respondent":"渋谷指導課長","answer":"どちらかというと主観的にそれぞれの委員にご判断いただいて、学校がした自己評価について、その妥当性について意見をお聞きするというふうな対応を今しています。","id":"exchange-019"},{"speaker":"伊藤副委員長","kind":"質問","question":"だからそれはやり方ですから、どういうふうに学校側が改善して実績を出したかという、その実績を示すところがほとんどない感じがするのです。結果としてこうなりましたという成果というか、そういうところをやはり出す必要があると思うのだけれども、その関連はいかがか尋ねました。","respondent":"渋谷指導課長","answer":"そういった評価を受けた後どうするのか、ＰＤＣＡのＣＡの部分を今後充実させていくというふうな意味合いでも、この外部評価の改善というのは重要だと思っているところです。","id":"exchange-020"},{"speaker":"伊藤副委員長","kind":"質問","question":"すごく何というかな、子どもたちに対して同じ目線の方々が、子どもたちが訴えるわけですから。新７年生に対しては、新入学生に対する学校紹介に使っていくべきだと思うのですが、いかがか尋ねました。","respondent":"渋谷指導課長","answer":"今の副委員長のご提案については、校長会等で周知をして、ぜひ有効活用を図っていただけるようにお話ししていきたいと思います。","id":"exchange-021"},{"speaker":"伊藤副委員長","kind":"質問","question":"いろいろな学校の取組みの温度差はあるでしょうから、一概に言えないのだけれども、全て公立の学校なのです。お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"大倉委員","kind":"質問","question":"すみません。ちょっと１点だけ、先ほどの質問で５７番、これ区の固有教員とかというのはどういうふうになるのかということを説明を求めました。","respondent":"渋谷指導課長","answer":"区の固有教員については、区の一般職員と同じ互助会で福利厚生について担っております。","id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それで今インフルエンザはかなりはやっているのですが、それに関してちょっとお聞きしたいことが２点あるので、２点に絞って聞きたいと思います。１つは登校許可証の問題なのですが、今の品川区の小学校の登校許可証、登校許可のシステムについて、簡単にご説明をお願いしたいのですけれども。","respondent":"野呂瀬学務課長","answer":"何というのですか、主治医というか、クリニックの証明というのは必要ないですよという形で解除をしているという状況です。","id":"exchange-024"},{"speaker":"鈴木（博）委員","kind":"意見","question":"インフルエンザに罹患した場合は発病してから５日間、解熱後２日間、幼児に関しては３日間は登園しないでくださいねと。きちんとその間お休みして、それが全てだという担保が全くないということに関して、教育委員会のほうはどういうお考えなのかとの意見を述べました。","respondent":"野呂瀬学務課長","answer":"例えば１年生で入ってきて、まだ学校のルールとか、そういうものがわからない方についてはきちんと説明していく必要があるかなと考えています。この願については、いろいろ検討した中でこういう形でいこうということになったので、今のところは考えております。","id":"exchange-025"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それを何とかしてほしいということが数年来問題になっていて、当然１つのシステムというのが、非常に真面目で真摯で。何かの形でチェックするような体制というのを、どのような形でもいいからこれは１回検討する必要があると思うのですが、これはいかがか尋ねました。","respondent":"野呂瀬学務課長","answer":"今現在のルールがこういう形で、今そういうご意見があったということを持ち帰りまして、今後検討させていただきたいと思います。","id":"exchange-026"},{"speaker":"鈴木（博）委員","kind":"提案","question":"それが全てだとは言えないのですが、その辺のこともちょっとよく考えたほうがいいのではないかというようなことで、１つ現状と提案をします。あれは実際どのぐらい機能しているのか尋ねました。","respondent":"野呂瀬学務課長","answer":"最低３日はやらなければいけないというのは、２日になるようなときもあるかもしれないですが、それを報告していただいているという状況です。","id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"質問","question":"インフルエンザにかかった小学校などは、６年１組がなりましたというのを学校の中での周知はどういうふうになっているのですか。ほかの児童とか、保護者の方に、お隣のクラスなんかだったらわかると思うのですが、ほかの学年等への連絡はどういうふうにしているのか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"一般的に学級閉鎖または学年閉鎖が起きますと、学校のほうから保護者宛てに臨時の通知文を出すことが多いです。各家庭においても十分注意していただきたいというような通知文を出すのが基本かなと考えています。","id":"exchange-028"},{"speaker":"高橋（し）委員","kind":"質問","question":"１年生などは家に帰っても言えないかもしれないので、隣の学校で学級閉鎖になったかというのをほかの学校の保護者の方はわからないわけです。何らかの方法が、近隣小学校とかのものがわかるような仕組みもできればいいなと思うのですが、いかがか尋ねました。","respondent":"野呂瀬学務課長","answer":"今委員がおっしゃるのは、ポイント的にどこの学校がやっているかどうかというのをお知らせするほうが効果的ではないかというご提案として承って、何らかの方法で考えさせていただきたいと思います。","id":"exchange-029"}]},{"id":"topic-02","title":"臨時福祉給付金","agenda":"臨時福祉給付金","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"臨時福祉給付金のほうで一番上の表を見ると、７３.４３％の申請率ですね。９０％にいかないのだなと思ったのですけれども、これは２月２９日が申請期限ですので、そういった状況は把握をされているのかお伺いいたします。","respondent":"廣田臨時給付金担当課長","answer":"１１月ごろから開始しているのですが、１カ月、サポートするということでご協力をいただいているところです。できる限りで高齢者等の部署と連携をとって探しているところですけれども、なかなか届かないところもあるという現実はつかんでおります。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"確認","question":"それで、裏面の４番のほうの平成２８年度の高齢者向けのものですけれども、これは平成２８年度だけのものでしたか。今のところそういう状況ですか、ちょっと確認させてください。","respondent":"廣田臨時給付金担当課長","answer":"この制度につきましては、平成２９年度から実施される予定となっております年金生活者支援給付金の前倒しというもので、臨時的に行われるものなので、今回限りというふうに国から情報をいただいております。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この３万円では到底、品川区のほうからもよびかけていただきたいなというふうに思いますけれども、いかがか尋ねました。","respondent":"廣田臨時給付金担当課長","answer":"平成２９年度から年金生活者支援給付金を実施予定ということで、満額６万円という制度ということで、そちらが代替になるというふうに聞いてあります。臨時的な今回のものにつきましては、粛々と支給事務をさせていただこうと思ってあります。","id":"exchange-032"}]},{"id":"topic-03","title":"区立幼稚園および保育園等の保育料減額基準等の改正","agenda":"区立幼稚園および保育園等の保育料減額基準等の改正","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"この規則に該当するところがどこなのかをちょっと教えてほしいのと、今までこれに該当した件数があったのかどうか、１点。ちょっと具体的に今までとどう違うのか、不利益が生じないのかどうか、その辺を説明を求めました。","respondent":"竹田保育課長","answer":"それから（イ）の変更する基準の変更内容ですが、今までが大変古い制度でございまして、１段階低いものを適用するということといたしました。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問","question":"若干今までここに該当して、今回新しくなったら受けられないような人が出てくる可能性はあるということですかね。特に2)の（ｂ）の医療費のところとか、今まではここに該当していたけれども、該当しなくなるようなケースが出てくるのか尋ねました。","respondent":"竹田保育課長","answer":"即効性がないこと、収入減のところで疾病等による休職ということで定めておりますので、一定程度はカバーできると考えております。こちらの規則ができた当時と育児休業等の制度が大分変わりましたので、必要性が薄れたということで育児休業等の方は対象外というふうになります。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問","question":"件数はそんなにたくさんないのかなとは思いますけれども、例えば収入減が、疾病以外でも収入が減ってしまうような事態はあり得るのですが、そういうときにこの保育料が本当に実態的に払えないような状況が生まれた場合に、何か救済する手だてとか何かあるのか尋ねました。","respondent":"竹田保育課長","answer":"ご本人様と十分交渉をさせていただいて、分割払い等、ご無理のないようなお支払いを交渉します。ここには記載がないのですが、住民税が免税になった方についても一定の配慮はなされますので、そういった制度もご利用いただいてと考えております。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問・要望","question":"個別に丁寧にということなので、どういうケースがあるか、ちょっと今の段階では私にはわかりませんけれども、ぜひいろいろな事情があって困難なケースについては、個別に丁寧に対応をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-04","title":"区立保育園の民営化対象園および八潮地区幼稚園・保育園の大規模改修","agenda":"区立保育園の民営化対象園および八潮地区幼稚園・保育園の大規模改修","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"ここには基本方針が２番目に書かれているのですが、手続的にこうこう民営化を進めていきますよというものだけではいけないと思うのです。これからもそうですが、書いてほしいなと思いますが、いかがか尋ねました。","respondent":"竹田保育課長","answer":"日頃の乳幼児教育の成果の１つであります「のびのび育つしながわっこ」にも、滑らかな小学校のほうへ入学するための基礎をしっかりと築いていくということが乳幼児教育の基本と考えておりますので、こちらの考え方に沿って進めていくことに変わりはないものです。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはり区の姿勢がどうなのかというのをきちんと書いてほしいし、幼育両方なので、そこのところはよろしくお願いしたいと思います。これなぜ５園なのか、当面と書いてあるので今後の方向性をぜひお聞かせいただきたいのと、いつごろの時期なのかというあたりを聞かせてください。","respondent":"竹田保育課長","answer":"直営の保育園が区内４３カ所ありますので、実務を進めていく上で、４園程度が適当だと考えましてお示ししたものです。まだ流動性があるところですので、乳幼児人口をしっかり見きわめながら、今後の方針については考えていきたいと考えています。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"なぜ５園程度選んだのかというところをお伺いしたのです。この相当数というのはどのくらいなのか尋ねました。","respondent":"金子子ども未来部長","answer":"課長が申し上げたとおり、都内でも全国でも民営化というのは実施されているもので、基本的には問題ないかなとは思っています。今後の方針をまた固めていこうというような考え方ですので、あくまでも程度ということであるということでご理解いただきたいと思います。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"というと、相当数というのはこの５園を検証してみて考えていくということなのですか。そういう大事な５年間であるということか尋ねました。","respondent":"金子子ども未来部長","answer":"あるいは積み重ねていって、区立の保育園、あるいは区立の幼稚園というのは一定程度残したいというのは今の考え方です。ただ、数については今の時点では考えてございません。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問","question":"乳幼児教育の発展のために区立が一定力を発揮してきたというところにおいては、かなりの数、大事だと受けとめていいのでしょうか。ですからそういった意味で、これからがらがら変わっていくということでは困るわけですけれども、その辺のお気持ちはどうなのか尋ねました。","respondent":"竹田保育課長","answer":"今後の相当数ですが、先ほどご答弁させていただいたとおり、まだ決めていないです。決めるにあたっては、今まで品川区として培ってきた乳幼児教育の基本的な考え方は変わらず、充実に努めていくという点では変わりはないところです。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"具体的に伺っていきます。施設規模等と３つ書いてあるのですけれども、どういう基準をもって判断しているのか、ここのところをもうちょっと詳しく中身を説明を求めました。","respondent":"竹田保育課長","answer":"それから三ツ木保育園は築年数が４２年というところで、一定程度適切、そういった建替えの需要もある施設だと考えております。その他、施設規模等、児童の定員等にかんがみまして、今回、三ツ木保育園ということで選定させていただいたところです。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問","question":"この３つをすると三ツ木になったのですか。どうか尋ねました。","respondent":"竹田保育課長","answer":"改築等、建替え等の時期を捉えて民営化するというのは、ほかの自治体等でもよく見受けられるケースです。こういった機会を捉えて民営化していくというのが有効な手法だと考えまして、今回、八潮も対象としたところです。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それをちょっとお伺いしたいのと、もう１回、基本のところの目的のところもお聞きをいたします。区民のためによくなるのか、区政にとってよいことなのか、ちょっとその辺も含めて、民間活力の活用についてもう１回ご説明をほしいと求めました。","respondent":"竹田保育課長","answer":"２園ということで限定したものではございませんが、今後検討を進めてまいりまして、またご報告させていただきたいと思います。区全体の考え方として、民間でできることは民間でというような考え方もありますので、保育ニーズに応えていきたいと考えております。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この官民の分担というのは、品川区はどう考えているのですか。認可保育園の運営、官でできるところは官で、民でできるところは民で、そこの線を教えてほしいと求めました。","respondent":"金子子ども未来部長","answer":"それは再三申し上げているとおり、再開発の地域で年限が今目途５年というふうにされていますので、これを民設民営でやるのは厳しいだろうと。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問","question":"子どもの立場から考えてどうなのかなというところで、ちょっとここは答えていただいていないのですが、これが保育園だったのです。サービスという言葉は私あまり好きではないのですけれども、提供しているという捉え方なのかどうか、ここは質問です。","respondent":"竹田保育課長","answer":"ですから、一概に皆さんが公立を求めているというご指摘は当たらないかと思います。私立の園では公立とは違った工夫をされている園もありますので、メニューを増やすという点ではサービスの向上に当たると考えております。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問・要望","question":"園庭のある保育園がほしい、最近できている株式会社立の保育園、園庭ないではないですか。区立で守ってきて広げてきたというお話をきのうも伺ったのですけれども、ぜひ聞かせてほしいと求めました。","respondent":"竹田保育課長","answer":"総合的に考えて、子どもの健全な育成に寄与しているかです。昨日も申し上げましたが、区立保育園で培ったノウハウ、変わりはないところです。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"意見","question":"ここにいらっしゃる皆さんはどうかわかりませんけれども、あちこち比較をして、見ているのですよ。園庭がきちんとある保育園に行きたいという、これきのうも誰か発言していましたけれども、当たり前の……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問","question":"とめられてしまったので、どこまでいったかわからない。切り離せというのは、園庭の話を話題にするなということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問","question":"そうですか。子どもたちの成長発達にとても影響するのではないかということで質問しましたけれども、その点はどう考えていらっしゃるか尋ねました。","respondent":"竹田保育課長","answer":"保育の質ということから考えますと、そういったところをしっかり管理監督しまして、充実に努めていきたいというのはどこの施設も一緒です。人が働くという面で、一定程度の人がかわっていくということは、致し方ない部分もあろうかと思います。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問","question":"仕方がないという言い方でいいのですか。でも、それが仕方がないという言葉でいいのか尋ねました。","respondent":"竹田保育課長、金子子ども未来部長","answer":"保育士の交代による子どもへの影響については、必要以上に過度に交代することは子どもに対してよくない影響があると考えております。そういった人がかわっても、保育の方針等は引き継がれていくと思いますので、適切な乳児教育… 今回の民営化にあたっては、もちろんこういうことも非常に考慮の対象として大きな要素だとは思っています。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問","question":"そうならないように配慮していくということなのですけれども、どういうことができるのですか。その点はどうなのか尋ねました。","respondent":"竹田保育課長","answer":"別のスーパーバイザーみたいな方が巡回しているというような園もあると聞いております。退職するにはさまざまな理由があろうかと思いますが、定着していけるようにいろいろな手段をとっていきたいと考えております。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問","question":"私はちょっと保育の質のところなので、とても譲れないというか、絶対に保育の質は下げてはならないと思っているので、ちょっとこだわって質問させていただいているのですけれども、保育の質とは一体何だろうというのを常に……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"意見","question":"子どもの権利条約とか言われて載っているのですけれども、それが実際に実現に向かって頑張っているのかなというのは、とても疑問なのです。今の規制緩和の中で国が、私一番最初に基本理念が大事だといって申し上げたところなのですが、ちょっとここのところを読ませてくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"意見","question":"委員長、お言葉ですけれども、言葉とかは掲げられるのですよ。それが実現をしているのか、進行形でどうなっているかというのは……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"意見","question":"子どもの立場を知ってほしいということです。まだ待っててねと言うのはいいけれども、「忙しいのよ」と言って子どもに目を向けなかったり、大人のいろいろな都合であるかと思うのですが……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"子どもの立場から見て。その点をお答えほしいと求めました。","respondent":"竹田保育課長","answer":"今６つの視点を挙げていただきましたが、品川区の保育・教育の中でこういったことも十分加味しながら、質の高い乳幼児教育を進めていきたいという考えには変わりはございません。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この間５,０００万円のお金がかからない、この５,０００万円の中身をどう受けとめていいか、漠然としていてわからないのです。この影響が、この５,０００万円の数字を出してきた根拠というか、この中身をもうちょっと詳しく教えていただきたいです。","respondent":"竹田保育課長","answer":"昨日示させていただいた数字は大ざっぱな数字ですので、また精査して数字についてはお示しさせていただきたいと思います。どういうものがあるのかといえば、もちろん年齢構成等違いますので、人件費等もあろうですし、さまざまなものがそこにはあろうかと思います。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"提案","question":"今回の提案は民営化によって財政負担の低減を行うということなのですが、今、品川区の財政は健全財政でいるわけですよね。８１５億円ある基金を１,０００億円までも増やしていきたいという答弁が決算でありましたが、ちょっとそこが疑問なので聞かせてくださいとの意見を述べました。","respondent":"竹田保育課長","answer":"平成３３年が一応のピークとなっておりますが、それよりもさらに伸びることも考えられます。責任だと考えておりますので、継続的に進められるように、さまざまな手法を考えていきたいと考えております。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問","question":"最後のほうにしますけれども、民営化しないと安定的な、経済的な運営ができていけない、そういうことなのでしょうか。このことに私は民営化が反することであると思って、一生懸命反対の声を唱えているわけなのですけれども、その点どう思われますか。","respondent":"竹田保育課長","answer":"減らしていくというようなご趣旨のことをおっしゃられていますが、保育需要が高まって、あるいは新たな施設の整備等、大きく膨らんでいくことに対して対応していくということですから、現行のものを削っていくということではないので、ご理解いただきたいと思います。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問","question":"民営化をしていかないと、品川区の財政はもたない、パンクをしてしまうということなのでしょうか。お伺いします。","respondent":"竹田保育課長","answer":"今後の需要というのは、推計はできますけれども、確実なものというのはわからないというのが実態だと思います。先手先手で対応策を考えていくというのは大変重要なことだと思いますので、今後、適切な運営ができるようにさまざまに考えていきたいと考えています。","id":"exchange-061"},{"speaker":"浅野委員","kind":"質問","question":"私のほうから何点かお伺いしたいのですが、八潮北・西の保育園の改築ですか、その中で三ツ木保育園というのは４２年経過しているのです。どこを一番やられていくというのでしょうか、老朽化しているのかということも、もしわかれば説明を求めました。","respondent":"竹田保育課長、金子子ども未来部長","answer":"今後、予算計上させていただいて、設計工事を速やかに進めていきたいと考えております。在園児との関係もありますので、今後検討させていただいて、またわかり次第ご報告させていただきたいと思います。１カ所南をあけて、そこに移りながらやっていくという計画を今立てたわけですが、それ以外の方法ではちょっと難しいと考えているところです。","id":"exchange-062"},{"speaker":"浅野委員","kind":"質問","question":"八潮という特殊性というのも伺いました。子どもたちの、そのような保育園を目指してほしいと求めましたし、また民営化についても早く進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"石田（ち）委員","kind":"質問","question":"いただいた資料の４番のところの、八潮地区における幼稚園・保育園大規模改修のところで、八潮南保育園があく、そこを仮園舎として活用すると。そして、ではそれが終わったときは、八潮南保育園の跡地は何になっていくのかはわかるか尋ねました。","respondent":"竹田保育課長","answer":"こちらの工事が最終的に終わるのが大分先になりますので、そのときの保育需要にかんがみまして、その用途については決めていきたいと考えております。","id":"exchange-064"},{"speaker":"石田（ち）委員","kind":"確認","question":"そうすると、保育需要等々を見た中で、また保育園が必要だということになれば保育園になっていくということなのでしょうか。ちょっと確認お願いします。","respondent":"金子子ども未来部長","answer":"これはこれから協議するので、結論はわかりません。その後の南保育園の跡については、これは今後また全ての見通しが立った後に検討していくべきだと考えています。","id":"exchange-065"},{"speaker":"伊藤副委員長","kind":"意見","question":"その中の１つに民営化だと思っているので、ぜひお願いしたいのは、そういう何というか、非常に的確な説明とＰＲをしていかないと、品川区のほうが。民営化に対してですがとの意見を述べました。","respondent":"竹田保育課長","answer":"副委員長ご指摘のとおり、民営化についてはまだこれからの説明になりますので、今後十分ご理解いただけるように、丁寧な説明を心がけていきたいと考えております。","id":"exchange-066"},{"speaker":"伊藤副委員長","kind":"質問","question":"つまり民間になってからは多角的な経営をされて、黒字になって、よく考えてみればここ何年か運賃の値上げがほとんどないわけではないですか。最終的な保育の責任は品川区で責任を持って、民営化も１つの方法として進めていくべきだと思うのですが、いかがか尋ねました。","respondent":"竹田保育課長","answer":"私立保育園のよさ、あるいは公立保育園の役割等、さまざまあると思います。１人でも多くの区民の方にご理解いただけるように十分ご説明すると同時に、向上させていくように我々も全力で頑張っていきたいと考えております。","id":"exchange-067"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"どういう運営主体であったとしても、品川区では保育の水準、サービスは下げませんよと。さまざまな手法の１つとして民営化を検討していく、これはぜひ対処していただきたいことを最後にお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"大倉委員","kind":"質問","question":"１点お伺いします。これというのは以前、今あるものとは違う幼保一体施設を開設するという報告というのは、以前ありましたか。","respondent":"竹田保育課長","answer":"今回保育園等の改築を考えていく中で導き出した考え方です。","id":"exchange-069"},{"speaker":"大倉委員","kind":"質問・要望","question":"そうしたらこれもう１個、こういう新しく八潮がわかば幼稚園の幼保一体施設というのはどういうものなのかというのは、ご報告していただきたいと思うのですが。","respondent":"金子子ども未来部長","answer":"今回、特にこの４番ですね。まとめたところでご報告していきたいと考えておりますので、少しお時間をいただければというふうに考えてあります。","id":"exchange-070"},{"speaker":"高橋（し）委員","kind":"質問","question":"２つなのですが、１つは先ほど公立、それで区立保育園等の応募をしているのでしょうか。訴訟が起きていないというふうに私は伺っているのですけれども、わかる範囲でいいですが、こういうところをこういうふうに進めた結果。","respondent":"竹田保育課長","answer":"基準が満たされない保育園がないように、しっかり指導していきたいと考えております。私の知る範囲では、適切な事業を踏まえまして、それで民営化にしていきたいと考えております。","id":"exchange-071"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"こちらにあるようにじっくりと周知しつつ、説明しつつ、丁寧に進めていってほしいと求めました。これは要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"飯沼委員","kind":"確認","question":"５,０００万円浮くのだけれども、ちょっとそこを確認したいのと、具体的に。果たして財政負担の低減になるのかというのはすごい疑問に、この八潮の関係が出てきてすごく思うのですが、その点についてお伺いします。","respondent":"竹田保育課長","answer":"より慎重に民営化をしていくために、まず公設民営で十分検証しまして、そして民設民営を検討していきたいという考えです。大規模な改築が必要なところもありますので、八潮地区を大規模改修し、その施設は有効に活用していきたいと考えております。","id":"exchange-073"}]},{"id":"topic-05","title":"公有地活用による公設民営型保育園の開設","agenda":"公有地活用による公設民営型保育園の開設","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"必要に応じては延長可能なのかどうか、５年ではまだだなと思うので、延長可能にしていただきたいなと思うのが１点です。3)の計画概要の年齢構成なのですけれども、１歳から５歳となっているので、地域要求とも絡めてどういう検討をされたのか聞かせてください。","respondent":"今井待機児童対策担当課長","answer":"期間につきましては、今品川区では平成３０年末を目途に待機児童の解消を予定しておりますので、その状況を踏まえてとなります。ご案内のとおり、やはり毎年１歳児の受入れ枠というのは担保していきたいと考えておりますので、１歳から５歳の年齢構成と考えているところです。","id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問","question":"１歳児を担保していきたいと、あったらいいのになと思うような、その辺の高い要求とかは特別ないのでしょうか。最後。","respondent":"今井待機児童対策担当課長","answer":"この近隣では八ツ山保育園も１歳児園ですけれども、北品川第二ですとか、近隣にもほかの認定こども園等もありますので、全体の地域バランスとして１歳児で適当だというふうに考えているところです。","id":"exchange-075"}]},{"id":"topic-06","title":"の２、その他を行います。 まず、(1)所管質問","agenda":"の２、その他を行います。 まず、(1)所管質問","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"平成２８年度４月の受入れ枠拡大数、そしてその拡大した枠のゼロから２歳児の内訳、３歳以上の内訳を説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"８３９のうち、ゼロから２歳の乳児の受入れ枠３７６が４月１日時点での拡大数になります。３歳以上の幼児につきましては４６３という数です。","id":"exchange-076"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/462438?Template=document&Id=4878#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":65061,"voices":214}},{"id":"h28-20160223-5","meetingId":"h28-cm02","date":"2016年2月23日","dateIso":"2016-02-23","committee":"総務委員会","time":"午前１０時００分～午後 ２時５８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を79件整理しています。","topics":[{"id":"topic-01","title":"平成２８年請願第１号 雇用促進住宅八潮宿舎存続のための施策を品川区に求める請願","agenda":"平成２８年請願第１号 雇用促進住宅八潮宿舎存続のための施策を品川区に求める請願","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"区に対応を求める請願ということもありますので、幾つか区にも対応について伺いたいと思いますので、よろしくお願いします。この２点、まず伺いたいと思います。","respondent":"柏原企画調整課長","answer":"説明会後に、そういった説明をいたしましたというお話がありましたので、きちんとした対応をとるようにという。その目的に応じたところでの国の判断があって、今、こういう状況になっているものであろうというふうに認識しています。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"この点を少し具体的に住民の方にお話を伺いましたけれども、１０年後はどうなってしまうのかという不安の声も伺っております。区にはどんな声が届いているのかという点を伺いたいのと、区は何を考えているのか、そこも伺いたいと思います。","respondent":"柏原企画調整課長","answer":"きちんと、何か、きちんとお住まいになっている方たちの立場に立った形の対応をというような趣旨のお話をさせていただいているといったところです。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"区からはどういう説明を受けているのか、そこも伺いたいと思うのですけれども、改めてそこは説明をほしいと求めました。築３０年とおっしゃっていましたでしょうか、３２年、区が購入を拒む理由を改めてご説明ほしいと求めました。","respondent":"柏原企画調整課長","answer":"ですので、それに対して何か、区のほうで何かというところではないというところを申し上げているものです。例えば１０年後どうなるかであるとか、では住民の方がどういうふうに対応といいますか、機構なり国のほうが対応するお話をしていくという。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"とにかく住民の住まいの継続を、そういう立場に立つべきだと思いますけれども、２点目、そこはいかがでしょうか。２２億円というように伺っているのですけれども、マンション３棟でこの金額というのは、この辺についても率直に伺いたいと思います。","respondent":"柏原企画調整課長","answer":"東京都に対しては、取得なりそういったところの考え方はどうなのでしょうかというお話は、こちらのほうもしていくといったところです。これはちょっと、そういった趣旨でできている住宅ですので、単純な比較はできないだろうというふうに思ってあります。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"オーナーが変わればオーナーチェンジですから、また退去を求める、借地借家法に基づいて借家人を保護する規定があると私は思うのです。いろいろ仕組みがあるというのは伺っていますけれども、退去を求める、です。","respondent":"柏原企画調整課長","answer":"その八潮の住宅などの施策をどう取り組んでいくかといったところを鑑みながら、住宅の関連部門と検討しながら進めているといったところがあります。それに対しまして、区が、国が行うべき政策、施策に関して、区が税を投入するのはできないといったところを申し上げたものです。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の区の対応では、住民が住み続けられない。区の購入や、閣議決定の廃止・撤回、それを求めていただきたいと強く要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"あるいは、雇用促進住宅であるけれども、もう雇用保険の対象を外れている世代の方もかなりいらっしゃるのでしょうか。そうでない方と、やはりいらっしゃるのではないかと思うので、その辺の把握というのはどうなっているのか尋ねました。","respondent":"柏原企画調整課長","answer":"少し前の情報ですと８軒というふうに聞いていますが、契約の形態が違っているというところは、情報としては知ることができる。それから所得というのは、そういった前段でお話ししたとおりのところでございまして、細かくは把握はしていないといったところです。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"機構に対して、確実にそれを履行するような、区としてはお考えがあるのか。区がその役割を補うというのも、区民への責任としてあるのではないかと思うのですが、その辺のお考えはいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"そのどういった対応をして、検討して進めるのか、説明をしながら進めていく。話の進め方、きちんと対応、区としての対応をするというふうに思っております。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"３３年度末ですか、民間で売却できなければ３３年度末ということで、民間を探す手続きに入る。その辺の見通しの示し方というのはどういうお考えか尋ねました。","respondent":"柏原企画調整課長","answer":"区としての考え方といいますか、対応というのは、どういう対応ができるかというのは考えてみるであるとか。ただ、今、ここでロードマップを何か示せるかというと、そういう状況には、今ちょっとないといったところです。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"機構が自分でやる・やらないを判断し、区としてはお願いはするけれどもその先はどうかわからない、そういう関係なのでしょうか。だとすると、区に対応を申し入れますと言っても、なかなかそれだけでは心もとないのですけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"きちんとした丁寧な対応というのはずっと言い続けている中で、より突っ込んだ対応というのを、地元の自治体として情報をきちんと共有していく。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問","question":"今のところ、機構としては、区に対してどういう、今後の対応について、どのような説明をしているのでしょうか。聞いても、まだ説明がない状態なのか尋ねました。","respondent":"柏原企画調整課長","answer":"年次を、それからそうでなかったときの対応をどうするかといったところのお話を、こちらも情報としてはいただいているといったところであります。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問","question":"売却の手続きや、住民の方々にどのようなフォローを行うかということの対応についてはどのような説明があるのでしょうか、まだないのでしょうか。そこを含めて説明を求めました。","respondent":"柏原企画調整課長","answer":"先ほどちょっと申し上げましたけれども、それに対してどういうふうに対応をとられるかどうかというのは、問い合わせをしているところであります。それに対してどうするというような回答、回答といいますか、まだできていないというところです。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問・要望","question":"ここはやはり、区も責任者の１人として、ぜひ積極的に関与してほしいと求めました。そういう、可能性としてはあったと思うのですけれども、その検討の内容について。","respondent":"柏原企画調整課長","answer":"区の考え方としましては、機構のほうに進めていっていただきたいという考え方で、進めていきたいというふうに思っております。条件とかいろいろ考えたときに、もちろん検討しながらですけれども、現段階でこういう判断をしているです。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"そうすると、築４０年、１０年後。一旦、私の質問はこの辺にいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問","question":"この住宅の目的とするのは、少しずつ変わってきているのではないかというふうに理解するのですけれども、それは違うのでしょうか。説明を求めました。","respondent":"柏原企画調整課長","answer":"雇用促進の関係のところを、その独立行政法人の改革の中で、こういったところで組織が統合していったという流れだろうかというふうに思ってあります。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"この八潮に限らず、やはり、この独立行政法人の目的に合ったような形で実際に機能しているところがあるのではないかと思います。ちょっとこれ、あべ委員の最初のほうのご質問に重なるかもしれませんけれども、その辺のことは把握していらっしゃるのか尋ねました。","respondent":"柏原企画調整課長","answer":"個別の個人的な情報に関しましては、区のほうとして主体的に調査をかけているものではありません。現在も定期借家の中で、一定程度、やはりその雇用促進に関する部分での住宅としての目的を今も果たしているというふうには考えているものです。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"どうもさっきからお話、何か質問したという感じで、お互いの話し合いみたいなところはないのでしょうか。例えば同じテーブルについて、その辺のことをやりとりするというような場面を持つことは考えられないのでしょうか、その辺を説明を求めました。","respondent":"柏原企画調整課長","answer":"それから情報提供というのは、決して文書だけでその返事があるとか、そういう動きでは今はないというところで我々は考えてあります。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"私もちょっとお話も伺ったのですけれども、転勤があるからという方も住んでらっしゃると聞いていますので、いろいろな事情の方があると思うのです。だから、その辺の、きめ細かな施策ができないものなのだろうかというふうに思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"お住まいになられている方の、その先を見たところでのきちんとした対応といったところを、我々としても機構のほうとお話ししながら進めていきたい。","id":"exchange-018"},{"speaker":"吉田委員","kind":"意見","question":"今現在、そういうふうに申し入れをしていて、それでも機構としてのその対応があまりないということで、こういう請願が出てきたのではないかというふうに思うのですけれども、その点につきましては今後どのように捉えられるのかとの意見を述べました。","respondent":"柏原企画調整課長","answer":"この対応につきましての中身、説明会の資料であるとか、おそらくないのだろうというふうに思います。機構のほうで検討しているところではないかと思いますけれども、それが先ほど来、丁寧な対応をしていただきたいというところに。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"だからもうちょっとやはり何か、例えばこの請願を判断するのに、１回機構からのお話を委員会として聞くなどということは無理なのでしょうかね。ちょっとそれは委員長に対する質問になるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"吉田委員","kind":"提案","question":"最後に、ではちょっと意見としては、もう少しやはり機構が今どういう対応をしているのか、総務委員会として聞いてはどうかなということ。こちらは皆さんへのご提案ということで、一旦やめますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"これは準拠されるかどうかわかりませんが、借地借家法というのがあるわけですから、机上の空論で。それとそこに住んでいる方たちですから、月に１回でもいいし、やはりそういう話し合って持っていくしかないと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"本多委員","kind":"質問・要望","question":"昭和５９年の運営開始から３１年強なのですが、その間の背景をちょっと教えていただきたいのですけれども、ニーズが当時相当あったと思うのです。その辺の時代背景というのを何か、もし把握されていたら教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"働いていた方々が、別のところに移って仕事をされるというようなときに、大きな人数の方がいろいろなところに移っていく。それに対して個別の調査をかけているわけではありませんので、今現在の社会情勢の動きとか、これは事実ではないかと思います。","id":"exchange-023"},{"speaker":"本多委員","kind":"質問・要望","question":"この請願の気持ちを区がどう考えるのかという審議をやっている中で、３３年度末の延長を政府に求めてくださいとか、区は誠意に応えているわけです。とりあえず終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"先ほどご答弁の中で、機構からの一方的な通知があったと、最初は多分、そういったところもあったと思うのですけれども、丁寧な対応を求めていく。求めていくというまでご答弁はしていないかもしれませんが、先ほどのご答弁の中で、そこについてはちょっとお聞かせほしいと求めました。","respondent":"柏原企画調整課長","answer":"給付者の方への対応というのは、その件に関しては、どういった対応をとられるのか。この方はこうします、あの方はどうしますというお答えはないですけれども、考えられるのではないでしょうかというお話はさせていただいているです。","id":"exchange-025"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"今のご答弁に関することでちょっと１点だけ念のために確認させていただきたいのですが、何か情報があるのかどうか。購入に限らず、何かそのほかの手段で自治体がそういうふうに関与した部分があるのかどうかという、何か情報があればそれを教えていただきたいです。","respondent":"柏原企画調整課長","answer":"県であるとか、ちょっと購入の形態をとっているかどうかは調べ切れていないのですけれども、取得に向けた動きをとっているという話は聞いてあります。","id":"exchange-026"},{"speaker":"あくつ副委員長","kind":"確認","question":"東京都ではないということ、今のところはつかんでいないということは確認させていただきました。繰返しの答弁になってしまうかもしれませんが、そこについてもう１回説明を求めました。","respondent":"柏原企画調整課長","answer":"丁寧な対応というところで、責任を持った対応をできるかというのは、そういう形で進めていければです。","id":"exchange-027"},{"speaker":"あべ委員","kind":"質問・要望","question":"築３２年、４０年弱ぐらいのものが更地になってしまうもったいなさをどうやったら回避できるのかという視点も、それを何とか回避できないかなと。もう日本がどんどん使い捨て社会になってしまうというのは、もったいないと思っているのですけれども、その辺のお考えはいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"ちょっと難しいお話だろうと思います。今の段階で、それをこうですというような判断が、ちょっと言いづらいかというふうに思っております。","id":"exchange-028"},{"speaker":"大沢委員","kind":"質問・要望","question":"やはり様々な工夫を凝らしていただきながら、この雇用促進住宅の居住者の方に対する対応に当たってほしいと求めました。そこの微調整は、今後される、その場合になったら、していく必要があると思うのですけれども、どうか尋ねました。","respondent":"柏原企画調整課長","answer":"先ほど来、お話し申し上げている雇用促進住宅というところには１つの目的を持った考え方があって、ということも変わっていったところがあります。もう少し大きな考えのところで、区としての申し入れであるとか、話していくといったところが大切なのかというふうに思っております。","id":"exchange-029"},{"speaker":"大沢委員","kind":"質問・要望","question":"このことに関しては、最終的には国の管理する、この部分に関しては、私は、国の政策判断に任せるべきだと思いますので、区は、先ほどお話をしたように、各々のいろいろな部分の制度をうまく使いながら、この居住者の方たちに対する今後の対応をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"中塚委員","kind":"確認","question":"どういう規定になっているのか、そこだけちょっと確認したいと思いまして。判断は判断で置いておいて、委員会条例上の仕組みだけ、ご説明をいただけたらと思うのですけれども、よろしいか尋ねました。","respondent":"原区議会事務局長","answer":"委員会条例、品川区の中には当然ございまして、その中に、公聴会の開催があって、あるいは参考人というような位置づけが各条項の中で持たれると。それは委員会が決定した場合においてという、当然のことながら判断があってというような、そういうような仕組みになってあります。","id":"exchange-031"},{"speaker":"本多委員","kind":"質問","question":"申し入れのとおりにするのであれば、結論を今日出さないで継続に、今日の招致は難しいでしょうから継続になると思うのです。結論については、願意に、思いはわかりますが、願意、区が買うとかは難しいと思いますので、不採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"議論の中で、参考人招致の動きについて議論をしたいと言うのであれば、継続にするということもあり得るとは思いますけれども。結論を出すということと、雇用促進住宅八潮宿舎の存続のための施策を品川区に求める請願は十分に理解できますので、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"あべ委員","kind":"意見","question":"閣議決定が９年前になされて、全国で同じような状況が進んでいる中で、ここをひっくり返す方向というのは、なかなか、私、困難だと考えています。結論としては不採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"須貝委員","kind":"質問・要望","question":"要望としては、品川区は、今後も、やはり機構に対しては、住民に誠意ある対応をしてほしいということで、今後も要望してほしいということ。今回の請願に対しては、私は反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"吉田委員","kind":"意見","question":"私も、まず一番大事なのは、住んでいる方たちの将来の居住を確保するということかというふうに思います。ぜひ機構の方たち、誰か住民のそういう思いを持った方たちの話もきちんと聞いて判断すべきというふうに考えて、継続を主張したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"}]},{"id":"topic-02","title":"平成２８年度都区財政調整","agenda":"平成２８年度都区財政調整","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"端的に３点だけ伺いたいと思うのですけれども、まず資料の３ページの、区の具体的な事業で言うとどこに当たるものと区は考えているのか。現状で思う区の見通し、こういう規模がどういうふうに続いていくのか、そこの考えを伺いたいと思います。","respondent":"秋山財政課長","answer":"今後どうなるかというのはなかなか見通しとしては難しいものですけれども、このようなことがずっと続いていくというふうには当然考えてございません。今回はこういう結果になったということで考えるところです。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"というように伺ったのですけれども、区の判断で使うものですから、縛り方というのは違うのは違うのでしょうけれども。財政の健全化対策、これらは具体的に区でいうとどこの部分が入るかというふうなのが、それはご説明ほしいと求めました。","respondent":"秋山財政課長","answer":"それから耐震診断支援ですけれども、平成３２年度までに９５％ということで、その算定を継続するというものです。充当にかかわる部分で、まだ照会をされていないものについて算定をするという、そういうようになっております。","id":"exchange-038"}]},{"id":"topic-03","title":"休憩前に引き続き、総務委員会を開きます。 次に、(2)品川区シティプロモーション","agenda":"休憩前に引き続き、総務委員会を開きます。 次に、(2)品川区シティプロモーション","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"意匠登録というか、何らか、そういう独占的に使えるような法的な対応というのはなさっているのか教えてください。もちろんしていると思うのですけれども、一応、確認で。","respondent":"中元広報広聴課長","answer":"缶バッジのほうは５,０００個を発注いたしまして、３月１０日頃に納品の予定です。メガホン型のものと、あと文字だけのロゴの３タイプにつきまして、商標登録の申請の手続きをしています。","id":"exchange-039"},{"speaker":"あべ委員","kind":"意見","question":"ということは、コースターは、コースターとして使ってもらうというより、コースター型の、何というか、チラシといいますか、そういうイメージなんですね、わかりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"あくつ副委員長","kind":"質問","question":"これは今後４,０００個発注をして、納入されたということですけれども、どういう形での配布を考えられているのか。もしくは販売等を考えられているのか、ちょっと伺いたいと思います。","respondent":"中元広報広聴課長","answer":"実費程度ということで考えておりまして、ピンバッジのほうは１個１００円で、缶バッジのほうも１個１００円ということで考えています。コースターのほうが、ちょっと両面印刷なところがありまして、単価としては１枚２０円ということで予定しています。","id":"exchange-041"},{"speaker":"あくつ副委員長","kind":"質問","question":"欲しいという方がいらっしゃったのですけれども、販売する場所というのはどちらになるのですか。細かいことですみません。","respondent":"中元広報広聴課長","answer":"もう準備をしています。ただ、納品されたものがコースターだけですので、まだ、バッジ等につきましては４月からの販売、頒布の予定です。","id":"exchange-042"},{"speaker":"大沢委員","kind":"意見","question":"ちょっとごめんなさい、指摘だけで結構です。ちょっと今思い出したものでとの意見を述べました。","respondent":"中元広報広聴課長","answer":"すみません、ちょっと私のほうで、その辺の事実関係を確認をさせていただいて、正しい認識をしていきたいと思います。","id":"exchange-043"},{"speaker":"大沢委員","kind":"質問・要望","question":"２月下旬にホームページ完成予定ということで、ちょっとそこのところをご留意いただきながら見てほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]},{"id":"topic-04","title":"コンビニエンスストアにおける個人番号カードを利用した住民票等の交付サービス","agenda":"コンビニエンスストアにおける個人番号カードを利用した住民票等の交付サービス","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"住民票の写し、印鑑登録の写し、納課税証明書というものの発行件数というのですか、見込みをそれぞれ伺いたいと思います。まず教えていただきたいのが、赤いラインで返ってくるという、そういう流れになるのか尋ねました。","respondent":"仁平情報推進課長","answer":"１点目のご質問の交付見込み、今後サービスを開始した後でどのぐらいを見ているかですが、今のところ予定しているです。それぞれの機器の間ですが、専用回線のほうで通信されますので、閉じられた世界のネットワークという形になります。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"今度はコンビニにあるマルチコピー機になるわけですから、伺いたいと思います。いろいろこう、そんなに珍しい話でもないだけに非常に心配なのですけれども、その点についてはいかがか尋ねました。","respondent":"仁平情報推進課長","answer":"２点目のご質問の、区民の利便性を向上させていく１つの手段というふうに考えておりますので、十分に気をつけていただきたいと考えるところです。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問","question":"これは区が決めたわけではないからあれですけれども、ちょっとどういう、なぜ４桁で大丈夫なのかというのは、１点聞きたいと思います。マイナンバーにかかわる、今までかかったお金もそうですけれども、全体のお金がどれぐらいかかるのか、そこを伺いたいと思います。","respondent":"仁平情報推進課長","answer":"来年度予算まで含めますと、２７年度は決算の見込みという形になりますけれども、システムの開発関係で６,９４０万円ほどを予定しております。おおよその決算見込みが出ているところでございまして、都合３年間で、約３億６,５００万円という形になります。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり情報漏えいの危険はもちろん、３年間で３億円を大きく超える予算をかける、そもそも人に番号をつけるというのもけしからん話だと思いますけれども、マイナンバーはやめるべきだと思いますので、中止を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"あべ委員","kind":"質問","question":"先ほどの発行業務の件数なのですけれども、それぞれお答えいただいたのですが、今、年間で、それぞれ何通発行されているのかということと、それぞれ今、窓口の場合は手数料がいくらかということをお伺いします。","respondent":"仁平情報推進課長","answer":"一応、見積り上、証明書送付件数の１０％というふうに見込んでいるところです。こちらも同じく１０％を予測にして見込んでおりますので、１万８,０００通という形になりますので、２万５,４００通の約１０倍という形です。","id":"exchange-049"},{"speaker":"あべ委員","kind":"質問","question":"それぞれありがとうあります。コンビニで行う場合は１通２００円というふうになっているのですが、この差額の根拠というのはどのような考え方によるものか尋ねました。","respondent":"仁平情報推進課長","answer":"現在、窓口ですと３００円ということになりまして、条例のほうで２００円。２００円にしたというのは、促進していきたいという思いと、そういう意味も含めまして２００円という形をとったというような話を聞いております。","id":"exchange-050"},{"speaker":"あべ委員","kind":"質問","question":"先ほどの１万５,０００通、計２万５,４００通ですか。一方で、コンビニでの利用を促進するために、本当はもっと手数料としてはかかるのだけれども、あえて政策的に安くしているという意味なのか尋ねました。","respondent":"仁平情報推進課長","answer":"これは一応、歳入の２００円のほうも見込んで、持ち出し分を割り出した数字としての形になります。それと手数料の２００円なのですが、その額の決定自体は私のほうではございませんので、立場上ちょっとお答えが難しいです。","id":"exchange-051"},{"speaker":"あべ委員","kind":"質問","question":"これは同額３００円でも十分なのではないかと。より、これを２００円にしなければいけない理由が私にはわからないのですけれども、その辺はどうなのか尋ねました。","respondent":"中山企画部長","answer":"今のも理由についてご説明している部分があって、私もそこまで細かく、所管として周知しているわけではありませんけれども。１つは、１つはそういうところに、より身近なところで出せるということも含めた誘導を考えていく中で設定したものです。","id":"exchange-052"},{"speaker":"あべ委員","kind":"質問・要望","question":"行政としてどういう価格設定、手数料設定をしていくかというのは、ぜひ常に見直しながら進めていってほしいと求めました。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"吉田委員","kind":"質問","question":"今利用されているものの１割程度というお返事だったと思うのですけれども、ということは、１５万件ぐらいということでよろしいのでしょうか。ちょっとごめんなさい、その数字だけ、まず。","respondent":"柏原企画調整課長","answer":"見込みとしては、１０％程度ということで見込んでおりますので、住民票については１万５,０００通を見込んでいますけれども。今、年間で想定している数字というのはそういうことでご理解いただきたいと思います。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問","question":"それなので、ちょっと数を伺いました。それと同程度ということですが、パスワードの設定のやり方とか、そういうのはどういうふうに考えていらっしゃるのか、その２つを説明を求めました。","respondent":"柏原企画調整課長、仁平情報推進課長","answer":"それを行うためには、そういった推移を見ながら、どのぐらいの利用者が出るのかというのを見ながらというところであろうと思います。昨日、同様の議論のほうがあったかどうかちょっとわかりませんけれども、私どもはそういう考え方… ４桁パスワードの変更なのですが、検討されているかどうかまではちょっと承知していないのですけれども、そういう世界も考えられなくはないかというように考えているところです。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問","question":"だから、割と少数の人が何回も必要になるのだけれども、普通、どうなのでしょう、区民全体の利便性ということでは、これはどうなのだろうかと。税を投入するということは区民全体、その辺のお考えを伺いたかったのですが、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"それは先ほどの予算の話のもちょっと出ましたけれども、年間何十万通という形で出るようなものですので、やはり相当の数の方がご利用されている。","id":"exchange-056"},{"speaker":"あくつ副委員長","kind":"質問","question":"区民委員会、昨日審議されたということで、切り分けは難しいのですが、ちょっと情報推進の観点から、同じ質問かもしれませんけれども。２３区としては、そういうことをどういうふうに取り入れ、ここについて伺いたいと思います。","respondent":"仁平情報推進課長","answer":"区のほうも検討はしたのですが、個人番号カードを取得されても、交付できるのがその全体の４割ぐらいになるという話です。品川区のほうも、国のほうの動きを見て、また改めて検討していきたいという話がございました。","id":"exchange-057"}]},{"id":"topic-05","title":"区立公園におけるフリーＷｉ－Ｆｉサービスの運用開始","agenda":"区立公園におけるフリーＷｉ－Ｆｉサービスの運用開始","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"駅前でＷｉ－Ｆｉが設置されて、これからする、それはちょっとどこだったかと思ったのが１つと。駅前が混み合いますので、そういう視点というのはどういうふうに検討されているのか、そこを伺いたいと思うのです。","respondent":"仁平情報推進課長","answer":"次の主要駅ということでの整備を予定しているところでございまして、順次、フリーＷｉ－Ｆｉのほうを展開していきたいと考えているところです。ちょっとやり方、費用のかけ方等も含めまして、順次検討していく予定としております。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"例えば、オリンピックをどうすれば、当然、オリンピックの会場や、そこに向かう道や。あまり予算にかかわらないように、今後どういうふうに展開があるのか、もう少し伺えたらと思うのですけれども、質問します。","respondent":"仁平情報推進課長","answer":"それは進めていくという形になっておりまして、各都内を走っております鉄道事業者等への働きかけ等を行っているという話を聞いております。は区の関係の施設、この辺をちょっと主眼にして、整備を検討していこうかと考えているところであります。","id":"exchange-059"},{"speaker":"あべ委員","kind":"質問","question":"１回６０分の回数制限なしと、同じように運用されると、大変パンクしてしまうのではないかと思ったりもします。災害時は別の運用方法があるのか、そのあたりを説明を求めました。","respondent":"仁平情報推進課長","answer":"１日当たりでは回数の上限なしというような設定になっておりますけれども、災害時は、そういうサービスに切り換えるというような形になっております。","id":"exchange-060"}]},{"id":"topic-06","title":"障害者差別解消法施行に向けた区の体制","agenda":"障害者差別解消法施行に向けた区の体制","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"本部会議というのでしょうか、何人ぐらいのメンバーで行われるのか、そこを伺いたいと思います。しっかり聞き取るということが大事だと思うのですけれども、その点について、どういう位置づけか伺いたいと思います。","respondent":"米田人事課長","answer":"これは部長級職員を、各部の部長もほぼ入れてというような形で考えておりますので、そういうものが数回開かれるであろうというふうに考えてあります。","id":"exchange-061"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えばこの１年間でどういう取組みや、どういう議論や経過があったのか、そういう報告書というのでしょうか。そういうものというのは年度末にお考えなのか、こういうものが必要ではないかと思うのですけれども、現状を伺いたいと思います。","respondent":"米田人事課長","answer":"基本的には職員がきちんと対応できるというようなことの、あるいは啓発活動というようなところだろうというふうに考えているところです。","id":"exchange-062"},{"speaker":"あべ委員","kind":"確認","question":"確認なのですけれども、この体制はこれからつくるということなのですか。職員対応要領もこれから作成するということなのか尋ねました。","respondent":"米田人事課長","answer":"既に勉強会という意味合いでは会議のほうを開いて、２８年４月に向けたということでの動き方については、確認をとっているところです。職員対応要領というものにつきましても、先行して国の省庁等で対応要領というものが示されておりますし、対応要領。","id":"exchange-063"},{"speaker":"あべ委員","kind":"質問・要望","question":"他区を見ても、４月までやってはいけないというものでもありませんし、ちょっとそのスケジュール感をもう一度確認したい。今後も行うべきことが、継続して広げていっていただきたいと思うのですが、今後のお考えについて説明を求めました。","respondent":"米田人事課長","answer":"職員対応要領を策定するに当たっては、障害者の方と対応しているときに、対応方針について。当然、例えば障害者差別解消支援地域協議会等の会議体等で出たご意見等を踏まえ、こちらについては見直しを図っていくつもりでいるところです。","id":"exchange-064"},{"speaker":"本多委員","kind":"質問・要望","question":"こういう機会ですから、こういう組織が立ち上がるわけですから、全職員に見ていただきたいと思っています。間違いなく高まると思いますので、そういった視点を持っていただきたいというところだけ、一言ほしいと求めました。","respondent":"米田人事課長","answer":"こちらのほうでもある程度具体的なものとしての検討を始めているところですが、委員より今ご指摘のありましたものも含めて、どのような形で職員に働きかけるのが有効かということを改めて考えてまいりたいと思います。","id":"exchange-065"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、この職員研修が、既にいろいろ考えられていると思いますけれども、具体的にどういう形で、今、映画のこともありましたけれども、どういう内容で行われているのか、もしくはこれから行おうとしているのか、そのプログラムなどがあれば教えてほしいと求めました。","respondent":"米田人事課長","answer":"お話がありましたように、集合形式で、識見の高い方からのお話をいただくであったりということも当然考えているところです。やはり最初に窓口対応等をするに当たって、職員同様にやはり大事だと考えていますので、考えているところです。","id":"exchange-066"},{"speaker":"吉田委員","kind":"質問・要望","question":"割と、障害者７団体の代表の方に、どこどこ協議会とかに参加していただいて伺っていますというお答えが多いような気がします。もしくはこれから検討をする余地はあるのかどうか、その辺のお考えを伺いたいと思いますが、いかがか尋ねました。","respondent":"米田人事課長","answer":"対応という言葉が出てきておりますけれども、当然、対応要領は努力義務ということなので定めていこうというふうには考えてはありますが。絶えず見直してまいりたいと思います。","id":"exchange-067"},{"speaker":"吉田委員","kind":"質問・要望","question":"３階の受付を入ってエレベーターの向かい側にあるトイレ、だれでもトイレというのでしょうか、大人の。もし、その点について、何か見解がありましたら、説明を求めました。","respondent":"米田人事課長","answer":"いわゆるこちらで本文にありますほうの相談対応というところでの強化ということで、あるいはご心配事も含めた相談対応の強化ということは、充実に努めていくということについては変わりないというふうに思ってあります。","id":"exchange-068"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"非常にご苦労されて晴れ着を着て伺って、一生に一度の機会が、本当に台無しになってしまったということで。非常に人がごった返している中ですから、心肝に染めるような研修をやってほしいと求めましたが、そこのところをお願いしたいと思います。","respondent":"米田人事課長","answer":"私のほうからお答えしますけれども、やはり職員の対応について、法の趣旨を十分に理解した対応をしていかなければならないと考えています。今、ご指摘の部分も踏まえまして、また職員の教育というものを充実させていきたいというふうに考えてあります。","id":"exchange-069"},{"speaker":"あくつ副委員長","kind":"質問","question":"誠実なご答弁だと思いますし、取り返しのつかないことってあると思います、一生に一度のことですから。ぜひそういったことが二度とないようにお願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"あべ委員","kind":"質問","question":"やっているのならありがたいのですし、ぜひやってほしいということで伺います。ハード面と、それからここは役所なので、制度面のバリアフリーというものも、合わせて考える仕組みになっているかを説明を求めました。","respondent":"米田人事課長","answer":"その辺のところの対応は、努力義務であったりするのですけれども、そちらのやり方ということはそれぞれ行っていく必要があるだろうと思います。","id":"exchange-071"},{"speaker":"あべ委員","kind":"質問・要望","question":"、それぞれ進めてほしいと求めました。初めて検討するということではなくて、やはりそれは積極的に、自らどこに課題があるかという視点をもってやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"}]},{"id":"topic-07","title":"選挙人名簿の登録に関する公職選挙法の改正","agenda":"選挙人名簿の登録に関する公職選挙法の改正","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"参考までに、品川区で該当のようなケースというのはどのくらいあったかどうかみたいなことは、特には把握はされていないでしょうか。多分１８歳になってから、１８歳に選挙権後はとても大きい区分になると思うのですけれども、参考までにわかれば。","respondent":"工藤選挙管理委員会事務局長","answer":"委員ご指摘のとおり、二十歳になってすぐ選挙が執行された場合には、その期間が３ヶ月なければ投票できなかったということがあります。そうしますと、大体１５０名前後が、今回の法改正で救われるのではないかというふうに思っているところです。","id":"exchange-073"},{"speaker":"中塚委員","kind":"質問・要望","question":"大変基本的なことで申し訳ないのですけれども、これは１８歳と１９歳だけということなのでしょうか。その辺の仕組みがちょっとよくわからなかったので、ご説明ほしいと求めました。","respondent":"工藤選挙管理委員会事務局長","answer":"もう１つ、旧住所地での居住期間が３ヶ月を経過してから初めての定時登録の前に転居をして、いずれもできないようなケースがございました。こういった形だという、いろいろなパターンを示しまして、わかりやすいような形で周知をしていくところです。","id":"exchange-074"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"東品川などにはそういうご要望もあります、大きなショッピングモールがありますので、それが１点。この２点をお伺いしたいと思います。","respondent":"工藤選挙管理委員会事務局長","answer":"その辺を総合的に検討しながら、私どものほうでも、引き続き検討はしてまいりたいというふうに思っているところです。そういった事例も検討はしてまいりますが、やはり一番は、選管がというよりも、事情を聞きますと、大学のほうからというのがまず１つあるということ。","id":"exchange-075"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"ぜひ、最初の投票所の件については、若い方への投資ということで、検討を続けてほしいと求めました。私どもも、しっかりそれは監視をしていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"中塚委員","kind":"質問・要望","question":"国立大学の値上げについて、共産党が出したビラをデマだと断定したのは事実でないので、発言の訂正を求めたいと思います。それは政治ですから、発言の訂正を求めたいと思いますけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"あくつ副委員長","kind":"質問","question":"訂正をしているということは、間違いを認めたということではないのですか。だから私は、発言を訂正をする必要もないし、そのつもりもありませんが、という考えです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"中塚委員","kind":"確認","question":"経過については、冷静に後で私もきちんと確認したいと思いますけれども。事実関係については、後でしっかり確認をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701406?Template=document&Id=2040#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":75092,"voices":187}},{"id":"h28-20160224-14","meetingId":"h28-cm02","date":"2016年2月24日","dateIso":"2016-02-24","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ０時２７分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件整理しています。","topics":[{"id":"topic-01","title":"国家戦略特区に関すること","agenda":"国家戦略特区に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"特区活用で区の方針として発表されておりますが、その先については何カ所の検討があるのでしょうか、１点伺います。この特区活用の具体化待ったなしかと思いますけれども、その点も伺います。","respondent":"柏原企画調整課長","answer":"条件等々その他いろいろありますので、幾つか候補を挙げて、それについて検討しているといった状況です。それからこの４月には公有地も使ったところでの動き等々ありますので、様々な手法を使いながら、こういったところを進めていきたいと思ってあります。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"質問したところで、何カ所の検討ということだと、幾つかということでしたけれども、何カ所の検討なのかというのをお伺いしたいと思います。今の現行計画、平成２９年の４月開設だったと思うのですけれども、そこら辺の心配はないのかもあわせてお伺いします。","respondent":"柏原企画調整課長","answer":"何カ所か、幾つか候補を挙げて、内容について検討しているといった状況です。少し私の説明不足だったかもしれませんが、これが３月中の開催ということであれば、大きな遅れは出ないだろうと考えています。","id":"exchange-002"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"国家戦略特区の話で来て、羽田空港跡地の、さっきいろいろ話が出たのですが、ここはアジアヘッドクォーターではなかったのですか。要は、都市計画の中でアジアヘッドクォーターを使って様々に展開していくということとの整合性が、どこにあるのかなというのだけ説明を求めました。","respondent":"柏原企画調整課長","answer":"国家戦略特区の場合ですと、もちろん外国人の方の起業というところも入ってございまして、より幅広い形で網がかかっているというところがあります。","id":"exchange-003"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"なぜこんなことを聞くかというと、やはり意見は言うべきで、一緒にやりましょうというのを考えているわけではないですか。品川区でもこのことについてはしっかり押さえておくべきだと思っているのだけれども、そこら辺の感覚はどうなのかというのを教えてもらいたいです。","respondent":"柏原企画調整課長","answer":"ご説明、見直しといいますか、というのをかけたいという話も聞いてあります。それは東京都、それから大田区もそうですけれども、情報共有等々しながら進めていければと思ってあります。","id":"exchange-004"}]},{"id":"topic-02","title":"公有地・跡地活用に関すること","agenda":"公有地・跡地活用に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"１番の品川第二寮ですけれども、日本ペイント近くの南品川にあるところですが、都営住宅に隣接している敷地だと思うのですけれども、今、一回社会福祉法人から申し出があったのだけれども辞退したということですが、現在に至るも売却先が未定となっている大きな理由は何なのかを伺います。","respondent":"柏原企画調整課長","answer":"そこの今国が持っている用地以外の部分の用地を取得なりしないと、大きなというか、特殊建築物が建てられないという現況があります。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"今のお話も伺って、ましてやいろいろな住民要望がある中ですから、そうした姿勢が私は必要だと思うのです。東京都に対して取得を求めて、そうした活用を求めるべきだと思うのですけれども、区の考えはいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"前回この品川第二寮の検討をした際も、東京都に打診といいますか、話をしたところです。民間が活用できませんので、現在のところでは、ここを取得というのはなかなか難しい状況かなと思ってあります。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"第二寮敷地も取得して、改めて区営住宅として戸数を増やすとか、区民の利益にとってプラスになる活用というのは私は可能だと思うのです。隣も取得して、区営住宅としてさらに増設することを検討すべき時期だと思うのですけれども、改めて伺います。","respondent":"柏原企画調整課長","answer":"都営住宅前の物件につきましては、耐震改修を行うというタイミングがあったというところで、すぐの移管は難しいという話を聞いてあります。１年、２年前ですか、区としては考えていないといったところです。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"３番目の旧参議院会議等施設なのですが、法人への貸与・売却とありますけれども、どんな法人からどんな用途で使用する話が来ているのでしょうか。ぜひ働きかけてほしいと求めましたし、丁寧に進めてほしいと求めましたけれども、こちらはいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"その交渉が至らなければ、次の段階で民間に入札という形になりますので、恐らくそういう準公共的な団体とお話をしているのだろうです。進行状況については機会を得て確認をとっているところなのですが、現況ではそういった状況です。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"上大崎寮に関しては、迅速な働きかけと丁寧な説明をお願いしたいと思います。ぜひ区としても後押しできるところがあれば、していただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"横山委員","kind":"質問","question":"１点、上大崎寮の部分でご質問します。今２月ですので、確定のものではなくて、通常どういった形でこういったケースを進めていかれるのかというところだけ教えていただけたらと思います。","respondent":"柏原企画調整課長","answer":"やりとりをしていくという形になりますけれども、全体としては２年間の間の中で契約をしてくださいという決まりになっています。年度明け、どういうタイミングで来るかによって、スケジュール感がまた少し変わるという状況です。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問","question":"今回には当然入れていないということと、それから、願わくば来年の４月には開設できればいいなと。一応、この中では保育園という話を聞いているのですけれども、その辺のスケジュールを説明を求めました。","respondent":"柏原企画調整課長","answer":"我々としても妥当性といったところも検討しなくてはいけない部分がありますので、平成２８年度がそれに対する大詰めになろうと思ってあります。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"品川第二寮のほうで、対象になるものとならないものがあるということでしたけれども、どういった基準があるのか。それと、今回の第二寮がそれに当たらない理由を伺いたいと思います。","respondent":"柏原企画調整課長","answer":"平成１２年のときの都区の移管のときの合意といいますか、都営住宅で１００戸未満のものは、基本的には区に移管だという方針を都は出しています。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"すぐには無理だということでしたけれども、ぜひ区でも、移管も含めて検討していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-03","title":"羽田空港の機能強化に関すること","agenda":"羽田空港の機能強化に関すること","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"すみません、今、最後におっしゃっていただいたところで、そうすると、ミニオープンハウスが開かれるというのは、何か地域の方からの要望を受けてやるということになったのか、国交省からそこをピンポイントで選んでやるというふうになったのか、説明を求めました。","respondent":"三ツ橋環境課長","answer":"夏にやはりミニオープンハウスを開催いたしまして、そのときも、この南大井文化センターと品川保健センターでございました。一番影響が大きいであろうと思われる地域を対象にしておりまして、今回もそのことを国交省が考えて、今回ミニオープンハウスとなっております。","id":"exchange-014"},{"speaker":"大倉委員","kind":"質問","question":"先ほどのミニオープンハウスの日程をもう一度教えてください。書いてあるのかと思って聞き漏らしてしまったので、お願いします。","respondent":"三ツ橋環境課長","answer":"３月５日（土）が南大井文化センターで開催されまして、時間が１３時から１７時です。次の３月６日（日）ですが、こちらは品川保健センターで開催されまして、１３時から１７時です。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問","question":"先ほど、この下に書いてある主な意見等というところで、区の職員が聞き取ったものということでしたけれども、そこに「区の方針は？」と書いてあるのですが、これについてはどういった答えをしたのか尋ねました。","respondent":"中村都市計画課長","answer":"区の方針としましては、引き続き国に求めていると、そういう姿勢を今のところ続けております。それを踏まえて、区としてまた必要な対応について求めるかどうか、その辺を検討していくです。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問","question":"本会議場でも第２フェーズの説明について質問が行われまして、今のご回答だと、周知について十分ではないと考えているということでしょうか。これで住民の不安や怒りに答える具体的な対策が示されたとは思っていませんが、区はどう考えているのか伺います。","respondent":"中村都市計画課長","answer":"そのほかの対応策につきましても、こういったものについての対策も、これで万全というものはないと考えています。対応について十分ではないというところは、国には常にこれからも求め続けていくという姿勢を区としては貫くべきと考えています。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"まさにそのとおりであって、これからも求めていくということですけれども、説明が不十分のまま決定することは許されないと考えています。第２フェーズが終わった今こそ、品川区が反対表明していただきたいと思っているのですけれども、区はいつになったら反対表明するのか尋ねました。","respondent":"中村都市計画課長","answer":"国では今後、具体的な対応策について明らかにしていくと言っていただいております。そういう回答が得られたですけれども、ただ、まだその対応策について具体的に示されたわけではございませんので。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問","question":"この具体的な対応策が示されなかった場合は、区は反対するのか尋ねました。","respondent":"中村都市計画課長","answer":"具体的な対応策の中身によりますので、反対あるいは賛成という具体的な回答は、今のところできませんけれども、ただ対応策も、先ほど申し上げましたけれども、これで万全ということはございませんので、引き続き国と協議を進めていくという形になろうかと思います。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ協議を続けていって、具体的な対応策を示されなければ、品川区として、一番被害を受ける自治体になると思いますので、反対の立場に立っていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"確認","question":"今の質疑の中で確認だけしたいのですけれども、例えば前の行革委員会で確認した記憶はないのだけれども、品川区が仮に航空機はうちの上空を通るなと、それを決めたところで、その権限が実際に及ぶのでしょうかの確認をお願いします。","respondent":"中村都市計画課長","answer":"法律に定められた範囲の中では、品川区の上空を飛ぶことについて、違法ではないという見解になってあります。国の見解はそういったところです。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"確認","question":"もう少し確認したいのが、ヘリコプターも飛ぶだろうし、いろいろな飛行機が飛んでくる。これを物理的に止めることはできないと思うのですが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"区としてはそういう態度をとるべきではないと考えておりますので、今、必要な協議を進めているところです。引き続き、区として可能な限りの協議を進めてまいりたいと考えております。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問・要望","question":"品川区の要望を伝えて、そして様々な解決策を具体的に導き出していくことのほうが、より現実的で具体的な成果を出すことにつながると思うのです。具体的に区民の皆様に直接かつ影響があることは事実だから、それに対する果実を得られないと思うのですが、改めてその答弁をお願いいたします。","respondent":"中村都市計画課長","answer":"現在、品川区として区民に対する説明を求めてきたところで、現在のところは説明会等も開催していただいていると考えております。ただ、このまま強硬的に何の対応策もないまま飛行するということがないように、協議の場から離れないように進めてまいりたいと考えています。","id":"exchange-023"},{"speaker":"塚本委員","kind":"質問","question":"先ほどご案内のあった３月５日と３月６日のミニオープンハウスということなのですけれども、会場が狭いとか、何かそういうことなのでしょうか。ミニと言っていることの理由というか、裏づけみたいなことをお伺いしたいのと、この周知ですね、今から２週間後ぐらいか尋ねました。","respondent":"三ツ橋環境課長","answer":"例えば国の説明の人員が若干少なかったり、また品川の周辺であったりというふうに、力を入れている部分です。今回の３月５日と６日の部分に関しましては、２月５日の回覧板では既に回覧しておりますので、その近辺の部分では周知はしております。","id":"exchange-024"},{"speaker":"塚本委員","kind":"質問・要望","question":"ご説明ありがとうございました。そこには一層力を入れていただいて、周知の徹底化を進めてほしいと求めましたので、よろしくお願いをいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"松永委員","kind":"質問・要望","question":"フェーズ１で要望を受けた中で、またこの第２フェーズの主な意見等の中で、区はそのように捉えているのかなと思います。その１番目に、前回の要望に対する国からの回答が示されない、こういうのは今後どのような形になっていくのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"いまだに行われていないというのは、品川区の要望が届いていないということだと思うのです。ゆゆしき事態ではないかと思うのですけれども、これは国が品川区の要望を聞いていないということになるのではないですか、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"ですので、規模の大小を問わず、引き続き教室型の説明会については求めてまいりたいと思います。そういった意味で、引き続き要望をしてまいります。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"フェーズ２として、皆様のご意見を伺いながら、さらに求めていくということだと思います。とありますが、模索というのは対策ではないと思うのですけれども、模索が対策だと思うかどうかも伺います。","respondent":"中村都市計画課長","answer":"模索ですけれども、この模索は、言葉としては委員ご指摘のように、あくまで具体的な対応策を示したということにはならないと思います。これは検討という言葉が、むしろ近いのかなと解釈をしております。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"それに続いて、現在のところＰＭ２.５については規制基準がないけれども、ＰＭ２.５の検討については求めていきたいということも言っております。区のこれまでのお考えを照らしますと、そう思いませんでしょうか、伺います。","respondent":"三ツ橋環境課長","answer":"それとも通常の状態のＮＯｘからのＰＭ２.５なのか、実際にはＰＭ２.５のその部分が何から来るのかというのが、なかなか難しいと考えています。引き続きＰＭ２.５というものに関しましてはデータとして、特にＰＭ２.５もそうですけれども、引き続き申し入れてまいります。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"国が新たなルートを設定するわけですから、それを求めていく必要があると思いますけれども、国はこんな説明です。そこら辺を求める考えはあるのかどうか、合わせて伺います。","respondent":"三ツ橋環境課長","answer":"なかなか大気汚染のＰＭ２.５というものも、それとも実際あの自動車からなのか、その部分のすみ分けというのも非常に難しいとは思っております。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"落下物は、成田空港では１０年間で１８件と書いていますけれども、そういうふうに思いませんでしょうかというのが１つの質問です。あわせてこちらについても区の見解を、見過ごせない重大な数字だと思いませんか、伺います。","respondent":"中村都市計画課長、三ツ橋環境課長","answer":"この辺は区からの要望に対しても、国は整備だとかそういったところで十分な措置を行っているという説明をしていただいているところです。年々減少はしていくというところで、これがゼロにしていただくまで… 先ほどの大気汚染のデータですけれども、今までも大気汚染のデータにつきましては環境課、区のホームページ上で情報を開示しておりますので、引き続き情報公開してまいります。","id":"exchange-031"},{"speaker":"安藤委員","kind":"提案","question":"いかがでしょうかと、そう思いませんかということをお伺いしたので、改めてこちらについてもお伺いします。冊子にも載っていますけれども、新飛行経路の午後の運用時間（１５時～１９時）は守られるのですかと率直に質問して、それが冊子に載っておりますとの意見を述べました。","respondent":"中村都市計画課長","answer":"国としても引き続きしっかりと対応してまいりますというふうに、区からもお願いをしている際に、そういったやりとりもあります。ないと考えております。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"区長はなぜ参加をしたのでしょうか。それを伺いたいと思います。","respondent":"中村都市計画課長","answer":"オープンハウスでもそんな説明もございましたので、現在、区としてもその時間帯が守られると考えて、今後の協議を進めてまいりたいと考えています。それから区長の説明会の視察ですけれども、そういった説明会が行われているということであれば、当然のことだと考えています。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"先日、日曜日に、品川区民の住民団体の皆さんが計画撤回を求めるデモ行進がありました。現行計画撤回に向けて区民運動を起こすことを求めていきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"天王洲からで３５０ｍぐらいだとして、４００ｍぐらい逆に振れるというと、肌の感覚でわかるではないですか。何かそういう資料をつくるように言っていただけないですかね。","respondent":"三ツ橋環境課長","answer":"今回の第２フェーズにつきましては、もっと品川区のイメージというものを要求していきたいと思っています。はっきりどの程度のものなのかというのも知識的にもよくわかりませんので、実際に区として、国に対して要望はしてまいりたいと考えています。","id":"exchange-035"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"計画案が出てくるのかどうか、それが８月かどうかわかりませんが、これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これを品川区に求めても、どうしようもない話だと私は思うのです。そういうふうにしていったほうがいいと思うのですが、改めてお願いですが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"今後、国から具体的な対応策が示されるに当たりまして、区としてはやはり最大限、国が品川区に対して対応をしていただくように、引き続き協議を進めてまいります。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"先ほど市街地上空を飛行機が飛ぶことは違法ではないというお話でしたけれども、違法でないと区は反対の表明というのはできないのでしょうか。制度上のお話をお聞きしたいと思います。","respondent":"中村都市計画課長","answer":"区としましては、違法ではないとか違法だというところとは、直接区の対応は関係ないと考えております。今回の場合は、まだ国として対応策が示されていない中で、結論を出すのはまだ区としてはといったところで、結論を出せないという意味です。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"今はまだ結論は出せないということでしたけれども、ぜひ、首相も地元の理解を得てルート変更も考えていくと言っておりますので、やる前から諦めずに、品川区がぜひ反対の立場に立ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"一般質問で昨年の１２月と、新ルートの下にある施設について伺ったのですが、具体的な施設名についても先日の一般質問で伺いましたが。具体的な施設名を伺いたいと思います。","respondent":"三ツ橋環境課長、藤田都市環境部長","answer":"実際に答弁のときには、大井地区５６件、八潮地区１４件、品川地区３１件と申しております。一応、新たなルート案の下の地区にある一定規模以上の公共施設や病院については、多数ありますので、個々の名称は差し控えます。飛行ルートの明確な位置が国としてはっきり示してくれていないということと、その影響範囲がどの程度に広がるかというのがはっきりわからないのです。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問","question":"そこら辺がわからなかったので、お伺いしたいのが１点あります。品川区は、ここでいう今回の新ルートで最も大きな被害を受ける、安倍首相が言うところのまさに地元に当たると思うのですけれども、いかがか尋ねました。","respondent":"三ツ橋環境課長、中村都市計画課長","answer":"八潮地区１４件、品川地区３１件というのは、別に全然違うものということではございません。 今現在飛んでいなかったところに、新たに飛行経路となるということに関しましては、品川区は当事者であり地元であるという認識です。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"それは区に求めたいのですが、委員長、いかがでしょうかというのが１つです。地元である品川区が理解を示さない限り、計画は進まないと考えてよろしいのかどうか、伺います。","respondent":"中塚委員長、中村都市計画課長","answer":"初めに、資料の取扱いについては、正副で調整したいと思います。 品川区としましては、区の理解をもって進めていただくように、国に引き続き求めていく所存です。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"区の申入れにより、昭和４０年に当時の運輸省が航空会社に対し、モノレールより海側を通るよう要請しましたという答弁をしています。伺いたいのは、何を成果として上げてきたのか、そうした区の認識を伺いたいと思います。","respondent":"中村都市計画課長","answer":"一つ大きくは、国に対して説明会の開催等、こういった区民に対する理解を深めていただくようなことをしていただくように求めてきたところです。対応策についてですが、これは具体的にこれから第２フェーズの後、夏までにですので、これについてはまだ引き続き継続中です。","id":"exchange-043"},{"speaker":"安藤委員","kind":"提案","question":"私が伺ったのは、今回の新ルートの提案というのはこれまで、そういうふうに思いませんでしょうか。そして重大な方針転換だと、約束違反だとも言えるのではないかと思うのですけれども、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"昭和４０年代から始まりました飛行経路についてですけれども、今日まで品川区内を最終的には飛行しないところまで持っていたところです。これについて検討するというのは、提案があったものに対して検討するというところで、必要な検討であると考えております。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問・要望","question":"一般質問で私たちが聞きましたけれども、人口密集地を低空で飛ぶこの新飛行ルートは、海外を含めてほかに例があるのですかと聞きました。伺いたいのは、ほかにあるのでしょうか、伺います。","respondent":"三ツ橋環境課長","answer":"委員が言われました人口密集地を低空で飛ぶ飛行ルートということに関しましては、国の資料によりますと、ロンドンのヒースロー空港、ニューヨークのラガーディア空港、大阪伊丹空港、福岡空港などを示しております。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"東京２３区における、区の認識を改めて伺います。１,２００万人の方が、区としてはどのように思っているのか、伺います。","respondent":"三ツ橋環境課長","answer":"伊丹であったり、福岡などを人口密集と呼ぶといたしましたら、そのようなものと考えております。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"飛ぶ地域というのは、今回の例というのは、では世界で一番最大の人口密集地を飛ぶ計画ということなのでしょうか。様々あります、ヒースローや伊丹などありますが、挙げられた例の中で比べても、一番密集している人口地を飛ぶという計画でよろしいのか尋ねました。","respondent":"中村都市計画課長","answer":"密集の度合いにつきましては、例えば他都市におきまして、では密集していなければいいのかといったことにもなるかと思いますので、密集そのものの度合いで経路の検討の結論が変わってくるということはございませんので、回答は差し控えるべきと考えております。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは、純粋にどういった計画なのかということを把握する上で、回答を差し控えるべきものではないと私は思います。ぜひ示していただきたいのですが、一番人口密集地を飛ぶという計画でよろしいのでしょうか、伺います。","respondent":"中村都市計画課長","answer":"そういった意味からしますと、まだ品川区内で算定できるものではございませんので、現在お答えすることができません。申し訳ございません。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"しかも第２フェーズの中で品川区の地図まで示されて、それでまだここを通るかどうかわからない、公表していただきたいと要望したいと思います。さらに物を申していくべきだと思うのですけれども、各委員の皆さんのご意見を伺えればと思うのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問・要望","question":"一定規模以上の施設を挙げたということですけれども、その一定規模以上というのはどういう基準で決めたのか。今回出した数字としては、ルートのどのぐらいの幅で出したのか、教えてほしいと求めました。","respondent":"三ツ橋環境課長","answer":"一定規模以上といいますのは、例えば病院をカウントするとしたら、どのくらいの規模の病院をカウントするのかとか、そういう具体的なものを考えましたところ、一定規模以上という文言を申しております。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問","question":"一定規模以上ということでしたけれども、何m2以上とか、そういったことも決めていると思うので、そこをお伺いしたいと思います。","respondent":"三ツ橋環境課長","answer":"m2数といいますか、今言いましたように、例えば病院でありますと病床数など、そういう部分に関係してきますので、m2数という具体的なものではない場合もあります。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問・要望","question":"様々な施設がありますので、資料をほかの委員が求めましたので、そこにもその基準がわかりやすくなるように資料を出してほしいと求めました。住民への被害も多大なものになると思いますので、請願の趣旨に賛同して、ぜひ採択を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"沢田委員","kind":"質問・要望","question":"まだまだ対応がとられていないという部分もありますし、また、それに対しての対策がどんな対策なのかというのがわからない状況であるということ。この騒音対策を求める意見書の中にもありますけれども、現在の段階では請願に対しては、継続で進めていきたいという思いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"たけうち委員","kind":"質問・要望","question":"理由につきましてはほとんど同じですが、第１・第２フェーズが終わって、一定程度の説明があるにせよ、まだ不十分なところがあると。今の段階で中止もしくは撤回ということについて判断をするというのは、非常に難しいということで、継続をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"結論を出すということでお願いしたいのですが、やはりこの時点でしっかりと採択をして、現行計画の撤回を区として求めていくべきだと思います。ましてや、まともな説明がないままに進めているのも論外ですということで、採択を私たちは主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"大倉委員","kind":"質問・要望","question":"我が会派としては、継続でお願いしたいと思います。その意見書の中でも様々求めていく中で、これからの国の動きをしっかり見ていく中で検討していくべきだと考えますので、継続でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"}]},{"id":"topic-04","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"国に対して３ヶ月ぐらいで回答しなさいということで、さらにそうした適切な時期に公有地情報を出してほしいという要請が必要ではないかと思います。特養ホームや認可保育園、公営住宅など、区民要望をかなえる立場に立つということが第一だと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"伊藤委員","kind":"意見","question":"それだけです。殊さらここに来て意見を追加することはしませんので、ぜひまとめてください、お願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/858443?Template=document&Id=6002#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":45129,"voices":134}},{"id":"h28-20160225-18","meetingId":"h28-cm02","date":"2016年2月25日","dateIso":"2016-02-25","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ３時０１分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/158474?Template=document&Id=6488#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":3783,"voices":13}}]);
